"""HTTP plumbing shared by the node server and the API (see CONTRACTS.md)."""
import json


class Request:
    def __init__(self, method="GET", path="/", query=None, headers=None, body=b"", node_id=0):
        self.method = method.upper()
        self.path = path
        self.query = dict(query or {})
        self.headers = {k.lower(): v for k, v in (headers or {}).items()}
        self.body = body or b""
        self.node_id = node_id

    def json(self):
        if not self.body:
            return {}
        try:
            return json.loads(self.body.decode("utf-8"))
        except Exception as e:  # noqa: BLE001
            raise ValueError("invalid JSON") from e


class Response:
    def __init__(self, status=200, body=None, headers=None, content_type=None):
        self.status = status
        self.body = body
        self.headers = dict(headers or {})
        self.content_type = content_type

    def encode(self):
        """Return (content_type, bytes)."""
        b = self.body
        if b is None:
            return self.content_type, b""
        if isinstance(b, (dict, list)):
            return self.content_type or "application/json", json.dumps(b).encode("utf-8")
        if isinstance(b, str):
            return self.content_type or "text/plain; charset=utf-8", b.encode("utf-8")
        return self.content_type or "application/octet-stream", bytes(b)

#!/usr/bin/env python3
"""Foreground supervisor: runs redis, three HTTP nodes and the IRC gateway; respawns anything that dies."""
import os
import signal
import subprocess
import sys
import time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PY = sys.executable or "python3"

SERVICES = {
    "redis": [os.path.join(ROOT, "bin", "redis-server")],
    "node0": [PY, "-m", "huddle.node", "--node-id", "0"],
    "node1": [PY, "-m", "huddle.node", "--node-id", "1"],
    "node2": [PY, "-m", "huddle.node", "--node-id", "2"],
    "irc": [PY, "-m", "huddle.irc"],
}

procs = {}
stopping = False


def spawn(name):
    log = open(os.path.join(ROOT, "data", "logs", f"{name}.log"), "ab", buffering=0)
    procs[name] = subprocess.Popen(SERVICES[name], cwd=ROOT, stdout=log, stderr=subprocess.STDOUT,
                                   env=dict(os.environ, PYTHONUNBUFFERED="1"))
    print(f"[supervisor] started {name} pid={procs[name].pid}", flush=True)


def shutdown(*_):
    global stopping
    stopping = True
    for p in procs.values():
        try:
            p.terminate()
        except Exception:
            pass
    deadline = time.time() + 3
    for p in procs.values():
        try:
            p.wait(max(0.1, deadline - time.time()))
        except Exception:
            p.kill()
    sys.exit(0)


def main():
    os.makedirs(os.path.join(ROOT, "data", "logs"), exist_ok=True)
    signal.signal(signal.SIGTERM, shutdown)
    signal.signal(signal.SIGINT, shutdown)
    os.chmod(SERVICES["redis"][0], 0o755)
    for name in SERVICES:
        spawn(name)
    while not stopping:
        time.sleep(0.5)
        for name, p in list(procs.items()):
            if p.poll() is not None and not stopping:
                print(f"[supervisor] {name} exited rc={p.returncode}; respawning", flush=True)
                time.sleep(0.2)
                spawn(name)


if __name__ == "__main__":
    main()

"""Durable per-channel event log + cluster fan-out entry points (see CONTRACTS.md).

* ``append`` runs inside the caller's ``BEGIN IMMEDIATE`` transaction and allocates a dense seq.
* ``publish`` / ``publish_global`` are fire-and-forget: inside a node process they hand the frame
  to the node's event loop (local delivery + Redis fast path); every node also tails the
  ``channel_events`` / ``global_events`` tables, so delivery survives a Redis outage and works even
  when called from a process that has no node running (e.g. unit tests).
"""
import json
import sqlite3
import threading
import time
from datetime import datetime, timezone

from huddle import config

PRESENCE_TTL = 8.0  # seconds; ws_presence rows older than this are ignored

SCHEMA = """
CREATE TABLE IF NOT EXISTS channel_events(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    channel_id INTEGER NOT NULL,
    seq INTEGER NOT NULL,
    type TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(channel_id, seq)
);
CREATE TABLE IF NOT EXISTS global_events(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS ws_presence(
    node_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    conn_count INTEGER NOT NULL,
    heartbeat_at REAL NOT NULL,
    PRIMARY KEY(node_id, user_id)
);
"""

_RESERVED = ("type", "seq", "channel_id")

# Set by huddle.node when running inside a node process.
_hub = None
_tls = threading.local()


def set_hub(hub):
    global _hub
    _hub = hub


def now_iso():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


def ensure_schema(conn) -> None:
    """Idempotent; safe inside an open transaction (does not commit)."""
    for stmt in SCHEMA.split(";"):
        if stmt.strip():
            conn.execute(stmt)


def _is_missing_table(e):
    return "no such table" in str(e)


def row_to_frame(channel_id, seq, kind, payload):
    frame = {"type": kind, "seq": seq, "channel_id": channel_id}
    try:
        data = json.loads(payload) if payload else {}
    except ValueError:
        data = {}
    for k, v in data.items():
        if k not in _RESERVED:
            frame[k] = v
    return frame


def append(conn, channel_id: int, kind: str, data: dict) -> dict:
    """Allocate the next dense seq for ``channel_id`` and persist the event.

    Must be called inside a write transaction opened with BEGIN IMMEDIATE.
    """
    channel_id = int(channel_id)
    data = {k: v for k, v in (data or {}).items() if k not in _RESERVED}
    payload = json.dumps(data, separators=(",", ":"), default=str)
    for attempt in (0, 1):
        try:
            row = conn.execute(
                "SELECT COALESCE(MAX(seq), 0) FROM channel_events WHERE channel_id=?",
                (channel_id,)).fetchone()
            seq = int(row[0]) + 1
            conn.execute(
                "INSERT INTO channel_events(channel_id, seq, type, payload, created_at)"
                " VALUES (?,?,?,?,?)", (channel_id, seq, kind, payload, now_iso()))
            break
        except sqlite3.OperationalError as e:
            if attempt == 0 and _is_missing_table(e):
                ensure_schema(conn)
                continue
            raise
    frame = {"type": kind, "seq": seq, "channel_id": channel_id}
    frame.update(data)
    return frame


def head_seq(conn, channel_id: int) -> int:
    try:
        row = conn.execute("SELECT COALESCE(MAX(seq), 0) FROM channel_events WHERE channel_id=?",
                           (int(channel_id),)).fetchone()
        return int(row[0])
    except sqlite3.OperationalError as e:
        if _is_missing_table(e):
            return 0
        raise


def _own_conn():
    """Per-thread connection for helpers that are not handed a connection."""
    path = config.DB_PATH
    conn = getattr(_tls, "conn", None)
    if conn is None or getattr(_tls, "path", None) != path:
        conn = config.connect()
        ensure_schema(conn)
        _tls.conn, _tls.path = conn, path
    return conn


def publish(frame: dict) -> None:
    """Fan a committed durable frame out. Thread-safe, non-blocking, never raises."""
    try:
        hub = _hub
        if hub is not None:
            hub.publish_threadsafe(dict(frame))
        # Without a hub (e.g. unit tests): the row is already committed in channel_events and
        # every running node tails that table, so nothing else to do.
    except Exception:  # noqa: BLE001
        pass


def _insert_global(frame):
    for _ in range(3):
        try:
            conn = _own_conn()
            cur = conn.execute("INSERT INTO global_events(type, payload, created_at) VALUES (?,?,?)",
                               (str(frame.get("type", "")), json.dumps(frame, default=str), now_iso()))
            return cur.lastrowid
        except Exception:  # noqa: BLE001
            _tls.conn = None
            time.sleep(0.05)
    return None


def _global_worker(frame, hub):
    try:
        gid = _insert_global(frame)
        if hub is not None:
            hub.publish_global_threadsafe(gid, frame)
    except Exception:  # noqa: BLE001
        pass


def publish_global(frame: dict) -> None:
    """Broadcast a non-channel frame to every WS client on every node. Never raises/blocks."""
    try:
        frame = dict(frame)
        hub = _hub
        if hub is not None and hasattr(hub, "submit_background"):
            hub.submit_background(_global_worker, frame, hub)
        else:
            threading.Thread(target=_global_worker, args=(frame, hub), daemon=True).start()
    except Exception:  # noqa: BLE001
        pass


def online_user_ids() -> set:
    """User ids with an open WebSocket on any live node."""
    ids = set()
    hub = _hub
    if hub is not None:
        try:
            ids |= hub.local_online_ids()
        except Exception:  # noqa: BLE001
            pass
    try:
        conn = _own_conn()
        rows = conn.execute("SELECT DISTINCT user_id FROM ws_presence WHERE conn_count>0 AND heartbeat_at>?",
                            (time.time() - PRESENCE_TTL,)).fetchall()
        local_node = getattr(hub, "node_id", None) if hub is not None else None
        if local_node is None:
            ids |= {int(r[0]) for r in rows}
        else:
            rows2 = conn.execute(
                "SELECT DISTINCT user_id FROM ws_presence WHERE conn_count>0 AND heartbeat_at>? AND node_id<>?",
                (time.time() - PRESENCE_TTL, local_node)).fetchall()
            ids |= {int(r[0]) for r in rows2}
    except Exception:  # noqa: BLE001
        _tls.conn = None
    return ids

"""Domain schema, per-thread connections, transactions and small shared helpers."""
