"""


class ApiError(Exception):
    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def now_iso():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


def iso_from_epoch(t):
    if t is None:
        return None
    return datetime.fromtimestamp(t, timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


_tls = threading.local()
_schema_lock = threading.Lock()
_schema_done = set()


def _is_busy(e):
    s = str(e).lower()
    return "locked" in s or "busy" in s


def _ensure_schema(conn):
    key = config.DB_PATH
    if key in _schema_done:
        return
    with _schema_lock:
        if key in _schema_done:
            return
        from huddle import events
        for attempt in range(50):
            try:
                conn.execute("BEGIN IMMEDIATE")
                try:
                    for stmt in SCHEMA.split(";"):
                        if stmt.strip():
                            conn.execute(stmt)
                    events.ensure_schema(conn)
                    conn.execute("COMMIT")
                except Exception:
                    conn.execute("ROLLBACK")
                    raise
                break
            except sqlite3.OperationalError as e:
                if _is_busy(e) and attempt < 49:
                    time.sleep(0.1)
                    continue
                raise
        _schema_done.add(key)


def get_conn():
    path = config.DB_PATH
    conn = getattr(_tls, "conn", None)
    if conn is None or getattr(_tls, "path", None) != path:
        conn = config.connect()
        _tls.conn, _tls.path = conn, path
    _ensure_schema(conn)
    return conn


def reset_conn():
    conn = getattr(_tls, "conn", None)
    _tls.conn = None
    if conn is not None:
        try:
            conn.close()
        except Exception:  # noqa: BLE001
            pass


class Tx:
    """``with Tx(conn) as tx:`` -> BEGIN IMMEDIATE ... COMMIT, then publish emitted frames.

    ``tx.emit(channel_id, kind, data)`` appends a durable event inside the transaction.
    """

    def __init__(self, conn):
        self.conn = conn
        self.frames = []

    def __enter__(self):
        delay = 0.02
        for attempt in range(40):
            try:
                self.conn.execute("BEGIN IMMEDIATE")
                return self
            except sqlite3.OperationalError as e:
                if _is_busy(e) and attempt < 39:
                    time.sleep(delay)
                    delay = min(delay * 2, 0.5)
                    continue
                raise
        return self

    def emit(self, channel_id, kind, data):
        from huddle import events
        frame = events.append(self.conn, channel_id, kind, data)
        self.frames.append(frame)
        return frame

    def __exit__(self, exc_type, exc, tb):
        if exc_type is not None:
            try:
                self.conn.execute("ROLLBACK")
            except Exception:  # noqa: BLE001
                pass
            return False
        delay = 0.02
        for attempt in range(40):
            try:
                self.conn.execute("COMMIT")
                break
            except sqlite3.OperationalError as e:
                if _is_busy(e) and attempt < 39:
                    time.sleep(delay)
                    delay = min(delay * 2, 0.5)
                    continue
                try:
                    self.conn.execute("ROLLBACK")
                except Exception:  # noqa: BLE001
                    pass
                raise
        if self.frames:
            from huddle import events
            for f in self.frames:
                events.publish(f)
        return False

"""Minimal asyncio HTTP/1.1 + RFC 6455 WebSocket client with node failover.

The IRC gateway is a pure client of the HTTP cluster: every REST call goes through
``Cluster.request`` which tries the nodes in ``config.node_ports()`` order (starting with the
last node that answered) and fails over when a node refuses, resets or times out.
"""
import asyncio
import base64
import json
import logging
import os
import struct
import urllib.parse

from .. import config

log = logging.getLogger("huddle.irc.client")

CONNECT_TIMEOUT = 2.0
REQUEST_TIMEOUT = 8.0


class NodeUnavailable(Exception):
    """No node of the cluster could serve the request."""


class HTTPResponse:
    def __init__(self, status, headers, body):
        self.status = status
        self.headers = headers
        self.body = body

    def json(self):
        if not self.body:
            return {}
        try:
            return json.loads(self.body.decode("utf-8"))
        except Exception:  # noqa: BLE001
            return {}

    def __repr__(self):
        return f"<HTTPResponse {self.status} {self.body[:200]!r}>"


async def _read_headers(reader):
    status_line = await reader.readline()
    if not status_line:
        raise asyncio.IncompleteReadError(b"", None)
    parts = status_line.decode("latin-1").strip().split(" ", 2)
    if len(parts) < 2 or not parts[0].startswith("HTTP/"):
        raise ValueError(f"bad status line {status_line!r}")
    status = int(parts[1])
    headers = {}
    while True:
        line = await reader.readline()
        if not line:
            raise asyncio.IncompleteReadError(b"", None)
        line = line.decode("latin-1").rstrip("\r\n")
        if not line:
            break
        if ":" in line:
            k, v = line.split(":", 1)
            headers[k.strip().lower()] = v.strip()
    return status, headers


async def _read_response(reader, method):
    status, headers = await _read_headers(reader)
    if method == "HEAD" or status in (204, 304) or 100 <= status < 200:
        return HTTPResponse(status, headers, b"")
    if "chunked" in headers.get("transfer-encoding", "").lower():
        chunks = []
        while True:
            size_line = await reader.readline()
            if not size_line:
                raise asyncio.IncompleteReadError(b"", None)
            size = int(size_line.split(b";")[0].strip() or b"0", 16)
            if size == 0:
                # trailers
                while True:
                    line = await reader.readline()
                    if not line or line in (b"\r\n", b"\n"):
                        break
                break
            chunks.append(await reader.readexactly(size))
            await reader.readline()
        body = b"".join(chunks)
    elif "content-length" in headers:
        body = await reader.readexactly(int(headers["content-length"]))
    else:
        body = await reader.read()
    return HTTPResponse(status, headers, body)


class Cluster:
    """Failover-aware REST client for the HTTP nodes."""

    def __init__(self, ports=None, host=None, timeout=REQUEST_TIMEOUT):
        self.ports = list(ports or config.node_ports())
        self.host = host or config.HOST
        self.timeout = timeout
        self._preferred = 0

    def order(self):
        n = len(self.ports)
        return [self.ports[(self._preferred + i) % n] for i in range(n)]

    def _mark_bad(self, port):
        if self.ports[self._preferred] == port:
            self._preferred = (self._preferred + 1) % len(self.ports)

    def _mark_good(self, port):
        self._preferred = self.ports.index(port)

    async def request(self, method, path, token=None, body=None, retry_after_send=None, rounds=3):
        """Perform a request, failing over between nodes.

        ``retry_after_send``: whether a request whose bytes were sent but whose response never
        arrived (node died mid-request) may be retried on another node. Defaults to True for
        idempotent methods.
        """
        method = method.upper()
        if retry_after_send is None:
            retry_after_send = method in ("GET", "HEAD", "PUT", "DELETE", "OPTIONS")
        payload = b""
        headers = {
            "Host": f"{self.host}",
            "Connection": "close",
            "Accept": "application/json",
            "User-Agent": "huddle-irc/1.0",
        }
        if token:
            headers["Authorization"] = f"Bearer {token}"
        if body is not None:
            payload = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        if body is not None or method in ("POST", "PUT", "PATCH"):
            headers["Content-Length"] = str(len(payload))
        head = f"{method} {path} HTTP/1.1\r\n" + "".join(f"{k}: {v}\r\n" for k, v in headers.items()) + "\r\n"
        raw = head.encode("latin-1") + payload

        last_exc = None
        for rnd in range(rounds):
            for port in self.order():
                try:
                    reader, writer = await asyncio.wait_for(
                        asyncio.open_connection(self.host, port), CONNECT_TIMEOUT)
                except (OSError, asyncio.TimeoutError) as e:
                    last_exc = e
                    self._mark_bad(port)
                    continue
                try:
                    writer.write(raw)
                    await writer.drain()
                    resp = await asyncio.wait_for(_read_response(reader, method), self.timeout)
                except (OSError, asyncio.TimeoutError, asyncio.IncompleteReadError, ValueError) as e:
                    last_exc = e
                    self._mark_bad(port)
                    if not retry_after_send:
                        raise NodeUnavailable(f"node {port} failed mid-request: {e!r}") from e
                    continue
                finally:
                    try:
                        writer.close()
                    except Exception:  # noqa: BLE001
                        pass
                if resp.status in (502, 503, 504) and retry_after_send:
                    last_exc = RuntimeError(f"status {resp.status}")
                    self._mark_bad(port)
                    continue
                self._mark_good(port)
                return resp
            if rnd + 1 < rounds:
                await asyncio.sleep(0.25 * (rnd + 1))
        raise NodeUnavailable(f"all nodes failed: {last_exc!r}")

    # convenience wrappers -------------------------------------------------
    async def get(self, path, token=None):
        return await self.request("GET", path, token=token)

    async def post(self, path, body=None, token=None, retry_after_send=False):
        return await self.request("POST", path, token=token, body=body if body is not None else {},
                                  retry_after_send=retry_after_send)

    async def patch(self, path, body, token=None):
        return await self.request("PATCH", path, token=token, body=body, retry_after_send=True)


# ---------------------------------------------------------------------------
# WebSocket
# ---------------------------------------------------------------------------

class WSClosed(Exception):
    pass


class WebSocket:
    """A client-side RFC 6455 connection (text frames, masked writes)."""

    def __init__(self, reader, writer):
        self.reader = reader
        self.writer = writer
        self.closed = False
        self._wlock = asyncio.Lock()

    @classmethod
    async def connect(cls, host, port, path, timeout=CONNECT_TIMEOUT + 3):
        reader, writer = await asyncio.wait_for(asyncio.open_connection(host, port), CONNECT_TIMEOUT)
        try:
            key = base64.b64encode(os.urandom(16)).decode()
            req = (f"GET {path} HTTP/1.1\r\nHost: {host}:{port}\r\nUpgrade: websocket\r\n"
                   f"Connection: Upgrade\r\nSec-WebSocket-Key: {key}\r\n"
                   f"Sec-WebSocket-Version: 13\r\n\r\n")
            writer.write(req.encode("latin-1"))
            await writer.drain()
            status, headers = await asyncio.wait_for(_read_headers(reader), timeout)
            if status != 101:
                # drain body if any for diagnostics
                raise ConnectionError(f"websocket upgrade refused: {status}")
        except BaseException:
            writer.close()
            raise
        return cls(reader, writer)

    async def _send_frame(self, opcode, data):
        if self.closed:
            raise WSClosed()
        header = bytearray([0x80 | opcode])
        n = len(data)
        if n < 126:
            header.append(0x80 | n)
        elif n < 65536:
            header.append(0x80 | 126)
            header += struct.pack("!H", n)
        else:
            header.append(0x80 | 127)
            header += struct.pack("!Q", n)
        mask = os.urandom(4)
        header += mask
        masked = bytes(b ^ mask[i & 3] for i, b in enumerate(data))
        async with self._wlock:
            self.writer.write(bytes(header) + masked)
            await self.writer.drain()

    async def send_json(self, obj):
        await self._send_frame(0x1, json.dumps(obj).encode("utf-8"))

    async def _read_frame(self):
        b1, b2 = await self.reader.readexactly(2)
        fin = bool(b1 & 0x80)
        opcode = b1 & 0x0F
        n = b2 & 0x7F
        if n == 126:
            n = struct.unpack("!H", await self.reader.readexactly(2))[0]
        elif n == 127:
            n = struct.unpack("!Q", await self.reader.readexactly(8))[0]
        mask = await self.reader.readexactly(4) if b2 & 0x80 else None
        data = await self.reader.readexactly(n) if n else b""
        if mask:
            data = bytes(b ^ mask[i & 3] for i, b in enumerate(data))
        return fin, opcode, data

    async def recv(self):
        """Return the next text/binary message as str; raise WSClosed when the peer closes."""
        buf = bytearray()
        msg_op = None
        while True:
            try:
                fin, opcode, data = await self._read_frame()
            except (asyncio.IncompleteReadError, OSError) as e:
                self.closed = True
                raise WSClosed() from e
            if opcode == 0x8:
                try:
                    await self._send_frame(0x8, data[:2])
                except Exception:  # noqa: BLE001
                    pass
                self.close()
                raise WSClosed()
            if opcode == 0x9:
                try:
                    await self._send_frame(0xA, data)
                except Exception:  # noqa: BLE001
                    pass
                continue
            if opcode == 0xA:
                continue
            if opcode in (0x1, 0x2):
                msg_op = opcode
                buf = bytearray(data)
            elif opcode == 0x0:
                buf += data
            if fin and msg_op is not None:
                return bytes(buf).decode("utf-8", "replace")

    def close(self):
        self.closed = True
        try:
            self.writer.close()
        except Exception:  # noqa: BLE001
            pass


class EventStream:
    """Keeps one WebSocket to some live node, subscribed to a set of channels.

    Tracks the last seen ``seq`` per channel; after reconnecting (possibly to a different
    node) it sends ``resume`` with that seq so nothing is missed, and drops frames with
    ``seq <= last`` so nothing is duplicated. Durable frames are passed to ``on_frame``.
    """

    PING_INTERVAL = 10.0
    IDLE_TIMEOUT = 35.0

    def __init__(self, cluster, token, on_frame):
        self.cluster = cluster
        self.token = token
        self.on_frame = on_frame
        self.last_seq = {}          # channel_id -> int | None
        self.ws = None
        self._task = None
        self._waiters = {}          # channel_id -> [futures]
        self._stopped = False
        self.connected = asyncio.Event()
        self.reconnects = 0

    def start(self):
        if self._task is None:
            self._task = asyncio.ensure_future(self._run())

    async def stop(self):
        self._stopped = True
        if self.ws:
            self.ws.close()
        if self._task:
            self._task.cancel()
            try:
                await self._task
            except BaseException:  # noqa: BLE001
                pass

    async def subscribe(self, channel_id, timeout=4.0):
        """Subscribe; waits (bounded) until the server confirmed with ``subscribed``."""
        if channel_id in self.last_seq and self.last_seq[channel_id] is not None:
            return True
        self.last_seq.setdefault(channel_id, None)
        fut = asyncio.get_running_loop().create_future()
        self._waiters.setdefault(channel_id, []).append(fut)
        self.start()
        ws = self.ws
        if ws is not None and not ws.closed:
            try:
                await ws.send_json({"type": "subscribe", "channel_id": channel_id})
            except Exception:  # noqa: BLE001
                pass
        try:
            await asyncio.wait_for(asyncio.shield(fut), timeout)
            return True
        except asyncio.TimeoutError:
            return False
        finally:
            lst = self._waiters.get(channel_id)
            if lst and fut in lst:
                lst.remove(fut)

    def unsubscribe(self, channel_id):
        self.last_seq.pop(channel_id, None)
        ws = self.ws
        if ws is not None and not ws.closed:
            asyncio.ensure_future(self._safe_send(ws, {"type": "unsubscribe", "channel_id": channel_id}))

    async def _safe_send(self, ws, obj):
        try:
            await ws.send_json(obj)
        except Exception:  # noqa: BLE001
            pass

    def _resolve(self, channel_id):
        for fut in self._waiters.pop(channel_id, []):
            if not fut.done():
                fut.set_result(True)

    async def _connect_any(self):
        path = "/api/ws?token=" + urllib.parse.quote(self.token, safe="")
        delay = 0.1
        while not self._stopped:
            for port in self.cluster.order():
                try:
                    ws = await WebSocket.connect(self.cluster.host, port, path)
                    self.cluster._mark_good(port)
                    return ws
                except (OSError, asyncio.TimeoutError, ConnectionError, ValueError,
                        asyncio.IncompleteReadError) as e:
                    log.debug("ws connect to %s failed: %r", port, e)
                    self.cluster._mark_bad(port)
            await asyncio.sleep(delay)
            delay = min(delay * 2, 2.0)
        raise WSClosed()

    async def _pinger(self, ws):
        try:
            while not ws.closed:
                await asyncio.sleep(self.PING_INTERVAL)
                await ws.send_json({"type": "ping"})
        except Exception:  # noqa: BLE001
            pass

    async def _run(self):
        while not self._stopped:
            try:
                ws = await self._connect_any()
            except WSClosed:
                return
            self.ws = ws
            self.connected.set()
            pinger = asyncio.ensure_future(self._pinger(ws))
            try:
                for cid, last in list(self.last_seq.items()):
                    if last is None:
                        await ws.send_json({"type": "subscribe", "channel_id": cid})
                    else:
                        await ws.send_json({"type": "resume", "channel_id": cid, "since_seq": last})
                while True:
                    text = await asyncio.wait_for(ws.recv(), self.IDLE_TIMEOUT)
                    try:
                        frame = json.loads(text)
                    except ValueError:
                        continue
                    if isinstance(frame, dict):
                        self._handle(frame)
            except asyncio.CancelledError:
                ws.close()
                raise
            except Exception as e:  # noqa: BLE001  (WSClosed, timeouts, OSError)
                log.info("event stream disconnected: %r", e)
            finally:
                pinger.cancel()
                ws.close()
                self.connected.clear()
                self.ws = None
            if self._stopped:
                return
            self.reconnects += 1
            await asyncio.sleep(0.05)

    def _handle(self, frame):
        ftype = frame.get("type")
        cid = frame.get("channel_id")
        if ftype == "subscribed":
            if cid in self.last_seq:
                head = frame.get("head_seq")
                cur = self.last_seq.get(cid)
                if isinstance(head, int) and (cur is None or head > cur):
                    self.last_seq[cid] = head
                elif cur is None:
                    self.last_seq[cid] = 0
            self._resolve(cid)
            return
        if ftype == "resumed":
            self._resolve(cid)
            return
        if ftype == "resume.gap":
            # Events older than earliest_seq are gone; continue from there.
            earliest = frame.get("earliest_seq")
            if cid in self.last_seq and isinstance(earliest, int):
                self.last_seq[cid] = max(earliest - 1, 0)
                ws = self.ws
                if ws is not None:
                    asyncio.ensure_future(self._safe_send(
                        ws, {"type": "resume", "channel_id": cid, "since_seq": earliest - 1}))
            return
        seq = frame.get("seq")
        if cid is None or not isinstance(seq, int):
            return  # pong, user.updated, errors ...
        if cid not in self.last_seq:
            return
        last = self.last_seq[cid]
        if last is not None and seq <= last:
            return  # duplicate (replayed or delivered twice)
        self.last_seq[cid] = seq
        try:
            self.on_frame(frame)
        except Exception:  # noqa: BLE001
            log.exception("on_frame failed")

"""Minimal Redis-compatible (RESP2) pub/sub server, stdlib asyncio only.

Supports PING, ECHO, SUBSCRIBE, UNSUBSCRIBE, PSUBSCRIBE, PUNSUBSCRIBE, PUBLISH, QUIT, plus a tiny
in-memory GET/SET/DEL/EXISTS/INFO/CLIENT/SELECT/COMMAND/FLUSHALL/DBSIZE so ordinary tooling works.
Run: python3 -m huddle.miniredis [--port P]   (default config.REDIS_PORT, binds 127.0.0.1)
"""
import argparse
import asyncio
import fnmatch
import signal
import sys

from huddle import config


class ProtocolError(Exception):
    pass


def enc(value):
    """Encode a python value as RESP2."""
    if value is None:
        return b"$-1\r\n"
    if isinstance(value, SimpleString):
        return b"+" + value.s.encode() + b"\r\n"
    if isinstance(value, Error):
        return b"-" + value.s.encode() + b"\r\n"
    if isinstance(value, bool):
        return b":%d\r\n" % int(value)
    if isinstance(value, int):
        return b":%d\r\n" % value
    if isinstance(value, str):
        value = value.encode()
    if isinstance(value, (bytes, bytearray)):
        return b"$%d\r\n%s\r\n" % (len(value), bytes(value))
    if isinstance(value, (list, tuple)):
        return b"*%d\r\n" % len(value) + b"".join(enc(v) for v in value)
    raise TypeError(type(value))


class SimpleString:
    def __init__(self, s):
        self.s = s


class Error:
    def __init__(self, s):
        self.s = s


OK = SimpleString("OK")


async def read_command(reader):
    """Read one command (RESP array of bulk strings or inline). Returns list[bytes] or None on EOF."""
    line = await reader.readline()
    if not line:
        return None
    if not line.endswith(b"\r\n") and not line.endswith(b"\n"):
        return None
    line = line.rstrip(b"\r\n")
    if not line:
        return []
    if line[:1] == b"*":
        try:
            n = int(line[1:])
        except ValueError:
            raise ProtocolError("invalid multibulk length")
        if n > 1024 * 1024:
            raise ProtocolError("invalid multibulk length")
        args = []
        for _ in range(n):
            hdr = await reader.readline()
            if not hdr:
                return None
            hdr = hdr.rstrip(b"\r\n")
            if hdr[:1] != b"$":
                raise ProtocolError("expected '$'")
            ln = int(hdr[1:])
            if ln < 0 or ln > 512 * 1024 * 1024:
                raise ProtocolError("invalid bulk length")
            data = await reader.readexactly(ln + 2)
            args.append(data[:-2])
        return args
    return line.split()


class Server:
    def __init__(self):
        self.channels = {}   # name(bytes) -> set(Client)
        self.patterns = {}   # pattern(bytes) -> set(Client)
        self.kv = {}

    def publish(self, channel, message):
        n = 0
        for c in list(self.channels.get(channel, ())):
            c.push(enc([b"message", channel, message]))
            n += 1
        if self.patterns:
            ch_s = channel.decode("latin-1")
            for pat, clients in list(self.patterns.items()):
                if fnmatch.fnmatchcase(ch_s, pat.decode("latin-1")):
                    for c in list(clients):
                        c.push(enc([b"pmessage", pat, channel, message]))
                        n += 1
        return n

    async def handle(self, reader, writer):
        client = Client(self, writer)
        try:
            while True:
                try:
                    args = await read_command(reader)
                except ProtocolError as e:
                    client.push(enc(Error("ERR Protocol error: %s" % e)))
                    break
                if args is None:
                    break
                if not args:
                    continue
                if not client.dispatch(args):
                    break
                if writer.transport.get_write_buffer_size() > 64 * 1024 * 1024:
                    break  # slow consumer: drop it like Redis' output-buffer limit
                await writer.drain()
        except (ConnectionError, asyncio.IncompleteReadError, OSError):
            pass
        finally:
            client.cleanup()
            try:
                writer.close()
            except Exception:  # noqa: BLE001
                pass


class Client:
    def __init__(self, server, writer):
        self.server = server
        self.writer = writer
        self.subs = set()
        self.psubs = set()
        self.name = None

    def push(self, data):
        try:
            if not self.writer.is_closing():
                self.writer.write(data)
        except Exception:  # noqa: BLE001
            pass

    def count(self):
        return len(self.subs) + len(self.psubs)

    def cleanup(self):
        for ch in self.subs:
            s = self.server.channels.get(ch)
            if s:
                s.discard(self)
                if not s:
                    del self.server.channels[ch]
        for p in self.psubs:
            s = self.server.patterns.get(p)
            if s:
                s.discard(self)
                if not s:
                    del self.server.patterns[p]
        self.subs.clear()
        self.psubs.clear()

    def dispatch(self, args):
        """Execute one command. Returns False when the connection should close."""
        cmd = args[0].upper()
        a = args[1:]
        srv = self.server
        in_sub = self.count() > 0
        if in_sub and cmd not in (b"SUBSCRIBE", b"UNSUBSCRIBE", b"PSUBSCRIBE", b"PUNSUBSCRIBE",
                                  b"PING", b"QUIT", b"RESET"):
            self.push(enc(Error("ERR Can't execute '%s': only (P|S)SUBSCRIBE / (P|S)UNSUBSCRIBE / PING / QUIT / RESET are allowed in this context" % cmd.decode(errors="replace").lower())))
            return True
        if cmd == b"PING":
            if in_sub:
                self.push(enc([b"pong", a[0] if a else b""]))
            else:
                self.push(enc(a[0]) if a else enc(SimpleString("PONG")))
        elif cmd == b"ECHO":
            if len(a) != 1:
                return self._arity(cmd)
            self.push(enc(a[0]))
        elif cmd == b"QUIT":
            self.push(enc(OK))
            return False
        elif cmd == b"RESET":
            self.cleanup()
            self.push(enc(SimpleString("RESET")))
        elif cmd == b"SUBSCRIBE":
            if not a:
                return self._arity(cmd)
            for ch in a:
                self.subs.add(ch)
                srv.channels.setdefault(ch, set()).add(self)
                self.push(enc([b"subscribe", ch, self.count()]))
        elif cmd == b"PSUBSCRIBE":
            if not a:
                return self._arity(cmd)
            for p in a:
                self.psubs.add(p)
                srv.patterns.setdefault(p, set()).add(self)
                self.push(enc([b"psubscribe", p, self.count()]))
        elif cmd == b"UNSUBSCRIBE":
            targets = list(a) if a else sorted(self.subs)
            if not targets:
                self.push(enc([b"unsubscribe", None, self.count()]))
            for ch in targets:
                self.subs.discard(ch)
                s = srv.channels.get(ch)
                if s:
                    s.discard(self)
                    if not s:
                        del srv.channels[ch]
                self.push(enc([b"unsubscribe", ch, self.count()]))
        elif cmd == b"PUNSUBSCRIBE":
            targets = list(a) if a else sorted(self.psubs)
            if not targets:
                self.push(enc([b"punsubscribe", None, self.count()]))
            for p in targets:
                self.psubs.discard(p)
                s = srv.patterns.get(p)
                if s:
                    s.discard(self)
                    if not s:
                        del srv.patterns[p]
                self.push(enc([b"punsubscribe", p, self.count()]))
        elif cmd == b"PUBLISH":
            if len(a) != 2:
                return self._arity(cmd)
            self.push(enc(srv.publish(a[0], a[1])))
        elif cmd == b"GET":
            if len(a) != 1:
                return self._arity(cmd)
            self.push(enc(srv.kv.get(a[0])))
        elif cmd == b"SET":
            if len(a) < 2:
                return self._arity(cmd)
            srv.kv[a[0]] = a[1]
            self.push(enc(OK))
        elif cmd == b"DEL":
            n = 0
            for k in a:
                if srv.kv.pop(k, None) is not None:
                    n += 1
            self.push(enc(n))
        elif cmd == b"EXISTS":
            self.push(enc(sum(1 for k in a if k in srv.kv)))
        elif cmd == b"DBSIZE":
            self.push(enc(len(srv.kv)))
        elif cmd in (b"FLUSHALL", b"FLUSHDB"):
            srv.kv.clear()
            self.push(enc(OK))
        elif cmd == b"SELECT":
            self.push(enc(OK))
        elif cmd == b"INFO":
            info = ("# Server\r\nredis_version:7.0.0-huddle\r\nredis_mode:standalone\r\n"
                    "# Clients\r\npubsub_channels:%d\r\n" % len(srv.channels))
            self.push(enc(info))
        elif cmd == b"CLIENT":
            sub = a[0].upper() if a else b""
            if sub == b"SETNAME" and len(a) > 1:
                self.name = a[1]
                self.push(enc(OK))
            elif sub == b"GETNAME":
                self.push(enc(self.name))
            elif sub == b"ID":
                self.push(enc(id(self) & 0x7FFFFFFF))
            else:
                self.push(enc(OK))
        elif cmd == b"COMMAND":
            self.push(enc([]))
        elif cmd == b"HELLO":
            # Only RESP2 supported.
            if a and a[0] not in (b"2",):
                self.push(enc(Error("NOPROTO unsupported protocol version")))
            else:
                self.push(enc([b"server", b"redis", b"version", b"7.0.0", b"proto", 2]))
        elif cmd == b"PUBSUB":
            sub = a[0].upper() if a else b""
            if sub == b"CHANNELS":
                self.push(enc(sorted(srv.channels)))
            elif sub == b"NUMSUB":
                out = []
                for ch in a[1:]:
                    out += [ch, len(srv.channels.get(ch, ()))]
                self.push(enc(out))
            elif sub == b"NUMPAT":
                self.push(enc(len(srv.patterns)))
            else:
                self.push(enc(Error("ERR unknown PUBSUB subcommand")))
        else:
            self.push(enc(Error("ERR unknown command '%s'" % cmd.decode(errors="replace").lower())))
        return True

    def _arity(self, cmd):
        self.push(enc(Error("ERR wrong number of arguments for '%s' command" % cmd.decode(errors="replace").lower())))
        return True


async def serve(host, port, ready=None):
    srv = Server()
    server = await asyncio.start_server(srv.handle, host, port, reuse_address=True)
    if ready is not None:
        ready.set()
    print("miniredis listening on %s:%d" % (host, port), flush=True)
    async with server:
        await server.serve_forever()


def main(argv=None):
    p = argparse.ArgumentParser(description="Huddle mini Redis pub/sub server")
    p.add_argument("--port", type=int, default=config.REDIS_PORT)
    p.add_argument("--bind", default="127.0.0.1")
    # Tolerate redis-server style invocations like `redis-server --port 6379 --save ''`.
    args, _unknown = p.parse_known_args(argv if argv is not None else sys.argv[1:])
    try:
        signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
    except Exception:  # noqa: BLE001
        pass
    try:
        asyncio.run(serve(args.bind, args.port))
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

"""Serializers and access-control helpers shared by the handlers."""
import json
import re

from huddle.api.db import ApiError

ROLES = ("owner", "admin", "member", "guest")
ROLE_RANK = {"owner": 3, "admin": 2, "member": 1, "guest": 0}


# ---------------------------------------------------------------- input helpers

def body_json(req):
    try:
        data = req.json()
    except ValueError:
        raise ApiError(400, "invalid JSON body")
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise ApiError(400, "JSON object expected")
    return data


def as_int(v, field, required=True):
    if v is None:
        if required:
            raise ApiError(400, f"{field} is required")
        return None
    if isinstance(v, bool):
        raise ApiError(400, f"{field} must be an integer")
    if isinstance(v, int):
        return v
    if isinstance(v, str) and re.fullmatch(r"-?\d+", v.strip()):
        return int(v.strip())
    raise ApiError(400, f"{field} must be an integer")


def truthy(v):
    if isinstance(v, bool):
        return v
    if v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    return str(v).strip().lower() in ("1", "true", "yes", "on")


# ---------------------------------------------------------------- serializers

def user_obj(row):
    if row is None:
        return None
    return {
        "id": row["id"],
        "username": row["username"],
        "display_name": row["display_name"] or row["username"],
        "timezone": row["timezone"],
        "avatar_url": row["avatar_url"],
        "status_text": row["status_text"],
        "status_emoji": row["status_emoji"],
        "title": row["title"],
        "created_at": row["created_at"],
    }


USER_COLS = "id, username, display_name, timezone, avatar_url, status_text, status_emoji, title, created_at"


def get_user(conn, uid):
    return conn.execute(f"SELECT {USER_COLS} FROM users WHERE id=?", (uid,)).fetchone()


def users_by_ids(conn, ids):
    ids = list({int(i) for i in ids})
    out = {}
    for i in range(0, len(ids), 500):
        chunk = ids[i:i + 500]
        q = ",".join("?" * len(chunk))
        for r in conn.execute(f"SELECT {USER_COLS} FROM users WHERE id IN ({q})", chunk):
            out[r["id"]] = user_obj(r)
    return out


def workspace_obj(row):
    return {
        "id": row["id"],
        "slug": row["slug"],
        "name": row["name"],
        "owner_id": row["owner_id"],
        "join_mode": row["join_mode"],
        "created_at": row["created_at"],
    }


def channel_obj(row):
    return {
        "id": row["id"],
        "workspace_id": row["workspace_id"],
        "name": row["name"],
        "is_private": bool(row["is_private"]),
        "is_dm": bool(row["is_dm"]),
        "topic": row["topic"] or "",
        "is_archived": bool(row["is_archived"]),
        "created_by": row["created_by"],
        "created_at": row["created_at"],
    }


def file_obj(row):
    return {
        "id": row["id"],
        "uploader_id": row["uploader_id"],
        "filename": row["filename"],
        "content_type": row["content_type"],
        "size": row["size"],
        "created_at": row["created_at"],
        "message_id": row["message_id"],
        "url": f"/api/files/{row['id']}/download",
    }


def reactions_for(conn, message_ids):
    """{message_id: [{emoji, count, user_ids}]} ordered by first reaction."""
    out = {mid: [] for mid in message_ids}
    if not message_ids:
        return out
    q = ",".join("?" * len(message_ids))
    rows = conn.execute(
        f"SELECT message_id, emoji, user_id FROM reactions WHERE message_id IN ({q})"
        " ORDER BY created_at, rowid", list(message_ids)).fetchall()
    tmp = {}
    for r in rows:
        d = tmp.setdefault(r["message_id"], {})
        if r["emoji"] not in d:
            d[r["emoji"]] = []
        d[r["emoji"]].append(r["user_id"])
    for mid, d in tmp.items():
        out[mid] = [{"emoji": e, "count": len(u), "user_ids": u} for e, u in d.items()]
    return out


def messages_obj(conn, rows):
    """Bulk-serialize message rows."""
    rows = list(rows)
    if not rows:
        return []
    ids = [r["id"] for r in rows]
    users = users_by_ids(conn, [r["user_id"] for r in rows])
    reacts = reactions_for(conn, ids)
    q = ",".join("?" * len(ids))
    files = {}
    for f in conn.execute(f"SELECT * FROM files WHERE message_id IN ({q}) ORDER BY id", ids):
        files.setdefault(f["message_id"], []).append(file_obj(f))
    out = []
    for r in rows:
        try:
            mentions = json.loads(r["mentions"] or "[]")
        except ValueError:
            mentions = []
        blocks = None
        if r["blocks"]:
            try:
                blocks = json.loads(r["blocks"])
            except ValueError:
                blocks = None
        out.append({
            "id": r["id"],
            "channel_id": r["channel_id"],
            "author_id": r["user_id"],
            "user_id": r["user_id"],
            "author": users.get(r["user_id"]),
            "body": r["body"],
            "parent_id": r["parent_id"],
            "reply_count": r["reply_count"],
            "created_at": r["created_at"],
            "edited_at": r["edited_at"],
            "is_edited": r["edited_at"] is not None,
            "deleted_at": r["deleted_at"],
            "files": files.get(r["id"], []),
            "reactions": reacts.get(r["id"], []),
            "mentions": mentions,
            "blocks": blocks,
        })
    return out


def message_obj(conn, row):
    return messages_obj(conn, [row])[0]


# ---------------------------------------------------------------- lookups / access

def get_workspace(conn, slug):
    row = conn.execute("SELECT * FROM workspaces WHERE slug=?", (slug,)).fetchone()
    if row is None:
        raise ApiError(404, "workspace not found")
    return row


def ws_role(conn, workspace_id, uid):
    if workspace_id is None:
        return None
    r = conn.execute("SELECT role FROM workspace_members WHERE workspace_id=? AND user_id=?",
                     (workspace_id, uid)).fetchone()
    return r["role"] if r else None


def get_channel(conn, cid):
    row = conn.execute("SELECT * FROM channels WHERE id=?", (cid,)).fetchone()
    if row is None:
        raise ApiError(404, "channel not found")
    return row


def is_channel_member(conn, cid, uid):
    return conn.execute("SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?",
                        (cid, uid)).fetchone() is not None


def can_read_channel(conn, ch, uid):
    if is_channel_member(conn, ch["id"], uid):
        return True
    if ch["is_private"] or ch["is_dm"]:
        return False
    return ws_role(conn, ch["workspace_id"], uid) is not None


def require_read(conn, ch, uid):
    if not can_read_channel(conn, ch, uid):
        raise ApiError(403, "not allowed to access this channel")


def require_write(conn, ch, uid):
    """Posting/reacting: channel member, or a non-guest workspace member on a public channel."""
    if is_channel_member(conn, ch["id"], uid):
        return
    if ch["is_private"] or ch["is_dm"]:
        raise ApiError(403, "not a member of this channel")
    role = ws_role(conn, ch["workspace_id"], uid)
    if role is None or role == "guest":
        raise ApiError(403, "not allowed to post in this channel")


def require_not_archived(ch):
    if ch["is_archived"]:
        raise ApiError(423, "channel is archived")


def get_message(conn, mid, allow_deleted=False):
    row = conn.execute("SELECT * FROM messages WHERE id=?", (mid,)).fetchone()
    if row is None or (row["deleted_at"] is not None and not allow_deleted):
        raise ApiError(404, "message not found")
    return row


def channel_member_ids(conn, cid):
    return [r[0] for r in conn.execute("SELECT user_id FROM channel_members WHERE channel_id=?", (cid,))]


def read_states(conn, uid, channel_ids):
    """{channel_id: {channel_id, last_read_seq, unread_count, mention_count}}."""
    out = {}
    channel_ids = list(channel_ids)
    if not channel_ids:
        return out
    for i in range(0, len(channel_ids), 400):
        chunk = channel_ids[i:i + 400]
        q = ",".join("?" * len(chunk))
        cursors = {r["channel_id"]: r["last_read_seq"] for r in conn.execute(
            f"SELECT channel_id, last_read_seq FROM read_state WHERE user_id=? AND channel_id IN ({q})",
            [uid] + chunk)}
        unread = {r[0]: r[1] for r in conn.execute(
            f"SELECT m.channel_id, COUNT(*) FROM messages m LEFT JOIN read_state rs"
            f" ON rs.user_id=? AND rs.channel_id=m.channel_id"
            f" WHERE m.channel_id IN ({q}) AND m.user_id<>? AND m.deleted_at IS NULL"
            f" AND m.seq > COALESCE(rs.last_read_seq, 0) GROUP BY m.channel_id",
            [uid] + chunk + [uid])}
        ment = {r[0]: r[1] for r in conn.execute(
            f"SELECT m.channel_id, COUNT(*) FROM message_mentions mm JOIN messages m ON m.id=mm.message_id"
            f" LEFT JOIN read_state rs ON rs.user_id=? AND rs.channel_id=m.channel_id"
            f" WHERE mm.user_id=? AND m.channel_id IN ({q}) AND m.user_id<>? AND m.deleted_at IS NULL"
            f" AND m.seq > COALESCE(rs.last_read_seq, 0) GROUP BY m.channel_id",
            [uid, uid] + chunk + [uid])}
        for cid in chunk:
            out[cid] = {"channel_id": cid, "last_read_seq": cursors.get(cid, 0),
                        "unread_count": unread.get(cid, 0), "mention_count": ment.get(cid, 0)}
    return out

"""Tiny regex router. Handlers: fn(ctx) -> Response | (status, body) | body."""
import re
import secrets  # noqa: F401  (re-exported convenience)

ROUTES = []  # (method, compiled regex, handler, auth_required)


def route(method, pattern, auth=True):
    rx = re.compile("^" + re.sub(r"\{(\w+)\}", r"(?P<\1>[^/]+)", pattern) + "/?$")

    def deco(fn):
        ROUTES.append((method, rx, fn, auth))
        return fn
    return deco


class Ctx:
    __slots__ = ("req", "conn", "uid", "user", "params", "token")

    def __init__(self, req, conn, params):
        self.req = req
        self.conn = conn
        self.params = params
        self.uid = None
        self.user = None
        self.token = None

    def pint(self, name):
        from huddle.api.db import ApiError
        v = self.params.get(name, "")
        if not v.isdigit():
            raise ApiError(404, "not found")
        return int(v)

"""REST API entry point: ``handle_api(req) -> Response`` (synchronous)."""
import logging
import sqlite3
import time
import traceback
from urllib.parse import unquote

from huddle.web.http import Response
from huddle.api.db import ApiError, get_conn, reset_conn
from huddle.api.router import ROUTES, Ctx

# Register handlers.
from huddle.api import h_auth, h_workspaces, h_channels, h_messages, h_misc  # noqa: F401,E402

log = logging.getLogger("huddle.api")


def _authenticate(ctx):
    h = ctx.req.headers.get("authorization", "")
    token = None
    if h:
        parts = h.split(None, 1)
        if len(parts) == 2 and parts[0].lower() == "bearer":
            token = parts[1].strip()
    if not token:
        token = ctx.req.query.get("token") or None
    if not token:
        raise ApiError(401, "missing bearer token")
    row = ctx.conn.execute(
        "SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?", (token,)).fetchone()
    if row is None:
        raise ApiError(401, "invalid token")
    ctx.uid = row["id"]
    ctx.user = row
    ctx.token = token


def _to_response(result):
    if isinstance(result, Response):
        return result
    if isinstance(result, tuple):
        status, body = result
        return Response(status, body)
    return Response(200, result)


def _dispatch(req):
    path = req.path or "/"
    if path in ("/api/health", "/api/health/"):
        return Response(200, {"status": "ok", "node_id": req.node_id})
    method = req.method.upper()
    if method == "HEAD":
        method = "GET"
    path_matched = False
    for m, rx, fn, auth in ROUTES:
        mt = rx.match(path)
        if not mt:
            continue
        path_matched = True
        if m != method:
            continue
        params = {k: unquote(v) for k, v in mt.groupdict().items()}
        conn = get_conn()
        ctx = Ctx(req, conn, params)
        if auth:
            _authenticate(ctx)
        return _to_response(fn(ctx))
    if path_matched:
        return Response(405, {"error": "method not allowed"})
    return Response(404, {"error": "not found"})


def handle_api(req):
    for attempt in range(4):
        try:
            return _dispatch(req)
        except ApiError as e:
            return Response(e.status, {"error": e.message})
        except sqlite3.OperationalError as e:
            s = str(e).lower()
            if ("locked" in s or "busy" in s) and attempt < 3:
                time.sleep(0.05 * (attempt + 1))
                continue
            log.error("db error: %s", traceback.format_exc())
            reset_conn()
            return Response(503 if ("locked" in s or "busy" in s) else 500, {"error": "database error"})
        except Exception:  # noqa: BLE001
            log.error("unhandled: %s", traceback.format_exc())
            try:
                conn = get_conn()
                if conn.in_transaction:
                    conn.execute("ROLLBACK")
            except Exception:  # noqa: BLE001
                reset_conn()
            return Response(500, {"error": "internal error"})
    return Response(503, {"error": "busy"})

"""Auth + user profile endpoints."""
import hashlib
import hmac
import re
import secrets
import sqlite3

from huddle.api.db import ApiError, Tx, now_iso
from huddle.api.router import route
from huddle.api.core import body_json, user_obj, get_user, USER_COLS

USERNAME_RE = re.compile(r"^[A-Za-z0-9_]{1,32}$")
PBKDF2_ITERS = 60000

PROFILE_LIMITS = {
    "display_name": 80,
    "status_text": 100,
    "status_emoji": 64,
    "avatar_url": 2048,
    "title": 100,
}


def hash_password(pw):
    salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), salt, PBKDF2_ITERS)
    return f"pbkdf2_sha256${PBKDF2_ITERS}${salt.hex()}${dk.hex()}"


def verify_password(pw, stored):
    try:
        algo, iters, salt, dk = stored.split("$")
        calc = hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), bytes.fromhex(salt), int(iters))
        return hmac.compare_digest(calc.hex(), dk)
    except Exception:  # noqa: BLE001
        return False


def new_token(conn, uid):
    token = secrets.token_urlsafe(32)
    conn.execute("INSERT INTO tokens(token, user_id, created_at) VALUES (?,?,?)", (token, uid, now_iso()))
    return token


def valid_timezone(tz):
    if not isinstance(tz, str) or not tz or len(tz) > 64:
        return False
    try:
        from zoneinfo import ZoneInfo
        ZoneInfo(tz)
        return True
    except Exception:  # noqa: BLE001
        return False


@route("POST", "/api/auth/register", auth=False)
def register(ctx):
    data = body_json(ctx.req)
    username = data.get("username")
    password = data.get("password")
    display_name = data.get("display_name")
    if not isinstance(username, str) or not USERNAME_RE.match(username):
        raise ApiError(400, "username must be 1-32 letters, digits or underscores")
    if not isinstance(password, str) or len(password) < 8:
        raise ApiError(400, "password must be at least 8 characters")
    if len(password) > 1024:
        raise ApiError(400, "password too long")
    if display_name is None or (isinstance(display_name, str) and not display_name.strip()):
        display_name = username
    if not isinstance(display_name, str) or len(display_name) > PROFILE_LIMITS["display_name"]:
        raise ApiError(400, "invalid display_name")
    tz = data.get("timezone") or "UTC"
    if not valid_timezone(tz):
        raise ApiError(400, "invalid timezone")
    conn = ctx.conn
    if conn.execute("SELECT 1 FROM users WHERE username=?", (username,)).fetchone():
        raise ApiError(409, "username already taken")
    pw_hash = hash_password(password)
    try:
        with Tx(conn):
            cur = conn.execute(
                "INSERT INTO users(username, password_hash, display_name, timezone, created_at)"
                " VALUES (?,?,?,?,?)", (username, pw_hash, display_name.strip(), tz, now_iso()))
            uid = cur.lastrowid
            token = new_token(conn, uid)
    except sqlite3.IntegrityError:
        raise ApiError(409, "username already taken")
    return 201, {"user": user_obj(get_user(conn, uid)), "token": token}


@route("POST", "/api/auth/login", auth=False)
def login(ctx):
    data = body_json(ctx.req)
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str) or not username or not password:
        raise ApiError(400, "username and password required")
    conn = ctx.conn
    row = conn.execute("SELECT * FROM users WHERE username=?", (username,)).fetchone()
    if row is None or not verify_password(password, row["password_hash"]):
        raise ApiError(401, "invalid username or password")
    token = new_token(conn, row["id"])
    return 200, {"user": user_obj(get_user(conn, row["id"])), "token": token}


@route("POST", "/api/auth/logout")
def logout(ctx):
    ctx.conn.execute("DELETE FROM tokens WHERE token=?", (ctx.token,))
    return 200, {"ok": True}


@route("GET", "/api/auth/me")
def me(ctx):
    return {"user": user_obj(get_user(ctx.conn, ctx.uid))}


@route("GET", "/api/users/me")
def users_me(ctx):
    return {"user": user_obj(get_user(ctx.conn, ctx.uid))}


@route("GET", "/api/users")
def list_users(ctx):
    q = (ctx.req.query.get("q") or ctx.req.query.get("username") or "").strip()
    conn = ctx.conn
    if q:
        esc = q.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        rows = conn.execute(
            f"SELECT {USER_COLS} FROM users WHERE username LIKE ? ESCAPE '\\' OR display_name LIKE ? ESCAPE '\\'"
            " ORDER BY username LIMIT 50", (f"%{esc}%", f"%{esc}%")).fetchall()
    else:
        rows = conn.execute(f"SELECT {USER_COLS} FROM users ORDER BY id LIMIT 200").fetchall()
    return {"users": [user_obj(r) for r in rows]}


@route("GET", "/api/users/{id}")
def get_user_ep(ctx):
    raw = ctx.params["id"]
    if not raw.isdigit():
        row = ctx.conn.execute(f"SELECT {USER_COLS} FROM users WHERE username=?", (raw,)).fetchone()
    else:
        row = get_user(ctx.conn, int(raw))
    if row is None:
        raise ApiError(404, "user not found")
    return {"user": user_obj(row)}


@route("PATCH", "/api/users/me")
def patch_me(ctx):
    data = body_json(ctx.req)
    updates = {}
    for field, limit in PROFILE_LIMITS.items():
        if field not in data:
            continue
        v = data[field]
        if v is None:
            v = ""
        if not isinstance(v, str):
            raise ApiError(400, f"{field} must be a string")
        if len(v) > limit:
            raise ApiError(400, f"{field} too long (max {limit})")
        if field == "display_name":
            v = v.strip()
            if not v:
                raise ApiError(400, "display_name cannot be empty")
        updates[field] = v
    if "timezone" in data:
        tz = data["timezone"]
        if not valid_timezone(tz):
            raise ApiError(400, "invalid timezone")
        updates["timezone"] = tz
    conn = ctx.conn
    if updates:
        sets = ", ".join(f"{k}=?" for k in updates)
        conn.execute(f"UPDATE users SET {sets} WHERE id=?", list(updates.values()) + [ctx.uid])
    user = user_obj(get_user(conn, ctx.uid))
    if updates:
        from huddle import events
        events.publish_global({"type": "user.updated", "user": user})
    return {"user": user}

"""RFC 6455 WebSocket helpers (server side, asyncio) — stdlib only."""
import asyncio
import base64
import hashlib
import struct

GUID = b"258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

OP_CONT, OP_TEXT, OP_BINARY, OP_CLOSE, OP_PING, OP_PONG = 0x0, 0x1, 0x2, 0x8, 0x9, 0xA
MAX_MESSAGE = 4 * 1024 * 1024


class WSClosed(Exception):
    def __init__(self, code=1000, reason=""):
        super().__init__(code, reason)
        self.code = code
        self.reason = reason


def accept_key(key: str) -> str:
    return base64.b64encode(hashlib.sha1(key.strip().encode("latin-1") + GUID).digest()).decode()


def encode_frame(payload: bytes, opcode=OP_TEXT, fin=True, mask=False) -> bytes:
    """Encode one frame. Server frames are unmasked; ``mask=True`` is for clients."""
    b0 = (0x80 if fin else 0) | opcode
    n = len(payload)
    mbit = 0x80 if mask else 0
    if n < 126:
        hdr = struct.pack("!BB", b0, mbit | n)
    elif n < 65536:
        hdr = struct.pack("!BBH", b0, mbit | 126, n)
    else:
        hdr = struct.pack("!BBQ", b0, mbit | 127, n)
    if mask:
        import os
        key = os.urandom(4)
        return hdr + key + apply_mask(payload, key)
    return hdr + payload


def apply_mask(data: bytes, key: bytes) -> bytes:
    if not data:
        return b""
    n = len(data)
    k = (key * (n // 4 + 1))[:n]
    return (int.from_bytes(data, "big") ^ int.from_bytes(k, "big")).to_bytes(n, "big")


def close_payload(code=1000, reason=""):
    return struct.pack("!H", code) + reason.encode("utf-8")[:120]


async def read_frame(reader: asyncio.StreamReader, require_mask=True):
    """Return (fin, opcode, payload). Raises WSClosed / IncompleteReadError."""
    h = await reader.readexactly(2)
    fin = bool(h[0] & 0x80)
    if h[0] & 0x70:
        raise WSClosed(1002, "reserved bits set")
    opcode = h[0] & 0x0F
    masked = bool(h[1] & 0x80)
    n = h[1] & 0x7F
    if n == 126:
        n = struct.unpack("!H", await reader.readexactly(2))[0]
    elif n == 127:
        n = struct.unpack("!Q", await reader.readexactly(8))[0]
    if opcode >= 0x8 and (n > 125 or not fin):
        raise WSClosed(1002, "bad control frame")
    if n > MAX_MESSAGE:
        raise WSClosed(1009, "message too big")
    if require_mask and not masked:
        raise WSClosed(1002, "client frames must be masked")
    key = await reader.readexactly(4) if masked else None
    payload = await reader.readexactly(n) if n else b""
    if key:
        payload = apply_mask(payload, key)
    return fin, opcode, payload


async def read_message(reader, send_raw, require_mask=True):
    """Read one complete data message, transparently answering pings.

    ``send_raw(bytes)`` writes an already-encoded frame. Returns (opcode, payload).
    Raises WSClosed when a close frame arrives (after echoing it).
    """
    buf = None
    first_op = None
    while True:
        fin, op, payload = await read_frame(reader, require_mask)
        if op == OP_PING:
            send_raw(encode_frame(payload, OP_PONG))
            continue
        if op == OP_PONG:
            continue
        if op == OP_CLOSE:
            code = struct.unpack("!H", payload[:2])[0] if len(payload) >= 2 else 1000
            raise WSClosed(code, payload[2:].decode("utf-8", "replace"))
        if op == OP_CONT:
            if buf is None:
                raise WSClosed(1002, "unexpected continuation")
            buf += payload
        elif op in (OP_TEXT, OP_BINARY):
            if buf is not None:
                raise WSClosed(1002, "expected continuation")
            buf = bytearray(payload)
            first_op = op
        else:
            raise WSClosed(1002, "unknown opcode")
        if len(buf) > MAX_MESSAGE:
            raise WSClosed(1009, "message too big")
        if fin:
            return first_op, bytes(buf)

"""Shared write operations (must be called inside a Tx)."""
from huddle.api.db import now_iso
from huddle.api.core import user_obj, get_user


def add_channel_member(tx, ch_id, uid, emit=True):
    """Adds uid to channel; emits member.joined. Returns True if newly added."""
    conn = tx.conn
    cur = conn.execute("INSERT OR IGNORE INTO channel_members(channel_id, user_id, joined_at) VALUES (?,?,?)",
                       (ch_id, uid, now_iso()))
    if cur.rowcount and emit:
        tx.emit(ch_id, "member.joined", {"user_id": uid, "user": user_obj(get_user(conn, uid))})
    return bool(cur.rowcount)


def remove_channel_member(tx, ch_id, uid):
    conn = tx.conn
    cur = conn.execute("DELETE FROM channel_members WHERE channel_id=? AND user_id=?", (ch_id, uid))
    if cur.rowcount:
        tx.emit(ch_id, "member.left", {"user_id": uid, "user": user_obj(get_user(conn, uid))})
    return bool(cur.rowcount)


def add_workspace_member(tx, ws_id, uid, role="member"):
    """Adds uid to the workspace (and its #general). Returns True if newly added."""
    conn = tx.conn
    cur = conn.execute("INSERT OR IGNORE INTO workspace_members(workspace_id, user_id, role, joined_at)"
                       " VALUES (?,?,?,?)", (ws_id, uid, role, now_iso()))
    if not cur.rowcount:
        return False
    gen = conn.execute("SELECT id, is_archived FROM channels WHERE workspace_id=? AND name='general' AND is_dm=0",
                       (ws_id,)).fetchone()
    if gen is not None and not gen["is_archived"]:
        add_channel_member(tx, gen["id"], uid)
    return True

"""Tiny blocking WebSocket client (stdlib only) for tests and tools.

    ws = WSClient("127.0.0.1", 8000, "/api/ws?token=...")
    ws.send_json({"type": "subscribe", "channel_id": 1})
    frame = ws.recv_json(timeout=5)     # None on timeout
    ws.close()
"""
import base64
import json
import os
import socket
import struct
import time

from huddle.web.ws import (OP_BINARY, OP_CLOSE, OP_CONT, OP_PING, OP_PONG, OP_TEXT, accept_key,
                           close_payload, encode_frame)


class HandshakeError(Exception):
    def __init__(self, status, body=b""):
        super().__init__("websocket handshake failed: HTTP %s" % status)
        self.status = status
        self.body = body


class WSClient:
    def __init__(self, host, port, path, timeout=10.0):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        self.buf = b""
        self.closed = False
        key = base64.b64encode(os.urandom(16)).decode()
        req = ("GET %s HTTP/1.1\r\nHost: %s:%d\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
               "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n\r\n" % (path, host, port, key))
        self.sock.sendall(req.encode())
        while b"\r\n\r\n" not in self.buf:
            chunk = self.sock.recv(65536)
            if not chunk:
                break
            self.buf += chunk
        head, _, rest = self.buf.partition(b"\r\n\r\n")
        lines = head.decode("latin-1").split("\r\n")
        status = int(lines[0].split()[1]) if lines and len(lines[0].split()) > 1 else 0
        headers = {}
        for ln in lines[1:]:
            k, _, v = ln.partition(":")
            headers[k.strip().lower()] = v.strip()
        if status != 101:
            self.sock.close()
            raise HandshakeError(status, rest)
        if headers.get("sec-websocket-accept") != accept_key(key):
            self.sock.close()
            raise HandshakeError(status, b"bad accept key")
        self.buf = rest

    # -- sending -----------------------------------------------------------------------------
    def send_raw(self, frame_bytes):
        self.sock.sendall(frame_bytes)

    def send_text(self, text, fragments=1):
        data = text.encode("utf-8")
        if fragments <= 1:
            self.sock.sendall(encode_frame(data, OP_TEXT, mask=True))
            return
        step = max(1, len(data) // fragments)
        parts = [data[i:i + step] for i in range(0, len(data), step)] or [b""]
        for i, p in enumerate(parts):
            op = OP_TEXT if i == 0 else OP_CONT
            self.sock.sendall(encode_frame(p, op, fin=(i == len(parts) - 1), mask=True))

    def send_json(self, obj, fragments=1):
        self.send_text(json.dumps(obj), fragments)

    def ping(self, payload=b"hi"):
        self.sock.sendall(encode_frame(payload, OP_PING, mask=True))

    # -- receiving ---------------------------------------------------------------------------
    def _need(self, n, deadline):
        while len(self.buf) < n:
            remaining = deadline - time.time()
            if remaining <= 0:
                raise socket.timeout()
            self.sock.settimeout(remaining)
            chunk = self.sock.recv(65536)
            if not chunk:
                raise ConnectionError("connection closed")
            self.buf += chunk

    def _take(self, n, deadline):
        self._need(n, deadline)
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def recv_frame(self, timeout=5.0):
        """Return (opcode, payload) of the next raw frame; raises socket.timeout.

        Only consumes bytes once a whole frame is available, so a timeout never desyncs.
        """
        deadline = time.time() + timeout
        self._need(2, deadline)
        b1 = self.buf[1]
        n = b1 & 0x7F
        hl = 2 + (2 if n == 126 else 8 if n == 127 else 0) + (4 if b1 & 0x80 else 0)
        self._need(hl, deadline)
        if n == 126:
            n = struct.unpack("!H", self.buf[2:4])[0]
        elif n == 127:
            n = struct.unpack("!Q", self.buf[2:10])[0]
        self._need(hl + n, deadline)
        frame = self._take(hl + n, deadline)
        return frame[0] & 0x0F, frame[hl:], bool(frame[0] & 0x80)

    def recv_text(self, timeout=5.0):
        """Next complete text message (pings answered); None on timeout; raises on close."""
        deadline = time.time() + timeout
        parts = []
        while True:
            try:
                op, payload, fin = self.recv_frame(max(0.0, deadline - time.time()))
            except socket.timeout:
                if parts:
                    continue
                return None
            if op == OP_PING:
                self.sock.sendall(encode_frame(payload, OP_PONG, mask=True))
                continue
            if op == OP_PONG:
                continue
            if op == OP_CLOSE:
                self.closed = True
                raise ConnectionError("websocket closed by server")
            if op in (OP_TEXT, OP_BINARY, OP_CONT):
                parts.append(payload)
                if fin:
                    return b"".join(parts).decode("utf-8")

    def recv_json(self, timeout=5.0):
        t = self.recv_text(timeout)
        return None if t is None else json.loads(t)

    def recv_until(self, pred, timeout=5.0):
        """Return the first JSON frame satisfying pred (others are discarded); None on timeout."""
        deadline = time.time() + timeout
        while True:
            remaining = deadline - time.time()
            if remaining <= 0:
                return None
            f = self.recv_json(remaining)
            if f is None:
                return None
            if pred(f):
                return f

    def close(self):
        if not self.closed:
            try:
                self.sock.sendall(encode_frame(close_payload(1000), OP_CLOSE, mask=True))
            except OSError:
                pass
        self.closed = True
        try:
            self.sock.close()
        except OSError:
            pass

