/* Huddle — hand-written styles. No frameworks. */
:root {
  --aubergine: #3f0e40;
  --aubergine-dark: #350d36;
  --aubergine-rail: #2a0a2b;
  --aubergine-hover: #4e1f50;
  --sidebar-text: #d9cfdb;
  --sidebar-muted: #b49fb6;
  --active: #1164a3;
  --accent: #007a5a;
  --accent-hover: #148567;
  --danger: #c0262d;
  --text: #1d1c1d;
  --muted: #616061;
  --border: #dddddd;
  --bg: #ffffff;
  --hover-bg: #f8f8f8;
  --highlight: #fff8e1;
  --mention: #1264a3;
  --radius: 8px;
  font-size: 15px;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { margin: 0; height: 100%; }
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  overflow: hidden;
}
button { font: inherit; cursor: pointer; }
input, textarea, select { font: inherit; color: inherit; }
a { color: var(--mention); }
.muted { color: var(--muted); }
.muted-light { color: var(--sidebar-muted); }
.small-text { font-size: 12px; }

/* ---------- buttons ---------- */
.btn {
  border: 1px solid transparent; border-radius: 6px; padding: 8px 14px; font-weight: 600;
  font-size: 14px; line-height: 1.2; background: #fff; color: var(--text);
}
.btn.small { padding: 5px 10px; font-size: 13px; }
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-outline { border-color: #bbb; background: #fff; }
.btn-outline:hover { background: #f4f4f4; }
.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover { background: #a51f25; }
.btn-block { width: 100%; }
.btn-ghost-light { background: transparent; color: var(--sidebar-text); border-color: rgba(255,255,255,.25); }
.btn-ghost-light:hover { background: rgba(255,255,255,.1); }
.btn:disabled { opacity: .6; cursor: default; }
.btn-send { background: var(--accent); color: #fff; padding: 6px 14px; }
.btn-send:hover { background: var(--accent-hover); }
.link-btn { background: none; border: 0; padding: 0; color: var(--mention); font-weight: 600; }
.link-btn:hover { text-decoration: underline; }
.icon-btn {
  background: none; border: 0; border-radius: 6px; width: 30px; height: 30px; padding: 0;
  display: inline-flex; align-items: center; justify-content: center; font-size: 18px; color: var(--muted);
}
.icon-btn:hover { background: #eee; color: var(--text); }
.icon-btn.light { color: var(--sidebar-text); }
.icon-btn.light:hover { background: rgba(255,255,255,.12); color: #fff; }
.icon-btn.small { width: 24px; height: 24px; font-size: 17px; }

/* ---------- forms ---------- */
.field { display: flex; flex-direction: column; gap: 5px; margin-bottom: 14px; font-size: 14px; font-weight: 600; }
.field input, .field select, .field textarea {
  font-weight: 400; border: 1px solid #bbb; border-radius: 6px; padding: 9px 10px; font-size: 15px; background: #fff;
}
.field input:focus, .field select:focus, textarea:focus { outline: 2px solid #1d9bd1; outline-offset: -1px; border-color: transparent; }
.field small { font-weight: 400; font-size: 12px; }
.field.grow { flex: 1; }
.check { display: flex; gap: 8px; align-items: center; margin-bottom: 14px; font-size: 14px; }
.input-prefix { display: flex; align-items: center; border: 1px solid #bbb; border-radius: 6px; padding-left: 10px; background: #fff; }
.input-prefix span { color: var(--muted); font-weight: 400; }
.input-prefix input { border: 0; flex: 1; padding-left: 6px; }
.input-prefix:focus-within { outline: 2px solid #1d9bd1; }
.input-prefix input:focus { outline: none; }
.form-error {
  background: #fde8e9; color: #8a1116; border: 1px solid #f3b7ba; border-radius: 6px;
  padding: 8px 10px; font-size: 14px; margin-bottom: 12px; font-weight: 500;
}
.form-ok { background: #e6f4ee; color: #0b5a3f; border: 1px solid #a8d8c3; border-radius: 6px; padding: 8px 10px; font-size: 14px; margin: 10px 0; }
.inline-form { display: flex; gap: 10px; align-items: flex-end; }
.inline-form .btn { margin-bottom: 14px; }
.form-row { display: flex; gap: 12px; }
.form-row .field { flex: 1; }

/* ---------- auth ---------- */
.screen { position: fixed; inset: 0; z-index: 50; }
.auth-screen { background: linear-gradient(160deg, #4a154b 0%, #2a0a2b 100%); display: flex; align-items: center; justify-content: center; }
.auth-card { background: #fff; width: 400px; max-width: 92vw; padding: 32px 32px 22px; border-radius: 12px; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
.brand { font-weight: 800; font-size: 20px; display: flex; align-items: center; gap: 8px; margin-bottom: 18px; color: var(--aubergine); }
.brand-logo { background: var(--aubergine); color: #fff; width: 30px; height: 30px; border-radius: 7px; display: inline-flex; align-items: center; justify-content: center; }
.auth-card h1 { font-size: 24px; margin: 0 0 4px; }
.auth-sub { color: var(--muted); margin: 0 0 20px; font-size: 14px; }
.auth-switch { text-align: center; font-size: 14px; color: var(--muted); margin: 18px 0 0; }

/* ---------- app layout ---------- */
.app { display: flex; height: 100vh; width: 100vw; }
.ws-rail { width: 64px; flex: none; background: var(--aubergine-rail); display: flex; flex-direction: column; align-items: center; padding: 12px 0; gap: 10px; }
.ws-rail-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.ws-rail-btn, .ws-rail-add {
  width: 40px; height: 40px; border-radius: 9px; border: 0; font-weight: 700; color: #fff; font-size: 15px;
  background: #6b3a6d; display: flex; align-items: center; justify-content: center;
}
.ws-rail-btn.active { box-shadow: 0 0 0 3px var(--aubergine-rail), 0 0 0 5px #fff; }
.ws-rail-add { background: transparent; border: 1px dashed rgba(255,255,255,.4); font-size: 22px; color: var(--sidebar-text); }
.ws-rail-add:hover { background: rgba(255,255,255,.1); }

.sidebar { width: 260px; flex: none; background: var(--aubergine); color: var(--sidebar-text); display: flex; flex-direction: column; border-right: 1px solid var(--aubergine-dark); }
.workspace-header { display: flex; align-items: center; justify-content: space-between; padding: 14px 12px 12px 16px; border-bottom: 1px solid rgba(255,255,255,.12); }
.ws-ident { display: flex; flex-direction: column; min-width: 0; }
.ws-name { color: #fff; font-weight: 800; font-size: 18px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ws-slug { font-size: 12px; }
.sidebar-scroll { flex: 1; overflow-y: auto; padding: 10px 0; }
.sidebar-section { margin-bottom: 16px; }
.sidebar-section-head { display: flex; justify-content: space-between; align-items: center; padding: 2px 10px 4px 16px; font-size: 14px; color: var(--sidebar-muted); font-weight: 600; }
.channel-list { list-style: none; margin: 0; padding: 0 8px; }
.channel-entry {
  width: 100%; display: flex; align-items: center; gap: 6px; border: 0; background: none; color: var(--sidebar-text);
  text-align: left; padding: 5px 10px; border-radius: 6px; font-size: 15px; min-height: 30px;
}
.channel-entry:hover { background: var(--aubergine-hover); }
.channel-entry.active { background: var(--active); color: #fff; }
.channel-entry.unread { color: #fff; font-weight: 700; }
.channel-entry.archived { opacity: .6; font-style: italic; }
.channel-entry .ch-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.channel-entry .ch-hash { opacity: .8; width: 14px; text-align: center; }
.badge { background: #cd2553; color: #fff; border-radius: 9px; font-size: 11px; font-weight: 700; padding: 1px 7px; }
.sidebar-empty { padding: 4px 18px; font-size: 13px; color: var(--sidebar-muted); }
.sidebar-footer { border-top: 1px solid rgba(255,255,255,.12); padding: 10px 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.current-user { display: flex; align-items: center; gap: 8px; min-width: 0; color: #fff; font-weight: 600; font-size: 14px; }
.current-user .cu-text { display: flex; flex-direction: column; min-width: 0; }
.current-user .cu-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.current-user .cu-handle { font-weight: 400; font-size: 12px; color: var(--sidebar-muted); }
.presence { width: 9px; height: 9px; border-radius: 50%; background: #2bac76; display: inline-block; flex: none; }
.presence.off { background: transparent; border: 1.5px solid var(--sidebar-muted); }

.main { flex: 1; min-width: 0; display: flex; flex-direction: column; position: relative; }
.channel-view { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.channel-header { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 10px 18px; border-bottom: 1px solid var(--border); min-height: 60px; }
.channel-heading { min-width: 0; }
.channel-title { font-size: 18px; margin: 0; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.channel-topic { font-size: 13px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 560px; }
.channel-topic.empty { font-style: italic; }
.channel-header-actions { display: flex; gap: 8px; align-items: center; flex: none; }
.search-form input { border: 1px solid #ccc; border-radius: 6px; padding: 6px 10px; width: 200px; font-size: 13px; }
.archived-banner { background: #fff4d6; border-bottom: 1px solid #f1d58a; padding: 8px 18px; font-size: 14px; color: #6b4e00; }

.message-scroll { flex: 1; overflow-y: auto; padding: 8px 0 12px; min-height: 0; }
.load-older { text-align: center; padding: 6px; }
.channel-intro { padding: 24px 20px 12px; }
.channel-intro h2 { margin: 0 0 6px; font-size: 22px; }
.channel-intro p { margin: 0; color: var(--muted); }
.message-list { list-style: none; margin: 0; padding: 0; }

/* ---------- messages ---------- */
.message { position: relative; display: flex; gap: 10px; padding: 7px 20px; }
.message:hover, .message:focus-within { background: var(--hover-bg); }
.message.flash { animation: flash 1.6s ease-out; }
@keyframes flash { from { background: var(--highlight); } to { background: transparent; } }
.avatar {
  width: 36px; height: 36px; border-radius: 6px; flex: none; color: #fff; font-weight: 700; font-size: 14px;
  display: flex; align-items: center; justify-content: center; text-transform: uppercase; user-select: none; overflow: hidden;
}
.avatar img { width: 100%; height: 100%; object-fit: cover; }
.avatar.sm { width: 24px; height: 24px; font-size: 11px; border-radius: 5px; }
.msg-main { flex: 1; min-width: 0; }
.msg-head { display: flex; align-items: baseline; gap: 8px; }
.msg-author { font-weight: 800; font-size: 15px; }
.msg-time { font-size: 12px; color: var(--muted); }
.msg-time:hover { text-decoration: underline; }
.message-body { font-size: 15px; line-height: 1.46; white-space: pre-wrap; word-wrap: break-word; overflow-wrap: anywhere; }
.message-body .mention { background: #e8f5fa; color: var(--mention); border-radius: 3px; padding: 0 2px; font-weight: 500; }
.message-body .mention.me { background: #fdf2c7; color: #6b4e00; }
.message-body code { background: #f3f3f3; border: 1px solid #e3e3e3; border-radius: 3px; padding: 0 3px; font-size: 13px; }
.message-body.me-action { font-style: italic; color: #444; }
.edited { font-size: 12px; color: var(--muted); margin-left: 4px; }
.msg-files { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }
.msg-file { border: 1px solid var(--border); border-radius: 6px; padding: 6px 10px; font-size: 13px; text-decoration: none; color: var(--text); background: #fff; }
.msg-file:hover { background: #f4f4f4; }
.reactions { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 4px; }
.reaction-chip {
  border: 1px solid #ddd; background: #f4f4f4; border-radius: 12px; padding: 1px 8px; font-size: 13px;
  display: inline-flex; gap: 4px; align-items: center; min-height: 24px;
}
.reaction-chip:hover { border-color: #999; }
.reaction-chip.mine { background: #e3f0f9; border-color: #1d9bd1; color: #0b4c7a; }
.reaction-chip .count { font-weight: 700; font-size: 12px; }
.reply-link { margin-top: 4px; display: inline-flex; gap: 6px; align-items: center; background: none; border: 1px solid transparent; border-radius: 6px; padding: 3px 6px 3px 2px; color: var(--mention); font-weight: 700; font-size: 13px; }
.reply-link:hover { border-color: #ddd; background: #fff; }
.msg-actions {
  position: absolute; top: -14px; right: 20px; display: flex; gap: 2px; background: #fff; border: 1px solid #ddd;
  border-radius: 8px; padding: 2px; box-shadow: 0 1px 4px rgba(0,0,0,.08); opacity: 0; pointer-events: none; transition: opacity .08s;
  z-index: 5;
}
.message:hover .msg-actions, .message:focus-within .msg-actions, .msg-actions.force { opacity: 1; pointer-events: auto; }
.msg-actions button { background: none; border: 0; border-radius: 5px; height: 28px; min-width: 30px; padding: 0 6px; font-size: 15px; color: #444; }
.msg-actions button:hover { background: #eee; }
.msg-actions .act-label { font-size: 12px; font-weight: 600; }
.message.editing { background: var(--highlight); }
.edit-form textarea { width: 100%; border: 1px solid #bbb; border-radius: 6px; padding: 8px; font-size: 15px; resize: vertical; min-height: 60px; }
.edit-form .edit-actions { display: flex; gap: 8px; margin-top: 6px; align-items: center; }
.day-divider { display: flex; align-items: center; gap: 10px; margin: 10px 20px; color: var(--muted); font-size: 12px; font-weight: 700; }
.day-divider::before, .day-divider::after { content: ""; flex: 1; border-top: 1px solid var(--border); }

/* ---------- composer ---------- */
.composer { padding: 0 18px 16px; flex: none; }
.composer-box { border: 1px solid #bbb; border-radius: 8px; background: #fff; }
.composer-box:focus-within { border-color: #888; box-shadow: 0 0 0 1px #888; }
.composer textarea { width: 100%; border: 0; resize: none; padding: 10px 12px 4px; font-size: 15px; max-height: 200px; min-height: 40px; line-height: 1.4; background: transparent; display: block; }
.composer textarea:focus { outline: none; }
.composer-bar { display: flex; align-items: center; gap: 8px; padding: 4px 6px 6px 8px; }
.composer-hint { flex: 1; font-size: 12px; text-align: right; }
.composer-files { font-size: 12px; display: flex; gap: 6px; }
.composer-files .pending-file { background: #eef; border-radius: 4px; padding: 2px 6px; }
.composer-error { margin: 6px 0 0; }
.composer.disabled .composer-box { opacity: .5; }
.attach-btn { cursor: pointer; font-size: 16px; }

/* ---------- thread panel ---------- */
.thread-panel { width: 380px; flex: none; border-left: 1px solid var(--border); display: flex; flex-direction: column; background: #fff; }
.panel-header { display: flex; justify-content: space-between; align-items: center; padding: 10px 14px; border-bottom: 1px solid var(--border); min-height: 60px; }
.panel-header h2 { margin: 0; font-size: 17px; }
.thread-scroll { flex: 1; overflow-y: auto; min-height: 0; padding-bottom: 8px; }
.thread-parent .message { padding-top: 14px; }
.thread-divider { display: flex; align-items: center; gap: 10px; margin: 4px 16px 6px; font-size: 13px; color: var(--muted); }
.thread-divider::after { content: ""; flex: 1; border-top: 1px solid var(--border); }
.thread-panel .message { padding: 7px 16px; }
.thread-panel .msg-actions { right: 12px; }
.thread-composer { padding: 8px 14px 14px; }
.search-result-ctx { font-size: 12px; color: var(--muted); margin-bottom: 2px; }

/* ---------- empty state ---------- */
.empty-state { position: absolute; inset: 0; background: #fafafa; overflow-y: auto; z-index: 3; display: flex; align-items: flex-start; justify-content: center; padding: 60px 20px; }
.empty-card { max-width: 760px; width: 100%; }
.empty-card h1 { margin: 0 0 6px; font-size: 26px; }
.empty-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin: 22px 0; }
.card-form { background: #fff; border: 1px solid var(--border); border-radius: 10px; padding: 18px; }
.card-form h2 { margin: 0 0 14px; font-size: 17px; }

/* ---------- modals ---------- */
