"""Workspace, membership/roles, groups and invitations endpoints."""
import re
import secrets
import sqlite3
import time

from huddle.api.db import ApiError, Tx, now_iso, iso_from_epoch
from huddle.api.router import route
from huddle.api.core import (body_json, as_int, truthy, user_obj, users_by_ids, workspace_obj, channel_obj,
                             get_workspace, ws_role, read_states, ROLES)
from huddle.api import ops

SLUG_RE = re.compile(r"^[a-z0-9-]{2,32}$")
HANDLE_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,31}$")
RESERVED_HANDLES = {"channel", "here", "everyone"}


def _name(v, field="name", limit=80):
    if not isinstance(v, str) or not v.strip():
        raise ApiError(400, f"{field} is required")
    if len(v.strip()) > limit:
        raise ApiError(400, f"{field} too long")
    return v.strip()


def _require_member(conn, ws, uid):
    role = ws_role(conn, ws["id"], uid)
    if role is None:
        raise ApiError(403, "not a member of this workspace")
    return role


def _require_admin(conn, ws, uid):
    role = _require_member(conn, ws, uid)
    if role not in ("owner", "admin"):
        raise ApiError(403, "admin or owner required")
    return role


# ---------------------------------------------------------------- workspaces

@route("POST", "/api/workspaces")
def create_workspace(ctx):
    data = body_json(ctx.req)
    slug = data.get("slug")
    if not isinstance(slug, str) or not SLUG_RE.match(slug):
        raise ApiError(400, "slug must match ^[a-z0-9-]{2,32}$")
    name = data.get("name")
    if name is None or (isinstance(name, str) and not name.strip()):
        name = slug
    name = _name(name)
    join_mode = data.get("join_mode", "open") or "open"
    if join_mode not in ("open", "invite_only"):
        raise ApiError(400, "join_mode must be open or invite_only")
    conn = ctx.conn
    if conn.execute("SELECT 1 FROM workspaces WHERE slug=?", (slug,)).fetchone():
        raise ApiError(409, "slug already taken")
    now = now_iso()
    try:
        with Tx(conn):
            cur = conn.execute("INSERT INTO workspaces(slug, name, owner_id, join_mode, created_at) VALUES (?,?,?,?,?)",
                               (slug, name, ctx.uid, join_mode, now))
            ws_id = cur.lastrowid
            conn.execute("INSERT INTO workspace_members(workspace_id, user_id, role, joined_at) VALUES (?,?,?,?)",
                         (ws_id, ctx.uid, "owner", now))
            cur = conn.execute("INSERT INTO channels(workspace_id, name, is_private, is_dm, topic, created_by, created_at)"
                               " VALUES (?,?,?,?,?,?,?)", (ws_id, "general", 0, 0, "", ctx.uid, now))
            gen_id = cur.lastrowid
            conn.execute("INSERT INTO channel_members(channel_id, user_id, joined_at) VALUES (?,?,?)",
                         (gen_id, ctx.uid, now))
    except sqlite3.IntegrityError:
        raise ApiError(409, "slug already taken")
    ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (ws_id,)).fetchone()
    gen = conn.execute("SELECT * FROM channels WHERE id=?", (gen_id,)).fetchone()
    return 201, {"workspace": workspace_obj(ws), "general_channel": channel_obj(gen)}


@route("GET", "/api/workspaces")
def list_workspaces(ctx):
    rows = ctx.conn.execute(
        "SELECT w.*, wm.role AS my_role FROM workspaces w JOIN workspace_members wm"
        " ON wm.workspace_id=w.id AND wm.user_id=? ORDER BY w.id", (ctx.uid,)).fetchall()
    out = []
    for r in rows:
        o = workspace_obj(r)
        o["role"] = r["my_role"]
        out.append(o)
    return {"workspaces": out}


@route("GET", "/api/workspaces/{slug}")
def get_workspace_ep(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    role = ws_role(conn, ws["id"], ctx.uid)
    if role is None and ws["join_mode"] != "open":
        raise ApiError(403, "not a member of this workspace")
    q = ctx.req.query
    include_archived = truthy(q.get("include_archived"))
    include_private = truthy(q.get("include_private")) and role in ("owner", "admin")
    rows = conn.execute(
        "SELECT c.*, (cm.user_id IS NOT NULL) AS is_member FROM channels c"
        " LEFT JOIN channel_members cm ON cm.channel_id=c.id AND cm.user_id=?"
        " WHERE c.workspace_id=? AND c.is_dm=0 ORDER BY c.name", (ctx.uid, ws["id"])).fetchall()
    chans = []
    for r in rows:
        if r["is_archived"] and not include_archived:
            continue
        if r["is_private"] and not r["is_member"] and not include_private:
            continue
        o = channel_obj(r)
        o["is_member"] = bool(r["is_member"])
        chans.append(o)
    member_ids = [c["id"] for c in chans if c["is_member"]]
    rs = read_states(conn, ctx.uid, member_ids)
    for c in chans:
        st = rs.get(c["id"])
        if st:
            c["unread_count"] = st["unread_count"]
            c["mention_count"] = st["mention_count"]
            c["last_read_seq"] = st["last_read_seq"]
    wo = workspace_obj(ws)
    wo["role"] = role
    return {"workspace": wo, "channels": chans, "read_state": [rs[c] for c in member_ids], "role": role}


@route("PATCH", "/api/workspaces/{slug}")
def patch_workspace(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_admin(conn, ws, ctx.uid)
    data = body_json(ctx.req)
    updates = {}
    if "name" in data:
        updates["name"] = _name(data["name"])
    if "join_mode" in data:
        if data["join_mode"] not in ("open", "invite_only"):
            raise ApiError(400, "join_mode must be open or invite_only")
        updates["join_mode"] = data["join_mode"]
    if updates:
        sets = ", ".join(f"{k}=?" for k in updates)
        conn.execute(f"UPDATE workspaces SET {sets} WHERE id=?", list(updates.values()) + [ws["id"]])
    ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (ws["id"],)).fetchone()
    return {"workspace": workspace_obj(ws)}


def _member_obj(conn, ws_id, uid, users=None):
    r = conn.execute("SELECT * FROM workspace_members WHERE workspace_id=? AND user_id=?", (ws_id, uid)).fetchone()
    if r is None:
        return None
    u = (users or users_by_ids(conn, [uid])).get(uid)
    return {"user_id": uid, "workspace_id": ws_id, "role": r["role"], "joined_at": r["joined_at"], "user": u,
            "username": u["username"] if u else None, "display_name": u["display_name"] if u else None}


@route("GET", "/api/workspaces/{slug}/members")
def list_members(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_member(conn, ws, ctx.uid)
    rows = conn.execute("SELECT * FROM workspace_members WHERE workspace_id=? ORDER BY joined_at, user_id",
                        (ws["id"],)).fetchall()
    users = users_by_ids(conn, [r["user_id"] for r in rows])
    out = []
    for r in rows:
        u = users.get(r["user_id"])
        out.append({"user_id": r["user_id"], "workspace_id": ws["id"], "role": r["role"], "joined_at": r["joined_at"],
                    "user": u, "username": u["username"] if u else None,
                    "display_name": u["display_name"] if u else None})
    return {"members": out}


@route("PATCH", "/api/workspaces/{slug}/members/{user_id}")
def patch_member(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    actor = _require_admin(conn, ws, ctx.uid)
    data = body_json(ctx.req)
    role = data.get("role")
    if role == "owner":
        raise ApiError(400, "use transfer_ownership to change the owner")
    if role not in ROLES:
        raise ApiError(400, "role must be one of admin, member, guest")
    target = ctx.pint("user_id")
    with Tx(conn):
        cur_role = ws_role(conn, ws["id"], target)
        if cur_role is None:
            raise ApiError(404, "user is not a member of this workspace")
        if cur_role == "owner":
            raise ApiError(403, "the owner's role cannot be changed")
        if actor == "admin" and cur_role == "admin" and target != ctx.uid:
            raise ApiError(403, "admins cannot modify other admins")
        conn.execute("UPDATE workspace_members SET role=? WHERE workspace_id=? AND user_id=?",
                     (role, ws["id"], target))
    return {"member": _member_obj(conn, ws["id"], target)}


@route("POST", "/api/workspaces/{slug}/transfer_ownership")
def transfer_ownership(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    if ws_role(conn, ws["id"], ctx.uid) != "owner":
        raise ApiError(403, "owner only")
    data = body_json(ctx.req)
    new_owner = as_int(data.get("new_owner_id", data.get("user_id")), "new_owner_id")
    with Tx(conn):
        if ws_role(conn, ws["id"], new_owner) != "admin":
            raise ApiError(400, "new owner must be an admin of the workspace")
        conn.execute("UPDATE workspace_members SET role='owner' WHERE workspace_id=? AND user_id=?",
                     (ws["id"], new_owner))
        conn.execute("UPDATE workspace_members SET role='admin' WHERE workspace_id=? AND user_id=?",
                     (ws["id"], ctx.uid))
        conn.execute("UPDATE workspaces SET owner_id=? WHERE id=?", (new_owner, ws["id"]))
    ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (ws["id"],)).fetchone()
    users = users_by_ids(conn, [new_owner, ctx.uid])
    return {"workspace": workspace_obj(ws),
            "owner": _member_obj(conn, ws["id"], new_owner, users),
            "previous_owner": _member_obj(conn, ws["id"], ctx.uid, users)}


@route("POST", "/api/workspaces/{slug}/join")
def join_workspace(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    if ws_role(conn, ws["id"], ctx.uid) is None:
        if ws["join_mode"] != "open":
            raise ApiError(403, "workspace is invite-only")
        with Tx(conn) as tx:
            ops.add_workspace_member(tx, ws["id"], ctx.uid, "member")
    return {"workspace": workspace_obj(ws), "member": _member_obj(conn, ws["id"], ctx.uid)}


# ---------------------------------------------------------------- groups

def _group_objs(conn, rows):
    out = []
    for g in rows:
        ids = [r[0] for r in conn.execute("SELECT user_id FROM group_members WHERE group_id=? ORDER BY user_id",
                                          (g["id"],))]
        out.append({"id": g["id"], "workspace_id": g["workspace_id"], "handle": g["handle"], "name": g["name"],
                    "created_by": g["created_by"], "created_at": g["created_at"], "member_user_ids": ids})
    return out


def _group_user_ids(conn, ws_id, v):
    if v is None:
        return []
    if not isinstance(v, list):
        raise ApiError(400, "user_ids must be a list")
    ids = []
    for x in v:
        i = as_int(x, "user_ids")
        if ws_role(conn, ws_id, i) is None:
            raise ApiError(400, f"user {i} is not a member of this workspace")
        if i not in ids:
            ids.append(i)
    return ids


def _handle(v):
    if not isinstance(v, str):
        raise ApiError(400, "handle is required")
    v = v.strip().lstrip("@").lower()
    if not HANDLE_RE.match(v) or v in RESERVED_HANDLES:
        raise ApiError(400, "invalid handle")
    return v


@route("GET", "/api/workspaces/{slug}/groups")
def list_groups(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_member(conn, ws, ctx.uid)
    rows = conn.execute("SELECT * FROM user_groups WHERE workspace_id=? ORDER BY handle", (ws["id"],)).fetchall()
    return {"groups": _group_objs(conn, rows)}


@route("POST", "/api/workspaces/{slug}/groups")
def create_group(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_member(conn, ws, ctx.uid)
    data = body_json(ctx.req)
    handle = _handle(data.get("handle"))
    name = data.get("name")
    name = _name(name) if name is not None and str(name).strip() else handle
    ids = _group_user_ids(conn, ws["id"], data.get("user_ids", data.get("member_user_ids")))
    try:
        with Tx(conn):
            if conn.execute("SELECT 1 FROM user_groups WHERE workspace_id=? AND handle=?",
                            (ws["id"], handle)).fetchone():
                raise ApiError(409, "group handle already exists")
            cur = conn.execute("INSERT INTO user_groups(workspace_id, handle, name, created_by, created_at)"
                               " VALUES (?,?,?,?,?)", (ws["id"], handle, name, ctx.uid, now_iso()))
            gid = cur.lastrowid
            conn.executemany("INSERT OR IGNORE INTO group_members(group_id, user_id) VALUES (?,?)",
                             [(gid, i) for i in ids])
    except sqlite3.IntegrityError:
        raise ApiError(409, "group handle already exists")
    g = conn.execute("SELECT * FROM user_groups WHERE id=?", (gid,)).fetchone()
    return 201, {"group": _group_objs(conn, [g])[0]}


def _get_group(conn, ws, handle):
    h = handle.lstrip("@").lower()
    g = conn.execute("SELECT * FROM user_groups WHERE workspace_id=? AND handle=?", (ws["id"], h)).fetchone()
    if g is None and h.isdigit():
        g = conn.execute("SELECT * FROM user_groups WHERE workspace_id=? AND id=?", (ws["id"], int(h))).fetchone()
    return g


def _can_manage_group(conn, ws, g, uid):
    return g["created_by"] == uid or ws_role(conn, ws["id"], uid) == "owner"


@route("GET", "/api/workspaces/{slug}/groups/{handle}")
def get_group(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_member(conn, ws, ctx.uid)
    g = _get_group(conn, ws, ctx.params["handle"])
    if g is None:
        raise ApiError(404, "group not found")
    return {"group": _group_objs(conn, [g])[0]}


@route("PATCH", "/api/workspaces/{slug}/groups/{handle}")
def patch_group(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_member(conn, ws, ctx.uid)
    g = _get_group(conn, ws, ctx.params["handle"])
    if g is None:
        raise ApiError(404, "group not found")
    if not _can_manage_group(conn, ws, g, ctx.uid):
        raise ApiError(403, "only the group creator or workspace owner may modify this group")
    data = body_json(ctx.req)
    updates = {}
    if "name" in data:
        updates["name"] = _name(data["name"])
    if "handle" in data and data["handle"] != g["handle"]:
        updates["handle"] = _handle(data["handle"])
    ids = None
    if "user_ids" in data or "member_user_ids" in data:
        ids = _group_user_ids(conn, ws["id"], data.get("user_ids", data.get("member_user_ids")))
    try:
        with Tx(conn):
            if updates:
                sets = ", ".join(f"{k}=?" for k in updates)
                conn.execute(f"UPDATE user_groups SET {sets} WHERE id=?", list(updates.values()) + [g["id"]])
            if ids is not None:
                conn.execute("DELETE FROM group_members WHERE group_id=?", (g["id"],))
                conn.executemany("INSERT OR IGNORE INTO group_members(group_id, user_id) VALUES (?,?)",
                                 [(g["id"], i) for i in ids])
    except sqlite3.IntegrityError:
        raise ApiError(409, "group handle already exists")
    g = conn.execute("SELECT * FROM user_groups WHERE id=?", (g["id"],)).fetchone()
    return {"group": _group_objs(conn, [g])[0]}


@route("DELETE", "/api/workspaces/{slug}/groups/{handle}")
def delete_group(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_member(conn, ws, ctx.uid)
    g = _get_group(conn, ws, ctx.params["handle"])
    if g is not None:
        if not _can_manage_group(conn, ws, g, ctx.uid):
            raise ApiError(403, "only the group creator or workspace owner may delete this group")
        with Tx(conn):
            conn.execute("DELETE FROM group_members WHERE group_id=?", (g["id"],))
            conn.execute("DELETE FROM user_groups WHERE id=?", (g["id"],))
    return {"deleted": True}


# ---------------------------------------------------------------- invitations

def _inv_obj(conn, r, ws=None):
    if ws is None:
        ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (r["workspace_id"],)).fetchone()
    return {"id": r["id"], "code": r["code"], "workspace_id": r["workspace_id"],
            "workspace_slug": ws["slug"] if ws else None, "workspace_name": ws["name"] if ws else None,
            "created_by": r["created_by"], "expires_at": iso_from_epoch(r["expires_at"]),
            "max_uses": r["max_uses"], "uses": r["uses"], "use_count": r["uses"],
            "invited_user_id": r["invited_user_id"], "role": r["role"], "revoked": bool(r["revoked"]),
            "created_at": r["created_at"]}


def _inv_active(r):
    return (not r["revoked"] and r["uses"] < r["max_uses"]
            and (r["expires_at"] is None or r["expires_at"] > time.time()))


@route("POST", "/api/workspaces/{slug}/invitations")
def create_invitation(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_admin(conn, ws, ctx.uid)
    data = body_json(ctx.req)
    exp = data.get("expires_in_seconds")
    expires_at = None
    if exp is not None:
        if isinstance(exp, bool) or not isinstance(exp, (int, float)) or exp <= 0:
            raise ApiError(400, "expires_in_seconds must be a positive number")
        expires_at = time.time() + float(exp)
    max_uses = data.get("max_uses")
    if max_uses is None:
        max_uses = 1
    else:
        max_uses = as_int(max_uses, "max_uses")
        if max_uses < 1:
            raise ApiError(400, "max_uses must be >= 1")
    target = None
    if data.get("invited_user_id") is not None:
        target = as_int(data["invited_user_id"], "invited_user_id")
        if conn.execute("SELECT 1 FROM users WHERE id=?", (target,)).fetchone() is None:
            raise ApiError(404, "invited user not found")
    elif data.get("invited_username"):
        u = data["invited_username"]
        if not isinstance(u, str):
            raise ApiError(400, "invited_username must be a string")
        r = conn.execute("SELECT id FROM users WHERE username=?", (u.lstrip("@"),)).fetchone()
        if r is None:
            raise ApiError(404, "invited user not found")
        target = r["id"]
    if target is not None:
        max_uses = 1
    role = data.get("role") or "member"
    if role not in ("member", "guest", "admin"):
        raise ApiError(400, "invalid role")
    code = secrets.token_urlsafe(12)
    cur = conn.execute(
        "INSERT INTO invitations(workspace_id, code, created_by, expires_at, max_uses, uses, invited_user_id, role,"
        " revoked, created_at) VALUES (?,?,?,?,?,0,?,?,0,?)",
        (ws["id"], code, ctx.uid, expires_at, max_uses, target, role, now_iso()))
    r = conn.execute("SELECT * FROM invitations WHERE id=?", (cur.lastrowid,)).fetchone()
    return 201, {"invitation": _inv_obj(conn, r, ws)}


@route("GET", "/api/workspaces/{slug}/invitations")
def list_invitations(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_admin(conn, ws, ctx.uid)
    rows = conn.execute("SELECT * FROM invitations WHERE workspace_id=? ORDER BY id DESC", (ws["id"],)).fetchall()
    return {"invitations": [_inv_obj(conn, r, ws) for r in rows if _inv_active(r)]}


@route("DELETE", "/api/workspaces/{slug}/invitations/{code}")
def revoke_invitation(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    _require_admin(conn, ws, ctx.uid)
    code = ctx.params["code"]
    r = conn.execute("SELECT * FROM invitations WHERE workspace_id=? AND code=?", (ws["id"], code)).fetchone()
    if r is None and code.isdigit():
        r = conn.execute("SELECT * FROM invitations WHERE workspace_id=? AND id=?", (ws["id"], int(code))).fetchone()
    if r is None:
        raise ApiError(404, "invitation not found")
    conn.execute("UPDATE invitations SET revoked=1 WHERE id=?", (r["id"],))
    return {"deleted": True}


@route("GET", "/api/invitations/{code}")
def get_invitation(ctx):
    conn = ctx.conn
    r = conn.execute("SELECT * FROM invitations WHERE code=?", (ctx.params["code"],)).fetchone()
    if r is None or not _inv_active(r):
        raise ApiError(404, "invitation not found")
    return {"invitation": _inv_obj(conn, r)}


@route("POST", "/api/invitations/{code}/accept")
def accept_invitation(ctx):
    conn = ctx.conn
    code = ctx.params["code"]
    with Tx(conn) as tx:
        r = conn.execute("SELECT * FROM invitations WHERE code=?", (code,)).fetchone()
        if r is None or not _inv_active(r):
            raise ApiError(404, "invitation not found or no longer valid")
        if r["invited_user_id"] is not None and r["invited_user_id"] != ctx.uid:
            raise ApiError(403, "this invitation is for a different user")
        ws_id = r["workspace_id"]
        if ws_role(conn, ws_id, ctx.uid) is None:
            conn.execute("UPDATE invitations SET uses=uses+1 WHERE id=?", (r["id"],))
            ops.add_workspace_member(tx, ws_id, ctx.uid, r["role"] or "member")
    ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (ws_id,)).fetchone()
    gen = conn.execute("SELECT * FROM channels WHERE workspace_id=? AND name='general' AND is_dm=0",
                       (ws_id,)).fetchone()
    return {"workspace": workspace_obj(ws), "member": _member_obj(conn, ws_id, ctx.uid),
            "general_channel": channel_obj(gen) if gen else None}

"""A tiny in-process fake of the Huddle HTTP/WS cluster (just enough for the IRC gateway).

Several FakeNode servers share one FakeState, so a node can be "killed" (server closed and its
WebSockets dropped) while the others keep serving -- mimicking the real cluster.
"""
import asyncio
import base64
import hashlib
import json
import struct
import urllib.parse

WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC11B5B"


class FakeState:
    def __init__(self):
        self.users = {}
        self.tokens = {}
        self.workspaces = {}
        self.channels = {}
        self.members = {}
        self.messages = {}
        self.events = {}
        self.next_id = 100
        self.nodes = []
        self.unmasked_frames = 0
        self.posts = []  # (node_port, channel_id, body)

    def _id(self):
        self.next_id += 1
        return self.next_id

    def add_user(self, username, token):
        uid = self._id()
        self.users[uid] = {"id": uid, "username": username, "display_name": username}
        self.tokens[token] = uid
        return uid

    def add_workspace(self, slug, owner_id, members=()):
        wid = self._id()
        self.workspaces[slug] = {"id": wid, "slug": slug, "name": slug, "owner_id": owner_id,
                                 "join_mode": "open", "members": set([owner_id, *members])}
        return wid

    def add_channel(self, slug, name, topic="", is_private=False, members=()):
        cid = self._id()
        ws = self.workspaces[slug]
        self.channels[cid] = {"id": cid, "workspace_id": ws["id"], "name": name, "topic": topic,
                              "is_private": is_private, "is_dm": False, "is_archived": False}
        self.members[cid] = set(members)
        self.messages[cid] = []
        self.events[cid] = []
        return cid

    def append_event(self, cid, kind, data):
        seq = len(self.events[cid]) + 1
        frame = {"type": kind, "seq": seq, "channel_id": cid, **data}
        self.events[cid].append(frame)
        for node in self.nodes:
            node.fanout(frame)
        return frame

    def post_message(self, cid, uid, body):
        mid = self._id()
        msg = {"id": mid, "channel_id": cid, "author_id": uid, "author": self.users[uid],
               "body": body, "parent_id": None, "reply_count": 0,
               "created_at": "2026-01-01T00:00:00.000Z", "edited_at": None, "files": [],
               "reactions": [], "mentions": []}
        self.messages[cid].append(msg)
        self.append_event(cid, "message.new", {"message": msg})
        return msg

    def ws_by_slug(self, slug):
        return self.workspaces.get(slug)


class FakeNode:
    def __init__(self, state, port, host="127.0.0.1"):
        self.state = state
        self.port = port
        self.host = host
        self.server = None
        self.wsconns = set()
        self.http_requests = 0
        state.nodes.append(self)

    async def start(self):
        self.server = await asyncio.start_server(self._client, self.host, self.port, reuse_address=True)

    async def kill(self):
        """Simulate SIGKILL: stop listening and drop every connection."""
        if self.server:
            self.server.close()
            self.server = None
        for c in list(self.wsconns):
            c["writer"].transport.abort()
        self.wsconns.clear()

    def fanout(self, frame):
        for c in list(self.wsconns):
            if frame["channel_id"] in c["subs"]:
                self._send(c, frame)

    def _send(self, c, obj):
        data = json.dumps(obj).encode()
        hdr = bytearray([0x81])
        n = len(data)
        if n < 126:
            hdr.append(n)
        elif n < 65536:
            hdr.append(126)
            hdr += struct.pack("!H", n)
        else:
            hdr.append(127)
            hdr += struct.pack("!Q", n)
        try:
            c["writer"].write(bytes(hdr) + data)
        except Exception:  # noqa: BLE001
            pass

    async def _client(self, reader, writer):
        try:
            line = await reader.readline()
            if not line:
                return
            method, target, _ = line.decode().split(" ", 2)
            headers = {}
            while True:
                h = await reader.readline()
                if h in (b"\r\n", b"\n", b""):
                    break
                k, v = h.decode().split(":", 1)
                headers[k.strip().lower()] = v.strip()
            body = b""
            if "content-length" in headers:
                body = await reader.readexactly(int(headers["content-length"]))
            path, _, qs = target.partition("?")
            query = dict(urllib.parse.parse_qsl(qs))
            if path == "/api/ws":
                await self._ws(reader, writer, headers, query)
                return
            self.http_requests += 1
            status, obj = self._route(method, path, headers, body)
            data = json.dumps(obj).encode()
            writer.write(f"HTTP/1.1 {status} X\r\nContent-Type: application/json\r\n"
                         f"Content-Length: {len(data)}\r\nConnection: close\r\n\r\n".encode() + data)
            await writer.drain()
        except Exception:  # noqa: BLE001
            pass
        finally:
            try:
                writer.close()
            except Exception:  # noqa: BLE001
                pass

    def _uid(self, headers):
        auth = headers.get("authorization", "")
        if auth.startswith("Bearer "):
            return self.state.tokens.get(auth[7:])
        return None

    def _route(self, method, path, headers, body):
        st = self.state
        uid = self._uid(headers)
        if uid is None:
            return 401, {"error": "unauthorized"}
        parts = path.strip("/").split("/")[1:]  # drop 'api'
        if parts == ["auth", "me"]:
            return 200, {"user": st.users[uid]}
        if parts == ["workspaces"]:
            return 200, {"workspaces": [{k: v for k, v in w.items() if k != "members"}
                                        for w in st.workspaces.values() if uid in w["members"]]}
        if len(parts) == 2 and parts[0] == "workspaces":
            w = st.workspaces.get(parts[1])
            if not w:
                return 404, {"error": "not found"}
            chans = [c for c in st.channels.values()
                     if c["workspace_id"] == w["id"] and (not c["is_private"] or uid in st.members[c["id"]])]
            return 200, {"workspace": {k: v for k, v in w.items() if k != "members"},
                         "channels": chans, "read_state": []}
        if len(parts) == 2 and parts[0] == "users":
            u = st.users.get(int(parts[1]))
            return (200, {"user": u}) if u else (404, {})
        if len(parts) >= 2 and parts[0] == "channels":
            cid = int(parts[1])
            ch = st.channels.get(cid)
            if not ch:
                return 404, {"error": "not found"}
            rest = parts[2:]
            if rest == ["join"] and method == "POST":
                if ch["is_private"] and uid not in st.members[cid]:
                    return 403, {"error": "forbidden"}
                if uid not in st.members[cid]:
                    st.members[cid].add(uid)
                    st.append_event(cid, "member.joined", {"user_id": uid, "user": st.users[uid]})
                return 200, {"channel": ch}
            if rest == ["members"]:
                return 200, {"members": [st.users[m] for m in sorted(st.members[cid])]}
            if rest == ["messages"] and method == "POST":
                b = json.loads(body or b"{}").get("body", "")
                if not b.strip():
                    return 400, {"error": "empty"}
                st.posts.append((self.port, cid, b))
                return 201, {"message": st.post_message(cid, uid, b)}
            if rest == ["messages"]:
                return 200, {"messages": list(reversed(st.messages[cid]))}
            if rest == [] and method == "PATCH":
                ch["topic"] = json.loads(body).get("topic", ch["topic"])
                st.append_event(cid, "channel.updated", {"channel": ch})
                return 200, {"channel": ch}
        return 404, {"error": "no route"}

    async def _ws(self, reader, writer, headers, query):
        uid = self.state.tokens.get(query.get("token", ""))
        if uid is None:
            writer.write(b"HTTP/1.1 401 Unauthorized\r\nContent-Length: 0\r\n\r\n")
            await writer.drain()
            return
        accept = base64.b64encode(hashlib.sha1((headers["sec-websocket-key"] + WS_GUID).encode()).digest()).decode()
        writer.write(("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                      f"Sec-WebSocket-Accept: {accept}\r\n\r\n").encode())
        await writer.drain()
        c = {"writer": writer, "subs": set(), "uid": uid}
        self.wsconns.add(c)
        try:
            while True:
                b1, b2 = await reader.readexactly(2)
                op = b1 & 0x0F
                n = b2 & 0x7F
                if not b2 & 0x80:
                    self.state.unmasked_frames += 1
                if n == 126:
                    n = struct.unpack("!H", await reader.readexactly(2))[0]
                elif n == 127:
                    n = struct.unpack("!Q", await reader.readexactly(8))[0]
                mask = await reader.readexactly(4) if b2 & 0x80 else b"\0\0\0\0"
                data = bytes(x ^ mask[i & 3] for i, x in enumerate(await reader.readexactly(n)))
                if op == 8:
                    break
                if op != 1:
                    continue
                msg = json.loads(data)
                t = msg.get("type")
                cid = msg.get("channel_id")
                if t == "ping":
                    self._send(c, {"type": "pong"})
                elif t == "subscribe" and cid in self.state.channels:
                    c["subs"].add(cid)
                    self._send(c, {"type": "subscribed", "channel_id": cid,
                                   "head_seq": len(self.state.events[cid])})
                elif t == "resume" and cid in self.state.channels:
                    c["subs"].add(cid)
                    for f in self.state.events[cid][msg.get("since_seq", 0):]:
                        self._send(c, f)
                    self._send(c, {"type": "resumed", "channel_id": cid,
                                   "head_seq": len(self.state.events[cid])})
                elif t == "unsubscribe":
                    c["subs"].discard(cid)
        except Exception:  # noqa: BLE001
            pass
        finally:
            self.wsconns.discard(c)
            try:
                writer.close()
            except Exception:  # noqa: BLE001
                pass

"""Test helpers: a scripted IRC client."""
import asyncio
import re


class IRCClient:
    def __init__(self, reader, writer):
        self.reader = reader
        self.writer = writer
        self.seen = []

    @classmethod
    async def connect(cls, port, host="127.0.0.1"):
        r, w = await asyncio.open_connection(host, port)
        return cls(r, w)

    def send(self, line, lf_only=False):
        self.writer.write(line.encode() + (b"\n" if lf_only else b"\r\n"))

    async def readline(self, timeout=5.0):
        raw = await asyncio.wait_for(self.reader.readline(), timeout)
        if not raw:
            raise EOFError("connection closed")
        assert raw.endswith(b"\r\n"), raw
        line = raw.decode().rstrip("\r\n")
        self.seen.append(line)
        return line

    async def expect(self, pattern, timeout=5.0):
        """Read lines until one matches regex ``pattern``; return it."""
        rx = re.compile(pattern)
        loop = asyncio.get_running_loop()
        deadline = loop.time() + timeout
        while True:
            left = deadline - loop.time()
            if left <= 0:
                raise AssertionError(f"timed out waiting for {pattern!r}; seen={self.seen[-15:]}")
            try:
                line = await self.readline(left)
            except asyncio.TimeoutError:
                raise AssertionError(f"timed out waiting for {pattern!r}; seen={self.seen[-15:]}") from None
            if rx.search(line):
                return line

    async def collect(self, duration=0.5):
        out = []
        try:
            while True:
                out.append(await self.readline(duration))
        except (asyncio.TimeoutError, EOFError):
            pass
        return out

    async def register(self, token, nick, expect_ok=True):
        self.send(f"PASS {token}")
        self.send(f"NICK {nick}")
        self.send(f"USER {nick} 0 * :{nick}")
        if expect_ok:
            await self.expect(r" 422 ")

    async def closed(self, timeout=3.0):
        try:
            data = await asyncio.wait_for(self.reader.read(), timeout)
        except asyncio.TimeoutError:
            return False
        return data == b"" or True

    def close(self):
        try:
            self.writer.close()
        except Exception:  # noqa: BLE001
            pass

"""Channel, membership, pins, read-state and DM endpoints."""
import re
import sqlite3

from huddle.api.db import ApiError, Tx, now_iso
from huddle.api.router import route
from huddle.api.core import (body_json, as_int, user_obj, users_by_ids, channel_obj, get_workspace, ws_role,
                             get_channel, is_channel_member, require_read, require_not_archived, messages_obj,
                             read_states, get_user)
from huddle.api import ops

CHANNEL_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,31}$")
TOPIC_MAX = 250


def _topic(v):
    if v is None:
        return ""
    if not isinstance(v, str):
        raise ApiError(400, "topic must be a string")
    if len(v) > TOPIC_MAX:
        raise ApiError(400, f"topic too long (max {TOPIC_MAX})")
    return v


def channel_view(conn, cid, uid=None):
    ch = get_channel(conn, cid)
    o = channel_obj(ch)
    if uid is not None:
        o["is_member"] = is_channel_member(conn, cid, uid)
    if ch["is_dm"]:
        o["member_ids"] = [r[0] for r in conn.execute(
            "SELECT user_id FROM channel_members WHERE channel_id=? ORDER BY user_id", (cid,))]
    return o


@route("POST", "/api/workspaces/{slug}/channels")
def create_channel(ctx):
    conn = ctx.conn
    ws = get_workspace(conn, ctx.params["slug"])
    role = ws_role(conn, ws["id"], ctx.uid)
    if role is None:
        raise ApiError(403, "not a member of this workspace")
    if role == "guest":
        raise ApiError(403, "guests cannot create channels")
    data = body_json(ctx.req)
    name = data.get("name")
    if isinstance(name, str):
        name = name.strip().lstrip("#")
    if not isinstance(name, str) or not CHANNEL_RE.match(name):
        raise ApiError(400, "channel name must be lowercase kebab-case, at most 32 characters")
    is_private = bool(data.get("is_private", False))
    if is_private and role not in ("owner", "admin"):
        raise ApiError(403, "only admins can create private channels")
    topic = _topic(data.get("topic"))
    try:
        with Tx(conn):
            if conn.execute("SELECT 1 FROM channels WHERE workspace_id=? AND name=? AND is_dm=0",
                            (ws["id"], name)).fetchone():
                raise ApiError(409, "channel name already exists")
            now = now_iso()
            cur = conn.execute("INSERT INTO channels(workspace_id, name, is_private, is_dm, topic, created_by, created_at)"
                               " VALUES (?,?,?,0,?,?,?)", (ws["id"], name, int(is_private), topic, ctx.uid, now))
            cid = cur.lastrowid
            conn.execute("INSERT INTO channel_members(channel_id, user_id, joined_at) VALUES (?,?,?)",
                         (cid, ctx.uid, now))
    except sqlite3.IntegrityError:
        raise ApiError(409, "channel name already exists")
    return 201, {"channel": channel_view(conn, cid, ctx.uid)}


@route("GET", "/api/workspaces/{slug}/channels")
def list_ws_channels(ctx):
    from huddle.api.h_workspaces import get_workspace_ep
    res = get_workspace_ep(ctx)
    return {"channels": res["channels"]}


@route("GET", "/api/channels/{id}")
def get_channel_ep(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    require_read(conn, ch, ctx.uid)
    return {"channel": channel_view(conn, ch["id"], ctx.uid)}


def _require_channel_editor(conn, ch, uid):
    if is_channel_member(conn, ch["id"], uid):
        return
    if ws_role(conn, ch["workspace_id"], uid) in ("owner", "admin") and not ch["is_dm"]:
        return
    raise ApiError(403, "must be a channel member to update it")


def set_topic(conn, ch, uid, topic):
    """Shared by PATCH and /topic. Returns the channel view."""
    topic = _topic(topic)
    with Tx(conn) as tx:
        conn.execute("UPDATE channels SET topic=? WHERE id=?", (topic, ch["id"]))
        tx.emit(ch["id"], "channel.updated", {"channel": channel_obj(get_channel(conn, ch["id"]))})
    return channel_view(conn, ch["id"], uid)


@route("PATCH", "/api/channels/{id}")
def patch_channel(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    data = body_json(ctx.req)
    if ch["is_private"] or ch["is_dm"]:
        if not is_channel_member(conn, ch["id"], ctx.uid) and ws_role(conn, ch["workspace_id"], ctx.uid) != "owner":
            raise ApiError(403, "not a member of this channel")
    require_not_archived(ch)
    _require_channel_editor(conn, ch, ctx.uid)
    updates = {}
    if "topic" in data:
        updates["topic"] = _topic(data["topic"])
    if "name" in data and data["name"] != ch["name"] and not ch["is_dm"]:
        name = data["name"]
        if not isinstance(name, str) or not CHANNEL_RE.match(name):
            raise ApiError(400, "invalid channel name")
        updates["name"] = name
    if not updates:
        return {"channel": channel_view(conn, ch["id"], ctx.uid)}
    try:
        with Tx(conn) as tx:
            if "name" in updates and conn.execute(
                    "SELECT 1 FROM channels WHERE workspace_id=? AND name=? AND is_dm=0 AND id<>?",
                    (ch["workspace_id"], updates["name"], ch["id"])).fetchone():
                raise ApiError(409, "channel name already exists")
            sets = ", ".join(f"{k}=?" for k in updates)
            conn.execute(f"UPDATE channels SET {sets} WHERE id=?", list(updates.values()) + [ch["id"]])
            tx.emit(ch["id"], "channel.updated", {"channel": channel_obj(get_channel(conn, ch["id"]))})
    except sqlite3.IntegrityError:
        raise ApiError(409, "channel name already exists")
    return {"channel": channel_view(conn, ch["id"], ctx.uid)}


def join_channel(conn, ch, uid):
    """Join semantics shared with /invite-less flows. Raises ApiError."""
    if is_channel_member(conn, ch["id"], uid):
        return
    if ch["is_dm"] or ch["is_private"]:
        raise ApiError(403, "private channel requires an invitation")
    with Tx(conn) as tx:
        ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (ch["workspace_id"],)).fetchone()
        role = ws_role(conn, ws["id"], uid)
        if role is None:
            if ws["join_mode"] != "open":
                raise ApiError(403, "workspace is invite-only")
            require_not_archived(ch)
            ops.add_workspace_member(tx, ws["id"], uid, "member")
        elif role == "guest":
            raise ApiError(403, "guests cannot join channels")
        require_not_archived(ch)
        ops.add_channel_member(tx, ch["id"], uid)


@route("POST", "/api/channels/{id}/join")
def join_channel_ep(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    join_channel(conn, ch, ctx.uid)
    return {"channel": channel_view(conn, ch["id"], ctx.uid)}


@route("POST", "/api/channels/{id}/leave")
def leave_channel(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    if is_channel_member(conn, ch["id"], ctx.uid):
        with Tx(conn) as tx:
            ops.remove_channel_member(tx, ch["id"], ctx.uid)
    return {"channel": channel_view(conn, ch["id"], ctx.uid)}


@route("GET", "/api/channels/{id}/members")
def channel_members(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    require_read(conn, ch, ctx.uid)
    rows = conn.execute("SELECT user_id FROM channel_members WHERE channel_id=? ORDER BY joined_at, user_id",
                        (ch["id"],)).fetchall()
    ids = [r[0] for r in rows]
    users = users_by_ids(conn, ids)
    return {"members": [users[i] for i in ids if i in users]}


def invite_to_channel(conn, ch, actor, target_uid):
    """Add another user to a channel (used by POST members and /invite)."""
    if not is_channel_member(conn, ch["id"], actor):
        if not (not ch["is_dm"] and ws_role(conn, ch["workspace_id"], actor) in ("owner", "admin")):
            raise ApiError(403, "must be a channel member to invite")
    if ch["is_dm"]:
        raise ApiError(400, "cannot invite to a direct message")
    require_not_archived(ch)
    if get_user(conn, target_uid) is None:
        raise ApiError(404, "user not found")
    with Tx(conn) as tx:
        ws = conn.execute("SELECT * FROM workspaces WHERE id=?", (ch["workspace_id"],)).fetchone()
        if ws_role(conn, ws["id"], target_uid) is None:
            if ws["join_mode"] != "open" and ws_role(conn, ws["id"], actor) not in ("owner", "admin"):
                raise ApiError(403, "user is not a member of this workspace")
            ops.add_workspace_member(tx, ws["id"], target_uid, "member")
        ops.add_channel_member(tx, ch["id"], target_uid)


@route("POST", "/api/channels/{id}/members")
def add_channel_member_ep(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    data = body_json(ctx.req)
    target = None
    if data.get("user_id") is not None:
        target = as_int(data["user_id"], "user_id")
    elif isinstance(data.get("username"), str) and data["username"].strip():
        r = conn.execute("SELECT id FROM users WHERE username=?", (data["username"].strip().lstrip("@"),)).fetchone()
        if r is None:
            raise ApiError(404, "user not found")
        target = r["id"]
    else:
        raise ApiError(400, "user_id or username required")
    invite_to_channel(conn, ch, ctx.uid, target)
    users = users_by_ids(conn, [target])
    return {"channel": channel_view(conn, ch["id"], ctx.uid), "user": users.get(target),
            "invited_user": users.get(target)}


@route("DELETE", "/api/channels/{id}/members/{user_id}")
def remove_channel_member_ep(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    target = ctx.pint("user_id")
    if target != ctx.uid and ws_role(conn, ch["workspace_id"], ctx.uid) not in ("owner", "admin"):
        raise ApiError(403, "admin or owner required")
    with Tx(conn) as tx:
        ops.remove_channel_member(tx, ch["id"], target)
    return {"channel": channel_view(conn, ch["id"], ctx.uid)}


def set_archived(conn, ch, uid, archived):
    if ch["is_dm"]:
        raise ApiError(400, "cannot archive a direct message")
    if ws_role(conn, ch["workspace_id"], uid) != "owner":
        raise ApiError(403, "only the workspace owner can archive channels")
    with Tx(conn) as tx:
        cur = conn.execute("UPDATE channels SET is_archived=? WHERE id=? AND is_archived<>?",
                           (int(archived), ch["id"], int(archived)))
        if cur.rowcount:
            tx.emit(ch["id"], "channel.archived" if archived else "channel.unarchived",
                    {"channel": channel_obj(get_channel(conn, ch["id"]))})
    return channel_view(conn, ch["id"], uid)


@route("POST", "/api/channels/{id}/archive")
def archive_channel(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    return {"channel": set_archived(conn, ch, ctx.uid, True)}


@route("POST", "/api/channels/{id}/unarchive")
def unarchive_channel(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    return {"channel": set_archived(conn, ch, ctx.uid, False)}


@route("GET", "/api/channels/{id}/pins")
def list_pins(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    require_read(conn, ch, ctx.uid)
    rows = conn.execute(
        "SELECT p.pinned_by, p.pinned_at, m.* FROM pins p JOIN messages m ON m.id=p.message_id"
        " WHERE p.channel_id=? AND m.deleted_at IS NULL ORDER BY p.pinned_at DESC, p.rowid DESC",
        (ch["id"],)).fetchall()
    msgs = messages_obj(conn, rows)
    return {"pins": [{"message": m, "message_id": m["id"], "pinned_by": r["pinned_by"], "pinned_at": r["pinned_at"]}
                     for r, m in zip(rows, msgs)]}


# ---------------------------------------------------------------- read state

@route("GET", "/api/channels/{id}/read")
def get_read(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    require_read(conn, ch, ctx.uid)
    return {"read_state": read_states(conn, ctx.uid, [ch["id"]])[ch["id"]]}


@route("POST", "/api/channels/{id}/read")
def post_read(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    require_read(conn, ch, ctx.uid)
    data = body_json(ctx.req)
    seq = data.get("last_read_seq")
    if seq is None:
        from huddle import events
        seq = events.head_seq(conn, ch["id"])
    seq = as_int(seq, "last_read_seq")
    if seq < 0:
        raise ApiError(400, "last_read_seq must be >= 0")
    conn.execute(
        "INSERT INTO read_state(user_id, channel_id, last_read_seq, updated_at) VALUES (?,?,?,?)"
        " ON CONFLICT(user_id, channel_id) DO UPDATE SET"
        " last_read_seq=MAX(last_read_seq, excluded.last_read_seq), updated_at=excluded.updated_at",
        (ctx.uid, ch["id"], seq, now_iso()))
    return {"read_state": read_states(conn, ctx.uid, [ch["id"]])[ch["id"]]}


# ---------------------------------------------------------------- DMs

@route("POST", "/api/dms")
def open_dm(ctx):
    conn = ctx.conn
    data = body_json(ctx.req)
    other = data.get("user_id")
    if other is None and isinstance(data.get("username"), str):
        r = conn.execute("SELECT id FROM users WHERE username=?", (data["username"].lstrip("@"),)).fetchone()
        if r is None:
            raise ApiError(404, "user not found")
        other = r["id"]
    other = as_int(other, "user_id")
    if get_user(conn, other) is None:
        raise ApiError(404, "user not found")
    a, b = sorted((ctx.uid, other))
    key = f"{a}:{b}"
    row = conn.execute("SELECT id FROM channels WHERE dm_key=?", (key,)).fetchone()
    if row is None:
        ws_id = data.get("workspace_id")
        ws_id = as_int(ws_id, "workspace_id") if ws_id is not None else None
        try:
            with Tx(conn):
                row = conn.execute("SELECT id FROM channels WHERE dm_key=?", (key,)).fetchone()
                if row is None:
                    now = now_iso()
                    cur = conn.execute(
                        "INSERT INTO channels(workspace_id, name, is_private, is_dm, topic, created_by, dm_key, created_at)"
                        " VALUES (?,?,1,1,'',?,?,?)", (ws_id, f"dm-{a}-{b}", ctx.uid, key, now))
                    cid = cur.lastrowid
                    conn.executemany("INSERT OR IGNORE INTO channel_members(channel_id, user_id, joined_at)"
                                     " VALUES (?,?,?)", [(cid, a, now), (cid, b, now)])
                else:
                    cid = row["id"]
        except sqlite3.IntegrityError:
            cid = conn.execute("SELECT id FROM channels WHERE dm_key=?", (key,)).fetchone()["id"]
    else:
        cid = row["id"]
    ch = channel_view(conn, cid, ctx.uid)
    ch["other_user"] = user_obj(get_user(conn, other))
    return 200, {"channel_id": cid, "channel": ch}


@route("GET", "/api/dms")
def list_dms(ctx):
    conn = ctx.conn
    rows = conn.execute(
        "SELECT c.* FROM channels c JOIN channel_members cm ON cm.channel_id=c.id AND cm.user_id=?"
        " WHERE c.is_dm=1 ORDER BY c.id", (ctx.uid,)).fetchall()
    out = []
    rs = read_states(conn, ctx.uid, [r["id"] for r in rows])
    for r in rows:
        o = channel_obj(r)
        a, b = (int(x) for x in r["dm_key"].split(":"))
        other = b if a == ctx.uid else a
        o["member_ids"] = [a, b] if a != b else [a]
        o["other_user"] = user_obj(get_user(conn, other))
        o.update({k: v for k, v in rs[r["id"]].items() if k != "channel_id"})
        out.append(o)
    return {"channels": out, "dms": out}

"""Huddle HTTP node: REST (delegated to huddle.api.app.handle_api), WebSocket fan-out, static SPA.

Run: python3 -m huddle.node --node-id N   (listens on 127.0.0.1:BASE_PORT+N)

Fan-out design (Redis is only a fast path, sqlite is the source of truth):
  * API worker threads call events.publish(frame) after commit -> handed to this loop, delivered to
    local subscribers immediately and PUBLISHed on Redis channel ``huddle:events``.
  * Every node SUBSCRIBEs to Redis (reconnect loop, backoff <= 1 s) and ALSO tails
    ``channel_events`` / ``global_events`` in sqlite every ~40 ms.
  * Per channel the node delivers strictly in seq order (``next_seq``), buffering out-of-order frames
    until the gap is filled (the db tail always fills it); duplicates from the three sources are
    dropped, and each WS connection additionally filters on its own last delivered seq.
"""
