WS_MAX_BUFFER = 16 * 1024 * 1024     # slow WS consumer cut-off
TAIL_INTERVAL = 0.04
PRESENCE_INTERVAL = 2.0
API_WORKERS = 32
REDIS_EVENTS = b"huddle:events"
REDIS_GLOBAL = b"huddle:global"

