def log(*a):
    print(time.strftime("%H:%M:%S"), *a, file=sys.stderr, flush=True)


def err_body(code, message):
    return {"error": {"code": code, "message": message}}


# ---------------------------------------------------------------------------------------------
# Minimal async Redis (RESP2) client
# ---------------------------------------------------------------------------------------------
async def resp_read(reader):
    line = await reader.readline()
    if not line:
        raise ConnectionError("redis eof")
    t, rest = line[:1], line[1:-2]
    if t == b"+":
        return rest.decode()
    if t == b"-":
        return Exception(rest.decode())
    if t == b":":
        return int(rest)
    if t == b"$":
        n = int(rest)
        if n < 0:
            return None
        return (await reader.readexactly(n + 2))[:-2]
    if t == b"*":
        n = int(rest)
        if n < 0:
            return None
        return [await resp_read(reader) for _ in range(n)]
    raise ConnectionError("bad RESP type %r" % t)


def resp_cmd(*args):
    out = [b"*%d\r\n" % len(args)]
    for a in args:
        if isinstance(a, str):
            a = a.encode()
        out.append(b"$%d\r\n%s\r\n" % (len(a), a))
    return b"".join(out)


class RedisLink:
    """Publisher + subscriber connections with independent reconnect loops (backoff <= 1 s)."""

    def __init__(self, hub, host, port):
        self.hub = hub
        self.host = host
        self.port = port
        self.pub_writer = None
        self.sub_up = False

    def publish(self, channel, data):
        w = self.pub_writer
        if w is None or w.is_closing():
            return False
        try:
            if w.transport.get_write_buffer_size() > 8 * 1024 * 1024:
                return False
            w.write(resp_cmd(b"PUBLISH", channel, data))
            return True
        except Exception:  # noqa: BLE001
            self.pub_writer = None
            return False

    async def _connect(self):
        r, w = await asyncio.wait_for(asyncio.open_connection(self.host, self.port), 1.0)
        try:
            w.get_extra_info("socket").setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except Exception:  # noqa: BLE001
            pass
        return r, w

    async def run_publisher(self):
        backoff = 0.05
        while True:
            w = None
            try:
                r, w = await self._connect()
                self.pub_writer = w
                backoff = 0.05
                while True:  # drain replies; EOF means redis went away
                    await resp_read(r)
            except asyncio.CancelledError:
                raise
            except Exception:  # noqa: BLE001
                pass
            self.pub_writer = None
            if w is not None:
                try:
                    w.close()
                except Exception:  # noqa: BLE001
                    pass
            await asyncio.sleep(backoff)
            backoff = min(1.0, backoff * 2)

    async def run_subscriber(self):
        backoff = 0.05
        while True:
            w = None
            try:
                r, w = await self._connect()
                w.write(resp_cmd(b"SUBSCRIBE", REDIS_EVENTS, REDIS_GLOBAL))
                await w.drain()
                self.sub_up = True
                backoff = 0.05
                while True:
                    msg = await resp_read(r)
                    if isinstance(msg, list) and len(msg) == 3 and msg[0] == b"message":
                        self.hub.on_redis_message(msg[1], msg[2])
            except asyncio.CancelledError:
                raise
            except Exception:  # noqa: BLE001
                pass
            self.sub_up = False
            if w is not None:
                try:
                    w.close()
                except Exception:  # noqa: BLE001
                    pass
            await asyncio.sleep(backoff)
            backoff = min(1.0, backoff * 2)


# ---------------------------------------------------------------------------------------------
# WebSocket connection + hub
# ---------------------------------------------------------------------------------------------
class WSConn:
    def __init__(self, hub, writer, user_id):
        self.hub = hub
        self.writer = writer
        self.user_id = user_id
        self.subs = {}  # channel_id -> last seq delivered to this connection
        self.closed = False

    def send_raw(self, data):
        if self.closed:
            return
        try:
            self.writer.write(data)
            if self.writer.transport.get_write_buffer_size() > WS_MAX_BUFFER:
                log("ws: slow consumer, closing user", self.user_id)
                self.closed = True
                self.writer.transport.abort()
        except Exception:  # noqa: BLE001
            self.closed = True

    def send(self, obj):
        self.send_raw(wsproto.encode_frame(json.dumps(obj, separators=(",", ":")).encode()))


class Hub:
    def __init__(self, node_id, loop):
        self.node_id = node_id
        self.loop = loop
        self.conns = set()
        self.chan_subs = {}       # channel_id -> set(WSConn)
        self.next_seq = {}        # channel_id -> next seq this node will deliver
        self.pending = {}         # channel_id -> {seq: (frame, encoded_bytes|None)}
        self.pending_since = {}   # channel_id -> monotonic time the gap was first seen
        self.user_counts = {}     # user_id -> number of open WS on this node
        self.seen_gids = set()
        self.seen_gid_order = collections.deque()
        self.presence_dirty = threading.Event()
        self.bg = concurrent.futures.ThreadPoolExecutor(max_workers=4, thread_name_prefix="bg")
        self.redis = RedisLink(self, config.HOST, config.REDIS_PORT)
        self.db = config.connect()  # loop-thread connection (reads only)
        self.stats = collections.Counter()

    # ---- thread-safe entry points used by huddle.events ----
    def publish_threadsafe(self, frame):
        self.loop.call_soon_threadsafe(self._publish_local, frame)

    def publish_global_threadsafe(self, gid, frame):
        self.loop.call_soon_threadsafe(self._publish_global_local, gid, frame)

    def submit_background(self, fn, *args):
        self.bg.submit(fn, *args)

    def local_online_ids(self):
        return {u for u, n in dict(self.user_counts).items() if n > 0}

    # ---- sources ----
    def _publish_local(self, frame):
        try:
            data = json.dumps(frame, separators=(",", ":")).encode()
        except Exception:  # noqa: BLE001
            return
        self.on_frame(frame, None)
        self.redis.publish(REDIS_EVENTS, data)

    def _publish_global_local(self, gid, frame):
        self.on_global(gid, frame)
        try:
            self.redis.publish(REDIS_GLOBAL, json.dumps({"gid": gid, "node": self.node_id, "frame": frame}).encode())
        except Exception:  # noqa: BLE001
            pass

    def on_redis_message(self, channel, data):
        try:
            obj = json.loads(data)
        except ValueError:
            return
        if channel == REDIS_EVENTS:
            self.stats["redis_frames"] += 1
            self.on_frame(obj, None)
        elif channel == REDIS_GLOBAL and isinstance(obj, dict):
            self.on_global(obj.get("gid"), obj.get("frame") or {})

    def on_tail(self, frames, globals_):
        for f in frames:
            self.on_frame(f, None)
        for gid, f in globals_:
            self.on_global(gid, f)

    # ---- ordered per-channel delivery ----
    def on_frame(self, frame, _enc=None):
        try:
            cid = int(frame["channel_id"])
            seq = int(frame["seq"])
        except (KeyError, TypeError, ValueError):
            return
        nxt = self.next_seq.get(cid)
        if nxt is None or seq < nxt:
            return  # nobody here cares, or duplicate
        pend = self.pending.setdefault(cid, {})
        if seq in pend:
            return
        pend[seq] = frame
        self._flush(cid)

    def _flush(self, cid):
        pend = self.pending.get(cid)
        nxt = self.next_seq.get(cid)
        if pend is None or nxt is None:
            return
        while nxt in pend:
            frame = pend.pop(nxt)
            self._deliver(cid, nxt, frame)
            nxt += 1
        self.next_seq[cid] = nxt
        if pend:
            self.pending_since.setdefault(cid, time.monotonic())
        else:
            self.pending_since.pop(cid, None)
            self.pending.pop(cid, None)

    def _deliver(self, cid, seq, frame):
        subs = self.chan_subs.get(cid)
        if not subs:
            return
        data = None
        for c in list(subs):
            if seq > c.subs.get(cid, 1 << 62):
                if data is None:
                    data = wsproto.encode_frame(json.dumps(frame, separators=(",", ":")).encode())
                c.send_raw(data)
                c.subs[cid] = seq
        self.stats["delivered"] += 1

    def track(self, cid, head):
        if cid not in self.next_seq:
            self.next_seq[cid] = head + 1
            self.pending.pop(cid, None)
            self.pending_since.pop(cid, None)

    def untrack_if_idle(self, cid):
        if not self.chan_subs.get(cid):
            self.chan_subs.pop(cid, None)
            self.next_seq.pop(cid, None)
            self.pending.pop(cid, None)
            self.pending_since.pop(cid, None)

    def fill_gaps(self):
        """Safety net: if a gap persisted, read the missing rows straight from the db."""
        now = time.monotonic()
        for cid, since in list(self.pending_since.items()):
            if now - since < 0.3:
                continue
            nxt = self.next_seq.get(cid)
            if nxt is None:
                continue
            try:
                rows = self.db.execute(
                    "SELECT seq, type, payload FROM channel_events WHERE channel_id=? AND seq>=? "
                    "ORDER BY seq LIMIT 5000", (cid, nxt)).fetchall()
            except sqlite3.Error:
                continue
            self.stats["gap_fills"] += 1
            for r in rows:
                self.on_frame(events.row_to_frame(cid, r[0], r[1], r[2]))
            self.pending_since.pop(cid, None)
            if self.pending.get(cid):
                self.pending_since[cid] = now

    # ---- global frames ----
    def on_global(self, gid, frame):
        if gid is not None:
            if gid in self.seen_gids:
                return
            self.seen_gids.add(gid)
            self.seen_gid_order.append(gid)
            while len(self.seen_gid_order) > 20000:
                self.seen_gids.discard(self.seen_gid_order.popleft())
        if not isinstance(frame, dict) or not frame:
            return
        data = wsproto.encode_frame(json.dumps(frame, separators=(",", ":")).encode())
        for c in list(self.conns):
            c.send_raw(data)

    # ---- connection bookkeeping ----
    def add_conn(self, c):
        self.conns.add(c)
        self.user_counts[c.user_id] = self.user_counts.get(c.user_id, 0) + 1
        self.presence_dirty.set()

    def remove_conn(self, c):
        c.closed = True
        if c in self.conns:
            self.conns.discard(c)
            n = self.user_counts.get(c.user_id, 0) - 1
            if n <= 0:
                self.user_counts.pop(c.user_id, None)
            else:
                self.user_counts[c.user_id] = n
            self.presence_dirty.set()
        for cid in list(c.subs):
            s = self.chan_subs.get(cid)
            if s:
                s.discard(c)
            self.untrack_if_idle(cid)
        c.subs.clear()


# ---------------------------------------------------------------------------------------------
# sqlite tail thread (fallback fan-out + presence heartbeat)
# ---------------------------------------------------------------------------------------------
class Tailer(threading.Thread):
    def __init__(self, hub):
        super().__init__(daemon=True, name="tail")
        self.hub = hub
        self.stop = threading.Event()
        self.conn = None
        self.last_ev = 0
        self.last_g = 0

    def _open(self):
        while not self.stop.is_set():
            try:
                c = config.connect()
                events.ensure_schema(c)
                self.last_ev = c.execute("SELECT COALESCE(MAX(id),0) FROM channel_events").fetchone()[0]
                self.last_g = c.execute("SELECT COALESCE(MAX(id),0) FROM global_events").fetchone()[0]
                return c
            except Exception as e:  # noqa: BLE001
                log("tail: open failed", e)
                time.sleep(0.5)

    def run(self):
        self.conn = self._open()
        last_presence = 0.0
        while not self.stop.is_set():
            busy = False
            try:
                rows = self.conn.execute(
                    "SELECT id, channel_id, seq, type, payload FROM channel_events WHERE id>? ORDER BY id LIMIT 2000",
                    (self.last_ev,)).fetchall()
                grows = self.conn.execute(
                    "SELECT id, payload FROM global_events WHERE id>? ORDER BY id LIMIT 500",
                    (self.last_g,)).fetchall()
                if rows or grows:
                    frames = [events.row_to_frame(r[1], r[2], r[3], r[4]) for r in rows]
                    gl = []
                    for r in grows:
                        try:
                            gl.append((r[0], json.loads(r[1])))
                        except ValueError:
                            pass
                    if rows:
                        self.last_ev = rows[-1][0]
                    if grows:
                        self.last_g = grows[-1][0]
                    busy = len(rows) == 2000 or len(grows) == 500
                    self.hub.loop.call_soon_threadsafe(self.hub.on_tail, frames, gl)
                now = time.time()
                if self.hub.presence_dirty.is_set() or now - last_presence > PRESENCE_INTERVAL:
                    self.hub.presence_dirty.clear()
                    self.write_presence(now)
                    last_presence = now
            except Exception as e:  # noqa: BLE001
                log("tail error:", e)
                time.sleep(0.2)
            if not busy:
                self.stop.wait(TAIL_INTERVAL)

    def write_presence(self, now):
        counts = dict(self.hub.user_counts)
        c = self.conn
        try:
            c.execute("BEGIN IMMEDIATE")
            c.execute("DELETE FROM ws_presence WHERE node_id=?", (self.hub.node_id,))
            c.executemany("INSERT INTO ws_presence(node_id, user_id, conn_count, heartbeat_at) VALUES (?,?,?,?)",
                          [(self.hub.node_id, u, n, now) for u, n in counts.items() if n > 0])
            c.execute("DELETE FROM ws_presence WHERE heartbeat_at<?", (now - 60,))
            c.execute("COMMIT")
        except Exception:  # noqa: BLE001
            try:
                c.execute("ROLLBACK")
            except Exception:  # noqa: BLE001
                pass
            self.hub.presence_dirty.set()


# ---------------------------------------------------------------------------------------------
# HTTP server
# ---------------------------------------------------------------------------------------------
class HTTPError(Exception):
    pass


class Node:
    def __init__(self, node_id, port):
        self.node_id = node_id
        self.port = port
        self.loop = None
        self.hub = None
        self.pool = concurrent.futures.ThreadPoolExecutor(max_workers=API_WORKERS, thread_name_prefix="api")
        self._api = None
        self._api_err_at = 0.0

    # ---- API import (lazy, tolerant of a broken api module) ----
    def api_handler(self):
        if self._api is not None:
            return self._api
        if time.time() - self._api_err_at < 1.0:
            return None
        try:
            from huddle.api.app import handle_api  # noqa: PLC0415
            self._api = handle_api
        except Exception:  # noqa: BLE001
            self._api_err_at = time.time()
            log("api import failed:\n" + traceback.format_exc())
            return None
        return self._api

    def _call_api(self, req):
        h = self.api_handler()
        if h is None:
            if req.path.rstrip("/") == "/api/health":
                return Response(200, {"status": "ok", "node_id": self.node_id})
            return Response(503, err_body("unavailable", "API module unavailable"))
        try:
            resp = h(req)
            if not isinstance(resp, Response):
                if isinstance(resp, (dict, list)):
                    resp = Response(200, resp)
                else:
                    raise TypeError("handle_api returned %r" % type(resp))
            return resp
        except Exception:  # noqa: BLE001
            log("handle_api error %s %s:\n%s" % (req.method, req.path, traceback.format_exc()))
            if req.path.rstrip("/") == "/api/health":
                return Response(200, {"status": "ok", "node_id": self.node_id})
            return Response(500, err_body("internal", "internal server error"))

    # ---- static files ----
    def static_response(self, path):
        if path.startswith("/static/"):
            rel = urllib.parse.unquote(path[len("/static/"):])
        else:
            rel = "index.html"
        base = os.path.realpath(config.STATIC_DIR)
        full = os.path.realpath(os.path.join(base, rel))
        if not (full == base or full.startswith(base + os.sep)) or not os.path.isfile(full):
            if rel == "index.html":
                html = "<!doctype html><html><head><title>Huddle</title></head><body><h1>Huddle</h1></body></html>"
                return Response(200, html, {"Cache-Control": "no-store"}, "text/html; charset=utf-8")
            return Response(404, err_body("not_found", "no such file"))
        with open(full, "rb") as f:
            data = f.read()
        ctype = mimetypes.guess_type(full)[0] or "application/octet-stream"
        if ctype.startswith("text/") or ctype in ("application/json", "application/javascript"):
            ctype += "; charset=utf-8"
        headers = {"Cache-Control": "no-store"} if full.endswith(".html") else {"Cache-Control": "no-cache"}
        return Response(200, data, headers, ctype)

    # ---- response writing ----
    def write_response(self, writer, resp, keep_alive, head_only=False):
        try:
            ctype, body = resp.encode()
        except Exception:  # noqa: BLE001
            log("bad response body:\n" + traceback.format_exc())
            resp = Response(500, err_body("internal", "bad response"))
            ctype, body = resp.encode()
        status = int(resp.status)
        try:
            reason = http.HTTPStatus(status).phrase
        except ValueError:
            reason = "Status"
        headers = dict(CORS_HEADERS)
        lower = {k.lower() for k in resp.headers}
        if ctype and "content-type" not in lower:
            headers["Content-Type"] = ctype
        headers.update(resp.headers)
        headers = {k: v for k, v in headers.items() if k.lower() not in ("content-length", "connection")}
        no_body = status in (204, 304) or 100 <= status < 200
        if not no_body:
            headers["Content-Length"] = str(len(body))
        headers["Connection"] = "keep-alive" if keep_alive else "close"
        lines = ["HTTP/1.1 %d %s" % (status, reason)]
        for k, v in headers.items():
            lines.append("%s: %s" % (k, str(v).replace("\r", "").replace("\n", "")))
        out = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1", "replace")
        if not head_only and not no_body:
            out += body
        writer.write(out)

    async def handle_conn(self, reader, writer):
        try:
            sock = writer.get_extra_info("socket")
            if sock is not None:
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except Exception:  # noqa: BLE001
            pass
        try:
            while True:
                try:
                    head = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), timeout=120)
                except (asyncio.IncompleteReadError, asyncio.TimeoutError, ConnectionError):
                    return
                except asyncio.LimitOverrunError:
                    self.write_response(writer, Response(431, err_body("bad_request", "headers too large")), False)
                    return
                try:
                    lines = head.decode("latin-1").split("\r\n")
                    method, target, version = lines[0].split(" ", 2)
                except ValueError:
                    self.write_response(writer, Response(400, err_body("bad_request", "bad request line")), False)
                    return
                headers = {}
                for ln in lines[1:]:
                    if not ln:
                        continue
                    k, _, v = ln.partition(":")
                    k = k.strip().lower()
                    v = v.strip()
                    headers[k] = (headers[k] + ", " + v) if k in headers and k not in ("content-length",) else v
                parsed = urllib.parse.urlsplit(target)
                path = urllib.parse.unquote(parsed.path) or "/"
                query = {}
                for k, v in urllib.parse.parse_qsl(parsed.query, keep_blank_values=True):
                    query.setdefault(k, v)
                conn_hdr = headers.get("connection", "").lower()
                keep_alive = ("close" not in conn_hdr) if version.upper() == "HTTP/1.1" else ("keep-alive" in conn_hdr)
                method = method.upper()

                if path == "/api/ws" and "websocket" in headers.get("upgrade", "").lower():
                    await self.handle_ws(reader, writer, headers, query)
                    return

                # ---- body ----
                body = b""
                te = headers.get("transfer-encoding", "").lower()
                if "chunked" in te:
                    body = await self.read_chunked(reader, writer, headers)
                    if body is None:
                        self.write_response(writer, Response(413, err_body("payload_too_large", "request body too large")), False)
                        await self._drain_close(writer)
                        return
                else:
                    try:
                        n = int(headers.get("content-length", "0") or 0)
                    except ValueError:
                        self.write_response(writer, Response(400, err_body("bad_request", "bad content-length")), False)
                        return
                    if n < 0:
                        n = 0
                    if n > MAX_BODY:
                        if "100-continue" in headers.get("expect", "").lower() or n > MAX_DRAIN:
                            self.write_response(writer, Response(413, err_body("payload_too_large", "request body too large")), False)
                            await self._drain_close(writer)
                            return
                        await self._discard(reader, n)
                        self.write_response(writer, Response(413, err_body("payload_too_large", "request body too large")), keep_alive)
                        await writer.drain()
                        if not keep_alive:
                            return
                        continue
                    if n:
                        if "100-continue" in headers.get("expect", "").lower():
                            writer.write(b"HTTP/1.1 100 Continue\r\n\r\n")
                        body = await reader.readexactly(n)

                req = Request(method, path, query, headers, body, self.node_id)
                head_only = method == "HEAD"
                resp = await self.dispatch(req)
                self.write_response(writer, resp, keep_alive, head_only)
                await writer.drain()
                if not keep_alive:
                    return
        except (ConnectionError, asyncio.IncompleteReadError, OSError):
            pass
        except Exception:  # noqa: BLE001
            log("conn error:\n" + traceback.format_exc())
        finally:
            try:
                writer.close()
            except Exception:  # noqa: BLE001
                pass

    async def _discard(self, reader, n):
        while n > 0:
            chunk = await reader.read(min(n, 1 << 20))
            if not chunk:
                raise ConnectionError("eof")
            n -= len(chunk)

    async def _drain_close(self, writer):
        try:
            await asyncio.wait_for(writer.drain(), 2)
        except Exception:  # noqa: BLE001
            pass

    async def read_chunked(self, reader, writer, headers):
        if "100-continue" in headers.get("expect", "").lower():
            writer.write(b"HTTP/1.1 100 Continue\r\n\r\n")
        parts = []
        total = 0
        while True:
            line = await reader.readline()
            size = int(line.split(b";")[0].strip() or b"0", 16)
            if size == 0:
                while True:  # trailers
                    t = await reader.readline()
                    if t in (b"\r\n", b"\n", b""):
                        break
                return b"".join(parts)
            total += size
            if total > MAX_BODY:
                return None
            parts.append(await reader.readexactly(size))
            await reader.readexactly(2)

    async def dispatch(self, req):
        p = req.path
        if req.method == "OPTIONS":
            return Response(204, None)
        if p == "/api" or p.startswith("/api/"):
            if p == "/api/ws":
                return Response(426, err_body("upgrade_required", "WebSocket upgrade required"))
            return await self.loop.run_in_executor(self.pool, self._call_api, req)
        if req.method not in ("GET", "HEAD"):
            return Response(405, err_body("method_not_allowed", "method not allowed"))
        if p == "/favicon.ico" and not os.path.isfile(os.path.join(config.STATIC_DIR, "favicon.ico")):
            return Response(204, None)
        if p.startswith("/static/"):
            return self.static_response(p)
        return self.static_response("/")

    # ---- WebSocket ----
    def lookup_token(self, token):
        if not token:
            return None
        try:
            row = self.hub.db.execute("SELECT user_id FROM tokens WHERE token=?", (token,)).fetchone()
        except sqlite3.Error:
            return None
        return int(row[0]) if row and row[0] is not None else None

    async def handle_ws(self, reader, writer, headers, query):
        token = query.get("token") or ""
        auth = headers.get("authorization", "")
        if not token and auth.lower().startswith("bearer "):
            token = auth[7:].strip()
        key = headers.get("sec-websocket-key")
        if not key or headers.get("sec-websocket-version", "13").strip() != "13":
            self.write_response(writer, Response(400, err_body("bad_request", "bad websocket handshake"),
                                                 {"Sec-WebSocket-Version": "13"}), False)
            await self._drain_close(writer)
            return
        user_id = self.lookup_token(token)
        if user_id is None:
            self.write_response(writer, Response(401, err_body("unauthorized", "invalid or missing token")), False)
            await self._drain_close(writer)
            return
        lines = ["HTTP/1.1 101 Switching Protocols", "Upgrade: websocket", "Connection: Upgrade",
                 "Sec-WebSocket-Accept: " + wsproto.accept_key(key)]
        proto = headers.get("sec-websocket-protocol")
        if proto:
            lines.append("Sec-WebSocket-Protocol: " + proto.split(",")[0].strip())
        writer.write(("\r\n".join(lines) + "\r\n\r\n").encode())
        conn = WSConn(self.hub, writer, user_id)
        self.hub.add_conn(conn)
        try:
            while not conn.closed:
                try:
                    op, payload = await wsproto.read_message(reader, conn.send_raw)
                except wsproto.WSClosed as e:
                    conn.send_raw(wsproto.encode_frame(wsproto.close_payload(e.code if e.code < 4000 or e.code >= 1000 else 1000), wsproto.OP_CLOSE))
                    break
                self.handle_ws_message(conn, payload)
                if writer.transport.get_write_buffer_size() > 1024 * 1024:
                    await writer.drain()
        except (ConnectionError, asyncio.IncompleteReadError, OSError):
            pass
        finally:
            self.hub.remove_conn(conn)
            try:
                await asyncio.wait_for(writer.drain(), 1)
            except Exception:  # noqa: BLE001
                pass

    def ws_error(self, conn, code, message, **extra):
        f = {"type": "error", "code": code, "message": message}
        f.update(extra)
        conn.send(f)

    def check_channel(self, conn, cid):
        """Return None if the user may watch the channel, else (code, message)."""
        db = self.hub.db
        try:
            row = db.execute("SELECT * FROM channels WHERE id=?", (cid,)).fetchone()
        except sqlite3.Error:
            row = None
        if row is None:
            return ("not_found", "unknown channel")
        keys = row.keys()
        private = (row["is_private"] if "is_private" in keys else 0) or (row["is_dm"] if "is_dm" in keys else 0)
        if private:
            try:
                m = db.execute("SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?",
                               (cid, conn.user_id)).fetchone()
            except sqlite3.Error:
                m = None
            if m is None:
                return ("forbidden", "not a member of this channel")
        return None

    def handle_ws_message(self, conn, payload):
        try:
            msg = json.loads(payload.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            self.ws_error(conn, "bad_request", "invalid JSON")
            return
        if not isinstance(msg, dict):
            self.ws_error(conn, "bad_request", "frame must be an object")
            return
        t = msg.get("type")
        if t == "ping":
            out = {"type": "pong"}
            if "id" in msg:
                out["id"] = msg["id"]
            conn.send(out)
            return
        if t not in ("subscribe", "resume", "unsubscribe"):
            self.ws_error(conn, "bad_request", "unknown frame type", request_type=t)
            return
        try:
            cid = int(msg.get("channel_id"))
        except (TypeError, ValueError):
            self.ws_error(conn, "bad_request", "channel_id required", request_type=t)
            return
        hub = self.hub
        if t == "unsubscribe":
            conn.subs.pop(cid, None)
            s = hub.chan_subs.get(cid)
            if s:
                s.discard(conn)
            hub.untrack_if_idle(cid)
            conn.send({"type": "unsubscribed", "channel_id": cid})
            return
        denied = self.check_channel(conn, cid)
        if denied:
            self.ws_error(conn, denied[0], denied[1], channel_id=cid, request_type=t)
            return
        db = hub.db
        if t == "subscribe":
            head = events.head_seq(db, cid)
            hub.track(cid, head)
            conn.subs[cid] = head
            hub.chan_subs.setdefault(cid, set()).add(conn)
            conn.send({"type": "subscribed", "channel_id": cid, "head_seq": head})
            return
        # resume
        try:
            since = int(msg.get("since_seq", 0) or 0)
        except (TypeError, ValueError):
            self.ws_error(conn, "bad_request", "since_seq must be an integer", channel_id=cid, request_type=t)
            return
        try:
            db.execute("BEGIN")
            try:
                head = events.head_seq(db, cid)
                earliest = None
                rows = []
                if head:
                    earliest = db.execute("SELECT MIN(seq) FROM channel_events WHERE channel_id=?",
                                          (cid,)).fetchone()[0]
                    rows = db.execute(
                        "SELECT seq, type, payload FROM channel_events WHERE channel_id=? AND seq>? ORDER BY seq",
                        (cid, since)).fetchall()
            finally:
                db.execute("COMMIT")
        except sqlite3.Error as e:
            self.ws_error(conn, "internal", "resume failed: %s" % e, channel_id=cid, request_type=t)
            return
        if earliest is not None and since < earliest - 1:
            conn.send({"type": "resume.gap", "channel_id": cid, "earliest_seq": earliest})
        for r in rows:
            conn.send(events.row_to_frame(cid, r[0], r[1], r[2]))
        hub.track(cid, head)
        conn.subs[cid] = head
        hub.chan_subs.setdefault(cid, set()).add(conn)
        conn.send({"type": "resumed", "channel_id": cid, "head_seq": head})

    # ---- lifecycle ----
    async def periodic(self):
        while True:
            await asyncio.sleep(0.1)
            try:
                self.hub.fill_gaps()
            except Exception:  # noqa: BLE001
                log("fill_gaps error:\n" + traceback.format_exc())

    async def main(self):
        self.loop = asyncio.get_running_loop()
        self.loop.set_default_executor(concurrent.futures.ThreadPoolExecutor(max_workers=8))
        # Schema for tables we own (retry: the db may be busy).
        for _ in range(50):
            try:
                c = config.connect()
                events.ensure_schema(c)
                c.execute("DELETE FROM ws_presence WHERE node_id=?", (self.node_id,))
                c.close()
                break
            except Exception as e:  # noqa: BLE001
                log("schema init retry:", e)
                await asyncio.sleep(0.2)
        self.hub = Hub(self.node_id, self.loop)
        events.set_hub(self.hub)
        tail = Tailer(self.hub)
        tail.start()
        tasks = [asyncio.ensure_future(self.hub.redis.run_subscriber()),
                 asyncio.ensure_future(self.hub.redis.run_publisher()),
                 asyncio.ensure_future(self.periodic())]
        # Warm the API import in the background so the first request is fast.
        self.loop.run_in_executor(self.pool, self.api_handler)
        server = None
        for attempt in range(100):
            try:
                server = await asyncio.start_server(self.handle_conn, config.HOST, self.port,
                                                    reuse_address=True, limit=MAX_HEADER, backlog=1024)
                break
            except OSError as e:
                log("bind %d failed (%s), retrying" % (self.port, e))
                await asyncio.sleep(0.3)
        if server is None:
            raise SystemExit("could not bind port %d" % self.port)
        log("node %d listening on %s:%d (redis %d, db %s)" % (self.node_id, config.HOST, self.port,
                                                             config.REDIS_PORT, config.DB_PATH))
        stop = asyncio.Event()
        for sig in (signal.SIGTERM, signal.SIGINT):
            try:
                self.loop.add_signal_handler(sig, stop.set)
            except (NotImplementedError, RuntimeError):
                pass
        async with server:
            await stop.wait()
        tail.stop.set()
        for t in tasks:
            t.cancel()
        try:
            c = config.connect()
            c.execute("DELETE FROM ws_presence WHERE node_id=?", (self.node_id,))
            c.close()
        except Exception:  # noqa: BLE001
            pass


def main(argv=None):
    p = argparse.ArgumentParser(description="Huddle HTTP node")
    p.add_argument("--node-id", type=int, default=int(os.environ.get("HUDDLE_NODE_ID", "0")))
    p.add_argument("--port", type=int, default=None)
    args = p.parse_args(argv)
    port = args.port if args.port is not None else config.BASE_PORT + args.node_id
    node = Node(args.node_id, port)
    try:
        asyncio.run(node.main())
    except KeyboardInterrupt:
        pass
    os._exit(0)


if __name__ == "__main__":
    main()

