"""Messages, threads, reactions, pins, slash commands, mentions and search."""
import json
import re

from huddle.api.db import ApiError, Tx, now_iso
from huddle.api.router import route
from huddle.api.core import (body_json, as_int, users_by_ids, channel_obj, ws_role, get_channel, is_channel_member,
                             require_read, require_write, require_not_archived, get_message, message_obj,
                             messages_obj, reactions_for, channel_member_ids)

BODY_MAX = 40000
SHRUG = "¯\\_(ツ)_/¯"
MENTION_RE = re.compile(r"(?<![A-Za-z0-9_.@+-])@([A-Za-z0-9_][A-Za-z0-9_-]*)")


# ---------------------------------------------------------------- mentions

def resolve_mentions(conn, ch, author_id, body):
    """Return the ordered, deduped list of user ids mentioned in ``body``."""
    if not body or "@" not in body:
        return []
    tokens = MENTION_RE.findall(body)
    if not tokens:
        return []
    out = []
    members = None
    ws_id = ch["workspace_id"]

    def chan_members():
        nonlocal members
        if members is None:
            members = channel_member_ids(conn, ch["id"])
        return members

    def add(uid):
        if uid != author_id and uid not in out:
            out.append(uid)

    for tok in tokens:
        low = tok.lower()
        if low in ("channel", "everyone"):
            for uid in chan_members():
                add(uid)
            continue
        if low == "here":
            try:
                from huddle import events
                online = events.online_user_ids()
            except Exception:  # noqa: BLE001
                online = set()
            for uid in chan_members():
                if uid in online:
                    add(uid)
            continue
        # strip trailing hyphens/underscores that are probably punctuation
        cands = [tok]
        if "-" in tok:
            cands.append(tok.split("-")[0])
        matched = False
        if ws_id is not None:
            g = conn.execute("SELECT id FROM user_groups WHERE workspace_id=? AND handle=?",
                             (ws_id, low)).fetchone()
            if g is not None:
                cm = set(chan_members())
                for r in conn.execute("SELECT user_id FROM group_members WHERE group_id=? ORDER BY user_id",
                                      (g["id"],)):
                    if r[0] in cm:
                        add(r[0])
                continue
        for cand in cands:
            if not re.fullmatch(r"[A-Za-z0-9_]+", cand):
                continue
            u = conn.execute("SELECT id FROM users WHERE username=?", (cand,)).fetchone()
            if u is None:
                continue
            uid = u["id"]
            if ws_id is not None:
                if ws_role(conn, ws_id, uid) is None:
                    break
            else:
                if uid not in chan_members():
                    break
            add(uid)
            matched = True
            break
        _ = matched
    return out


def _store_mentions(conn, mid, cid, ids):
    conn.execute("DELETE FROM message_mentions WHERE message_id=?", (mid,))
    conn.executemany("INSERT OR IGNORE INTO message_mentions(message_id, user_id, channel_id) VALUES (?,?,?)",
                     [(mid, u, cid) for u in ids])


# ---------------------------------------------------------------- posting

def _validate_body(body, allow_empty=False):
    if body is None:
        body = ""
    if not isinstance(body, str):
        raise ApiError(400, "body must be a string")
    if not body.strip() and not allow_empty:
        raise ApiError(400, "message body cannot be empty")
    if len(body) > BODY_MAX:
        raise ApiError(400, "message body too long")
    return body


def post_message(conn, ch, uid, body, parent_id=None, file_ids=None, blocks=None):
    """Create a message (or reply) atomically with its durable event. Returns MessageObj."""
    file_ids = file_ids or []
    with Tx(conn) as tx:
        ch = get_channel(conn, ch["id"])
        require_not_archived(ch)
        parent = None
        if parent_id is not None:
            parent = conn.execute("SELECT * FROM messages WHERE id=?", (parent_id,)).fetchone()
            if parent is None or parent["deleted_at"] is not None:
                raise ApiError(404, "parent message not found")
            if parent["channel_id"] != ch["id"]:
                raise ApiError(400, "parent message is in a different channel")
            if parent["parent_id"] is not None:
                parent = conn.execute("SELECT * FROM messages WHERE id=?", (parent["parent_id"],)).fetchone()
                if parent is None:
                    raise ApiError(404, "parent message not found")
        for fid in file_ids:
            f = conn.execute("SELECT uploader_id, message_id FROM files WHERE id=?", (fid,)).fetchone()
            if f is None or f["uploader_id"] != uid or f["message_id"] is not None:
                raise ApiError(400, f"file {fid} cannot be attached")
        mentions = resolve_mentions(conn, ch, uid, body)
        cur = conn.execute(
            "INSERT INTO messages(channel_id, user_id, body, parent_id, created_at, mentions, blocks)"
            " VALUES (?,?,?,?,?,?,?)",
            (ch["id"], uid, body, parent["id"] if parent else None, now_iso(), json.dumps(mentions),
             json.dumps(blocks) if blocks is not None else None))
        mid = cur.lastrowid
        _store_mentions(conn, mid, ch["id"], mentions)
        for fid in file_ids:
            conn.execute("UPDATE files SET message_id=? WHERE id=?", (mid, fid))
        if parent is not None:
            conn.execute("UPDATE messages SET reply_count=reply_count+1 WHERE id=?", (parent["id"],))
            rc = conn.execute("SELECT reply_count FROM messages WHERE id=?", (parent["id"],)).fetchone()[0]
        row = conn.execute("SELECT * FROM messages WHERE id=?", (mid,)).fetchone()
        msg = message_obj(conn, row)
        if parent is not None:
            frame = tx.emit(ch["id"], "message.reply", {"message": msg, "parent_id": parent["id"], "reply_count": rc})
        else:
            frame = tx.emit(ch["id"], "message.new", {"message": msg})
        conn.execute("UPDATE messages SET seq=? WHERE id=?", (frame["seq"], mid))
    return msg


def _parse_file_ids(v):
    if v is None:
        return []
    if not isinstance(v, list):
        raise ApiError(400, "file_ids must be a list")
    out = []
    for x in v:
        try:
            i = as_int(x, "file_ids")
        except ApiError:
            raise ApiError(400, "file_ids must be integers")
        if i in out:
            raise ApiError(400, "duplicate file id")
        out.append(i)
    return out


def _resolve_user_arg(conn, arg):
    name = arg.strip().split()[0] if arg.strip() else ""
    name = name.lstrip("@")
    if not name:
        raise ApiError(400, "usage: /invite @user")
    u = conn.execute("SELECT id FROM users WHERE username=?", (name,)).fetchone()
    if u is None:
        raise ApiError(404, f"user {name} not found")
    return u["id"]


def _slash(conn, ch, uid, body, parent_id, file_ids, blocks):
    """Returns a (status, response) tuple, or None if body should be posted as a normal message."""
    from huddle.api import h_channels
    m = re.match(r"^/(\S+)(?:\s+(.*))?$", body.strip(), re.S)
    if not m:
        raise ApiError(400, "invalid command")
    cmd = m.group(1).lower()
    arg = (m.group(2) or "").strip()
    if cmd == "me":
        if not arg:
            raise ApiError(400, "/me requires text")
        return None
    if cmd == "shrug":
        new_body = f"{arg} {SHRUG}" if arg else SHRUG
        msg = post_message(conn, ch, uid, new_body, parent_id, file_ids, blocks)
        return 201, {"message": msg}
    if cmd == "topic":
        if ch["is_private"] or ch["is_dm"]:
            if not is_channel_member(conn, ch["id"], uid):
                raise ApiError(403, "not a member of this channel")
        require_not_archived(ch)
        h_channels._require_channel_editor(conn, ch, uid)
        chan = h_channels.set_topic(conn, ch, uid, arg)
        return 201, {"message": None, "channel": chan}
    if cmd == "invite":
        target = _resolve_user_arg(conn, arg)
        h_channels.invite_to_channel(conn, ch, uid, target)
        users = users_by_ids(conn, [target])
        return 201, {"message": None, "invited_user": users.get(target),
                     "channel": h_channels.channel_view(conn, ch["id"], uid)}
    if cmd in ("archive", "unarchive"):
        chan = h_channels.set_archived(conn, ch, uid, cmd == "archive")
        return 201, {"message": None, "channel": chan}
    raise ApiError(400, f"unknown command /{cmd}")


@route("POST", "/api/channels/{id}/messages")
def create_message(ctx):
    conn = ctx.conn
    ch = get_channel(conn, ctx.pint("id"))
    if (ch["is_private"] or ch["is_dm"]) and not is_channel_member(conn, ch["id"], ctx.uid):
        raise ApiError(403, "not a member of this channel")
    data = body_json(ctx.req)
    file_ids = _parse_file_ids(data.get("file_ids"))
    body = _validate_body(data.get("body", data.get("text")), allow_empty=bool(file_ids))
    parent_id = data.get("parent_id", data.get("thread_id"))
    parent_id = as_int(parent_id, "parent_id") if parent_id is not None else None
    blocks = data.get("blocks")
    stripped = body.lstrip()
    if stripped.startswith("/") and not stripped.startswith("//"):
        m = re.match(r"^/(\S+)", stripped)
        cmd = m.group(1).lower() if m else ""
        if cmd not in ("unarchive", "archive"):
            require_not_archived(ch)
            require_write(conn, ch, ctx.uid)
        res = _slash(conn, ch, ctx.uid, stripped, parent_id, file_ids, blocks)
        if res is not None:
            return res
    require_not_archived(ch)
    require_write(conn, ch, ctx.uid)
    msg = post_message(conn, ch, ctx.uid, body, parent_id, file_ids, blocks)
    return 201, {"message": msg}


