    q = ctx.req.query
    try:
        limit = int(q.get("limit") or 50)
    except ValueError:
        raise ApiError(400, "limit must be an integer")
    limit = max(1, min(limit, 200))
    sql = "SELECT * FROM messages WHERE channel_id=? AND parent_id IS NULL AND deleted_at IS NULL"
    args = [ch["id"]]
    if q.get("before"):
        try:
            args.append(int(q["before"]))
        except ValueError:
            raise ApiError(400, "before must be an id")
        sql += " AND id<?"
    if q.get("after"):
        try:
            args.append(int(q["after"]))
        except ValueError:
            raise ApiError(400, "after must be an id")
        sql += " AND id>?"
    sql += " ORDER BY id DESC LIMIT ?"
    args.append(limit)
    rows = conn.execute(sql, args).fetchall()
    return {"messages": messages_obj(conn, rows), "has_more": len(rows) == limit}


