def _emoji(v):
    if not isinstance(v, str) or not v.strip():
        raise ApiError(400, "emoji is required")
    v = v.strip()
    if len(v) > 64 or any(c.isspace() for c in v):
        raise ApiError(400, "invalid emoji")
