def _react(ctx, emoji, add):
    conn = ctx.conn
    m, ch = _msg_and_channel(ctx)
    if (ch["is_private"] or ch["is_dm"]) and not is_channel_member(conn, ch["id"], ctx.uid):
        raise ApiError(403, "not a member of this channel")
    require_not_archived(ch)
    require_write(conn, ch, ctx.uid)
    with Tx(conn) as tx:
        if add:
            cur = conn.execute("INSERT OR IGNORE INTO reactions(message_id, user_id, emoji, created_at) VALUES (?,?,?,?)",
                               (m["id"], ctx.uid, emoji, now_iso()))
        else:
            cur = conn.execute("DELETE FROM reactions WHERE message_id=? AND user_id=? AND emoji=?",
                               (m["id"], ctx.uid, emoji))
        reactions = reactions_for(conn, [m["id"]])[m["id"]]
        if cur.rowcount:
            tx.emit(ch["id"], "reaction.added" if add else "reaction.removed",
                    {"message_id": m["id"], "emoji": emoji, "user_id": ctx.uid, "reactions": reactions})
    return 200, {"reactions": reactions, "message_id": m["id"]}


