@route("GET", "/api/search")
def search(ctx):
    conn = ctx.conn
    q = (ctx.req.query.get("q") or "").strip()
    if not q:
        raise ApiError(400, "q is required")
    try:
        limit = max(1, min(int(ctx.req.query.get("limit") or 50), 200))
    except ValueError:
        raise ApiError(400, "limit must be an integer")
    ws_filter = ctx.req.query.get("workspace_id")
    args = [ctx.uid, ctx.uid]
    sql = ("SELECT m.* FROM messages m JOIN channels c ON c.id=m.channel_id"
           " WHERE m.deleted_at IS NULL AND ("
           "  EXISTS(SELECT 1 FROM channel_members cm WHERE cm.channel_id=c.id AND cm.user_id=?)"
           "  OR (c.is_private=0 AND c.is_dm=0 AND EXISTS(SELECT 1 FROM workspace_members wm"
           "      WHERE wm.workspace_id=c.workspace_id AND wm.user_id=?)))"
           " AND m.body LIKE ? ESCAPE '\\'")
    esc = q.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    args.append(f"%{esc}%")
    if ws_filter:
        try:
            args.append(int(ws_filter))
        except ValueError:
            raise ApiError(400, "workspace_id must be an integer")
        sql += " AND c.workspace_id=?"
    if ctx.req.query.get("channel_id"):
        try:
            args.append(int(ctx.req.query["channel_id"]))
        except ValueError:
            raise ApiError(400, "channel_id must be an integer")
        sql += " AND c.id=?"
    sql += " ORDER BY m.id DESC LIMIT ?"
    args.append(limit)
    rows = conn.execute(sql, args).fetchall()
    msgs = messages_obj(conn, rows)
    chans = {}
    results = []
    for m in msgs:
        cid = m["channel_id"]
        if cid not in chans:
            chans[cid] = channel_obj(get_channel(conn, cid))
        r = dict(m)
        r["message"] = m
        r["channel"] = chans[cid]
        r["channel_name"] = chans[cid]["name"]
        r["workspace_id"] = chans[cid]["workspace_id"]
        results.append(r)
    return {"results": results, "messages": msgs}

"""Shared helpers for cluster tests: spawn miniredis + nodes on test ports, HTTP/WS helpers, seeding.

Ports: nodes 28000-28002, redis 26379 (never the production ports). Only PIDs started here are killed.
"""
import http.client
import json
import os
import shutil
import signal
import socket
import subprocess
import sys
import tempfile
import time

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from huddle.web.wsclient import HandshakeError, WSClient  # noqa: E402,F401

BASE_PORT = 28000
REDIS_PORT = 26379
HOST = "127.0.0.1"


def port_open(port, host=HOST):
    try:
        with socket.create_connection((host, port), timeout=0.2):
            return True
    except OSError:
        return False


def wait_port(port, timeout=10.0, up=True):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if port_open(port) == up:
            return True
        time.sleep(0.05)
    return False


class Cluster:
    """Owns a temp data dir and the child processes it starts."""

    def __init__(self, nodes=3, redis=True, data_dir=None):
        self.data_dir = data_dir or tempfile.mkdtemp(prefix="huddle-cluster-")
        self.env = dict(os.environ, HUDDLE_DATA=self.data_dir, HUDDLE_BASE_PORT=str(BASE_PORT),
                        HUDDLE_REDIS_PORT=str(REDIS_PORT), HUDDLE_IRC_PORT="26667", PYTHONUNBUFFERED="1")
        self.procs = {}
        self.n_nodes = nodes
        self.want_redis = redis
        os.makedirs(os.path.join(self.data_dir, "logs"), exist_ok=True)

    # --- config for in-process db access ---
    def db_path(self):
        return os.path.join(self.data_dir, "huddle.db")

    def connect(self):
        import sqlite3
        c = sqlite3.connect(self.db_path(), timeout=30, isolation_level=None, check_same_thread=False)
        c.row_factory = sqlite3.Row
        c.execute("PRAGMA journal_mode=WAL")
        c.execute("PRAGMA busy_timeout=30000")
        return c

    def _spawn(self, name, args):
        log = open(os.path.join(self.data_dir, "logs", name + ".log"), "ab")
        p = subprocess.Popen([sys.executable] + args, cwd=ROOT, env=self.env, stdout=log, stderr=subprocess.STDOUT)
        self.procs[name] = p
        return p

    def start_redis(self):
        if port_open(REDIS_PORT):
            raise RuntimeError("port %d already in use" % REDIS_PORT)
        self._spawn("redis", ["-m", "huddle.miniredis", "--port", str(REDIS_PORT)])
        assert wait_port(REDIS_PORT), "miniredis did not start"

    def start_node(self, i):
        self._spawn("node%d" % i, ["-m", "huddle.node", "--node-id", str(i)])
        assert wait_port(BASE_PORT + i, 15), "node %d did not start; log:\n%s" % (i, self.log("node%d" % i))

    def start(self):
        for i in range(self.n_nodes):
            if port_open(BASE_PORT + i):
                raise RuntimeError("port %d already in use" % (BASE_PORT + i))
        if self.want_redis:
            self.start_redis()
        for i in range(self.n_nodes):
            self.start_node(i)
        time.sleep(0.3)  # let redis subscribers connect
        return self

    def kill(self, name, sig=signal.SIGKILL):
        p = self.procs.get(name)
        if p and p.poll() is None:
            p.send_signal(sig)
            try:
                p.wait(5)
            except subprocess.TimeoutExpired:
                p.kill()
                p.wait()

    def log(self, name):
        try:
            with open(os.path.join(self.data_dir, "logs", name + ".log"), "rb") as f:
                return f.read().decode("utf-8", "replace")[-4000:]
        except OSError:
            return ""

    def stop(self, keep=False):
        for name in list(self.procs):
            self.kill(name, signal.SIGTERM)
        for name in list(self.procs):
            self.kill(name, signal.SIGKILL)
        self.procs.clear()
        if not keep:
            shutil.rmtree(self.data_dir, ignore_errors=True)

    # --- clients ---
    def ws(self, node, token, timeout=10.0):
        return WSClient(HOST, BASE_PORT + node, "/api/ws?token=%s" % token, timeout=timeout)


def http_request(port, method, path, body=None, token=None, headers=None, timeout=10.0, raw=False):
    conn = http.client.HTTPConnection(HOST, port, timeout=timeout)
    h = dict(headers or {})
    data = None
    if body is not None:
        if isinstance(body, (bytes, bytearray)):
            data = bytes(body)
        else:
            data = json.dumps(body).encode()
            h.setdefault("Content-Type", "application/json")
    if token:
        h["Authorization"] = "Bearer " + token
    conn.request(method, path, body=data, headers=h)
    r = conn.getresponse()
    payload = r.read()
    hdrs = {k.lower(): v for k, v in r.getheaders()}
    conn.close()
    if raw:
        return r.status, hdrs, payload
    try:
        j = json.loads(payload) if payload else None
    except ValueError:
        j = None
    return r.status, j


# --- direct seeding (used when huddle.api isn't available; only pinned columns) ---
MIN_SCHEMA = """
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY, user_id INTEGER);
CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY, slug TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS workspace_members(workspace_id INTEGER, user_id INTEGER, role TEXT);
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY, workspace_id INTEGER, name TEXT,
    is_private INTEGER DEFAULT 0, is_dm INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER, user_id INTEGER);
"""


def seed_minimal(conn):
    """Create two users (tokens tok-alice-000000001 / tok-bob-00000000002), a public channel 1,
    and a private channel 2 that only alice belongs to."""
    for stmt in MIN_SCHEMA.split(";"):
        if stmt.strip():
            conn.execute(stmt)
    conn.execute("INSERT OR IGNORE INTO users(id, username) VALUES (1,'alice'),(2,'bob')")
    conn.execute("INSERT OR IGNORE INTO tokens(token, user_id) VALUES ('tok-alice-000000001',1),('tok-bob-00000000002',2)")
    conn.execute("INSERT OR IGNORE INTO workspaces(id, slug) VALUES (1,'acme')")
    conn.execute("INSERT OR IGNORE INTO channels(id, workspace_id, name, is_private, is_dm) VALUES "
                 "(1,1,'general',0,0),(2,1,'secret',1,0)")
    conn.execute("INSERT INTO channel_members(channel_id, user_id) VALUES (1,1),(1,2),(2,1)")
    return {"alice": "tok-alice-000000001", "bob": "tok-bob-00000000002"}


def append_event(conn, channel_id, kind="message.new", data=None):
    from huddle import events
    conn.execute("BEGIN IMMEDIATE")
    try:
        f = events.append(conn, channel_id, kind, data or {})
        conn.execute("COMMIT")
    except Exception:
        conn.execute("ROLLBACK")
        raise
    return f


