"""File upload/download endpoints (multipart parsing by hand)."""
import os
import re
import secrets
from urllib.parse import quote

from huddle import config
from huddle.web.http import Response
from huddle.api.db import ApiError, now_iso
from huddle.api.router import route
from huddle.api.core import file_obj, get_channel, can_read_channel


def _header_params(value):
    """Parse 'form-data; name="file"; filename="a.txt"' -> ('form-data', {...})."""
    parts = []
    cur, inq, i = "", False, 0
    while i < len(value):
        c = value[i]
        if c == '"':
            inq = not inq
            cur += c
        elif c == "\\" and inq and i + 1 < len(value):
            cur += value[i:i + 2]
            i += 1
        elif c == ";" and not inq:
            parts.append(cur)
            cur = ""
        else:
            cur += c
        i += 1
    parts.append(cur)
    main = parts[0].strip().lower()
    params = {}
    for p in parts[1:]:
        if "=" not in p:
            continue
        k, v = p.split("=", 1)
        k = k.strip().lower()
        v = v.strip()
        if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
            v = v[1:-1].replace('\\"', '"').replace("\\\\", "\\")
        if k == "filename*":
            m = re.match(r"^([^']*)'[^']*'(.*)$", v)
            if m:
                from urllib.parse import unquote
                try:
                    v = unquote(m.group(2), encoding=m.group(1) or "utf-8")
                except LookupError:
                    v = unquote(m.group(2))
        params[k] = v
    return main, params


def parse_multipart(body, content_type):
    """Return list of dicts {name, filename, content_type, data}."""
    _, params = _header_params(content_type or "")
    boundary = params.get("boundary")
    if not boundary:
        raise ApiError(400, "multipart boundary missing")
    delim = b"--" + boundary.encode("latin-1")
    parts = []
    pos = body.find(delim)
    if pos < 0:
        raise ApiError(400, "malformed multipart body")
    while True:
        pos += len(delim)
        if body[pos:pos + 2] == b"--":
            break
        if body[pos:pos + 2] == b"\r\n":
            pos += 2
        elif body[pos:pos + 1] == b"\n":
            pos += 1
        hdr_end = body.find(b"\r\n\r\n", pos)
        sep = 4
        if hdr_end < 0:
            hdr_end = body.find(b"\n\n", pos)
            sep = 2
            if hdr_end < 0:
                raise ApiError(400, "malformed multipart part")
        headers = {}
        for line in body[pos:hdr_end].decode("utf-8", "replace").splitlines():
            if ":" in line:
                k, v = line.split(":", 1)
                headers[k.strip().lower()] = v.strip()
        data_start = hdr_end + sep
        nxt = body.find(b"\r\n" + delim, data_start)
        trail = 2
        if nxt < 0:
            nxt = body.find(b"\n" + delim, data_start)
            trail = 1
            if nxt < 0:
                nxt = body.find(delim, data_start)
                trail = 0
                if nxt < 0:
                    raise ApiError(400, "malformed multipart body")
        data = body[data_start:nxt]
        _, dparams = _header_params(headers.get("content-disposition", ""))
        parts.append({"name": dparams.get("name"),
                      "filename": dparams.get("filename*") or dparams.get("filename"),
                      "content_type": headers.get("content-type"), "data": data})
        pos = nxt + trail
    return parts


@route("POST", "/api/files")
def upload_file(ctx):
    req = ctx.req
    ctype = req.headers.get("content-type", "")
    if len(req.body) > config.MAX_UPLOAD + 256 * 1024:
        raise ApiError(413, "file too large (max 10 MiB)")
    if not ctype.lower().startswith("multipart/form-data"):
        raise ApiError(400, "multipart/form-data required")
    parts = parse_multipart(req.body, ctype)
    part = None
    for p in parts:
        if p["name"] == "file":
            part = p
            break
    if part is None:
        for p in parts:
            if p["filename"] is not None:
                part = p
                break
    if part is None:
        raise ApiError(400, "file part missing")
    data = part["data"]
    if len(data) > config.MAX_UPLOAD:
        raise ApiError(413, "file too large (max 10 MiB)")
    filename = os.path.basename((part["filename"] or "upload").replace("\\", "/")) or "upload"
    filename = filename[:255]
    content_type = (part["content_type"] or "application/octet-stream").strip()
    os.makedirs(config.FILES_DIR, exist_ok=True)
    stored = secrets.token_hex(16)
    path = os.path.join(config.FILES_DIR, stored)
    with open(path, "wb") as f:
        f.write(data)
    cur = ctx.conn.execute(
        "INSERT INTO files(uploader_id, filename, content_type, size, path, created_at) VALUES (?,?,?,?,?,?)",
        (ctx.uid, filename, content_type, len(data), stored, now_iso()))
    row = ctx.conn.execute("SELECT * FROM files WHERE id=?", (cur.lastrowid,)).fetchone()
    return 201, {"file": file_obj(row)}


def _get_file(ctx):
    raw = ctx.params["id"]
    if not raw.isdigit():
        raise ApiError(404, "file not found")
    row = ctx.conn.execute("SELECT * FROM files WHERE id=?", (int(raw),)).fetchone()
    if row is None:
        raise ApiError(404, "file not found")
    if row["uploader_id"] != ctx.uid and row["message_id"] is not None:
        m = ctx.conn.execute("SELECT channel_id FROM messages WHERE id=?", (row["message_id"],)).fetchone()
        if m is not None:
            try:
                ch = get_channel(ctx.conn, m["channel_id"])
            except ApiError:
                ch = None
            if ch is not None and not can_read_channel(ctx.conn, ch, ctx.uid):
                raise ApiError(403, "not allowed to access this file")
    return row


@route("GET", "/api/files")
def list_files(ctx):
    rows = ctx.conn.execute("SELECT * FROM files WHERE uploader_id=? ORDER BY id DESC LIMIT 200",
                            (ctx.uid,)).fetchall()
    return {"files": [file_obj(r) for r in rows]}


@route("GET", "/api/files/{id}")
def get_file(ctx):
    return {"file": file_obj(_get_file(ctx))}


@route("GET", "/api/files/{id}/download")
def download_file(ctx):
    row = _get_file(ctx)
    path = os.path.join(config.FILES_DIR, row["path"])
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        raise ApiError(404, "file content missing")
    fn = row["filename"]
    ascii_fn = fn.encode("ascii", "replace").decode("ascii").replace('"', "_").replace("\\", "_")
    disp = f'attachment; filename="{ascii_fn}"'
    if ascii_fn != fn:
        disp += f"; filename*=UTF-8''{quote(fn)}"
    return Response(200, data, headers={"Content-Disposition": disp, "Content-Length": str(len(data))},
                    content_type=row["content_type"])

