"""Shared test helpers: isolated data dir + direct handle_api calls (no sockets)."""
import json
import os
import tempfile

if "HUDDLE_TEST_DATA" not in os.environ:
    os.environ["HUDDLE_TEST_DATA"] = tempfile.mkdtemp(prefix="huddle-api-test-")
os.environ["HUDDLE_DATA"] = os.environ["HUDDLE_TEST_DATA"]
os.environ.setdefault("HUDDLE_BASE_PORT", "18000")

from huddle.web.http import Request  # noqa: E402
from huddle.api.app import handle_api  # noqa: E402

_counter = [0]


def uniq(prefix="u"):
    _counter[0] += 1
    return f"{prefix}{os.getpid()}x{_counter[0]}"


class Resp:
    def __init__(self, r):
        self.status = r.status
        self.raw = r
        self.headers = r.headers
        ctype, data = r.encode()
        self.content_type = ctype
        self.data = data
        try:
            self.json = json.loads(data.decode("utf-8")) if data and ctype and "json" in ctype else None
        except ValueError:
            self.json = None

    def __repr__(self):
        return f"<Resp {self.status} {self.json if self.json is not None else self.data[:100]!r}>"


def call(method, path, body=None, token=None, query=None, headers=None, raw=None, node_id=0):
    h = dict(headers or {})
    if token:
        h["Authorization"] = f"Bearer {token}"
    if raw is not None:
        data = raw
    elif body is not None:
        data = json.dumps(body).encode()
        h.setdefault("Content-Type", "application/json")
    else:
        data = b""
    return Resp(handle_api(Request(method, path, query=query or {}, headers=h, body=data, node_id=node_id)))


def register(name=None, password="password123", **kw):
    name = name or uniq()
    body = {"username": name, "password": password}
    body.update(kw)
    r = call("POST", "/api/auth/register", body)
    assert r.status == 201, r
    return r.json["user"], r.json["token"]


def make_ws(token, slug=None, name=None):
    slug = slug or uniq("ws-").replace("x", "-")
    r = call("POST", "/api/workspaces", {"slug": slug, "name": name or slug}, token)
    assert r.status == 201, r
    return r.json["workspace"], r.json["general_channel"]


def make_channel(token, slug, name=None, **kw):
    body = {"name": name or uniq("ch-").replace("x", "-")}
    body.update(kw)
    r = call("POST", f"/api/workspaces/{slug}/channels", body, token)
    assert r.status == 201, r
    return r.json["channel"]


def post(token, cid, body, **kw):
    b = {"body": body}
    b.update(kw)
    return call("POST", f"/api/channels/{cid}/messages", b, token)


def channel_events(cid):
