/* Huddle SPA — hand-written, no frameworks, no build step. */
(function () {
  'use strict';

  // ------------------------------------------------------------------
  // Utilities
  // ------------------------------------------------------------------
  const $ = (sel, root) => (root || document).querySelector(sel);
  const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));
  const byId = (id) => document.getElementById(id);

  function el(tag, attrs, ...children) {
    const node = document.createElement(tag);
    if (attrs) {
      for (const [k, v] of Object.entries(attrs)) {
        if (v === undefined || v === null || v === false) continue;
        if (k === 'class') node.className = v;
        else if (k === 'text') node.textContent = v;
        else if (k === 'html') node.innerHTML = v;
        else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v);
        else if (k === 'dataset') Object.assign(node.dataset, v);
        else if (v === true) node.setAttribute(k, '');
        else node.setAttribute(k, String(v));
      }
    }
    for (const c of children.flat()) {
      if (c === null || c === undefined || c === false) continue;
      node.appendChild(typeof c === 'string' || typeof c === 'number' ? document.createTextNode(String(c)) : c);
    }
    return node;
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  function show(node, on) { if (node) node.hidden = !on; }

  function setError(node, msg) {
    if (!node) return;
    if (msg) { node.textContent = msg; node.hidden = false; } else { node.textContent = ''; node.hidden = true; }
  }

  let toastTimer = null;
  function toast(msg, isError) {
    const t = byId('toast');
    t.textContent = msg;
    t.classList.toggle('error', !!isError);
    t.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { t.hidden = true; }, isError ? 5000 : 3000);
  }

  const AVATAR_COLORS = ['#e8912d', '#2bac76', '#1264a3', '#cd2553', '#4a154b', '#36c5f0', '#9b59b6', '#e01e5a', '#0f7b6c', '#d2691e', '#5b6abf', '#b5651d'];
  function colorFor(key) {
    const s = String(key || '?');
    let h = 0;
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return AVATAR_COLORS[h % AVATAR_COLORS.length];
  }
  function initials(name) {
    const parts = String(name || '?').trim().split(/[\s_.-]+/).filter(Boolean);
    if (!parts.length) return '?';
    if (parts.length === 1) return parts[0].slice(0, 2);
    return (parts[0][0] + parts[1][0]);
  }
  function avatarEl(user, fallbackName, small) {
    const name = userName(user) || fallbackName || '?';
    const key = (user && (user.id || user.username)) || name;
    const a = el('div', { class: 'avatar' + (small ? ' sm' : ''), 'aria-hidden': 'true', style: `background:${colorFor(key)}` });
    if (user && user.avatar_url && /^(https?:|\/|data:)/.test(user.avatar_url)) {
      const img = el('img', { src: user.avatar_url, alt: '' });
      img.addEventListener('error', () => { img.remove(); a.textContent = initials(name); });
      a.appendChild(img);
    } else {
      a.textContent = initials(name);
    }
    return a;
  }

  function parseTime(ts) {
    if (!ts) return null;
    const d = new Date(ts);
    return isNaN(d.getTime()) ? null : d;
  }
  function fmtTime(ts) {
    const d = parseTime(ts);
    return d ? d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) : '';
  }
  function fmtFull(ts) {
    const d = parseTime(ts);
    return d ? d.toLocaleString([], { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }) : '';
  }
  function dayKey(ts) {
    const d = parseTime(ts);
    return d ? `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}` : '';
  }
  function dayLabel(ts) {
    const d = parseTime(ts);
    if (!d) return '';
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const that = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    const diff = Math.round((today - that) / 86400000);
    if (diff === 0) return 'Today';
    if (diff === 1) return 'Yesterday';
    return d.toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric' });
  }

  function errText(err) {
    if (!err) return 'Something went wrong';
    if (err.userMessage) return err.userMessage;
    return err.message || String(err);
  }

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  const TOKEN_KEY = 'huddle.token';
  const S = {
    token: null,
    me: null,
    workspaces: [],
    ws: null,                 // current workspace object
    myRole: null,
    channels: new Map(),      // id -> channel
    currentChannelId: null,
    msgs: new Map(),          // channelId -> {list: [...oldest-first], hasMore, loaded}
    users: new Map(),         // id -> user
    wsMembers: [],            // workspace members
    unread: new Map(),        // channelId -> count
    mentionCount: new Map(),
    lastSeq: new Map(),       // channelId -> highest seq observed
    dmNames: new Map(),       // channelId -> other user
    thread: null,             // {parentId, channelId, parent, replies: []}
    editing: null,            // {id, draft}
    sock: null,
    sockSubs: new Set(),
    sockRetry: 0,
    sockTimer: null,
    pingTimer: null,
    everConnected: false,
    pendingFiles: [],
    loadSeq: 0,
  };
  window.__huddle_state = S; // for debugging

  // ------------------------------------------------------------------
  // API
  // ------------------------------------------------------------------
  class ApiError extends Error {
    constructor(status, message, data) { super(message); this.status = status; this.data = data; this.userMessage = message; }
  }

  function extractError(data, status) {
    if (data) {
      if (typeof data === 'string') return data.slice(0, 300);
      const e = data.error;
      if (typeof e === 'string' && e) return data.message && data.message !== e ? `${e}: ${data.message}` : (data.detail ? `${e}: ${data.detail}` : e);
      if (e && typeof e === 'object') return e.message || e.detail || e.code || JSON.stringify(e);
      if (data.message) return data.message;
      if (data.detail) return typeof data.detail === 'string' ? data.detail : JSON.stringify(data.detail);
      if (data.errors) return JSON.stringify(data.errors);
    }
    const generic = { 400: 'Invalid input', 401: 'Not authorized', 403: 'You do not have permission to do that', 404: 'Not found', 409: 'Already exists', 413: 'File too large (max 10 MB)', 423: 'This channel is archived' };
    return generic[status] || `Request failed (${status})`;
  }

  async function api(method, path, body, opts) {
    opts = opts || {};
    const headers = {};
    if (S.token) headers['Authorization'] = 'Bearer ' + S.token;
    let payload;
    if (body instanceof FormData) payload = body;
    else if (body !== undefined) { headers['Content-Type'] = 'application/json'; payload = JSON.stringify(body); }
    let resp;
    try {
      resp = await fetch(path, { method, headers, body: payload });
    } catch (e) {
      throw new ApiError(0, 'Network error — is the server reachable?', null);
    }
    let data = null;
    const text = await resp.text();
    if (text) {
      try { data = JSON.parse(text); } catch (_) { data = text; }
    }
    if (!resp.ok) {
      if (resp.status === 401 && !opts.noAuthRedirect && S.token) {
        handleUnauthorized();
      }
      throw new ApiError(resp.status, extractError(data, resp.status), data);
    }
    return data || {};
  }

  // ------------------------------------------------------------------
  // Users
  // ------------------------------------------------------------------
  function userName(u) {
    if (!u) return '';
    if (typeof u === 'string') return u;
    return u.display_name || u.username || '';
  }
  function rememberUser(u) {
    if (!u || typeof u !== 'object' || u.id === undefined || u.id === null) return;
    const prev = S.users.get(u.id) || {};
    S.users.set(u.id, Object.assign({}, prev, u));
  }
  const userFetches = new Map();
  function fetchUser(id) {
    if (id === undefined || id === null) return Promise.resolve(null);
    if (S.users.has(id) && S.users.get(id).username) return Promise.resolve(S.users.get(id));
    if (userFetches.has(id)) return userFetches.get(id);
    const p = api('GET', `/api/users/${id}`).then((d) => { rememberUser(d.user); return d.user; }).catch(() => null);
    userFetches.set(id, p);
    return p;
  }
  function authorOf(msg) {
    if (msg.author && typeof msg.author === 'object') { rememberUser(msg.author); return S.users.get(msg.author.id) || msg.author; }
    const u = S.users.get(msg.author_id);
    if (u) return u;
    if (typeof msg.author === 'string') return { id: msg.author_id, display_name: msg.author };
    return null;
  }
  let userRefreshScheduled = false;
  function ensureAuthors(list) {
    const missing = new Set();
    for (const m of list) {
      if (!authorOf(m) && m.author_id !== undefined) missing.add(m.author_id);
    }
    if (!missing.size) return;
    Promise.all(Array.from(missing).map(fetchUser)).then(() => {
      if (userRefreshScheduled) return;
      userRefreshScheduled = true;
      setTimeout(() => { userRefreshScheduled = false; renderMessages(); renderThread(); }, 30);
    });
  }

  // ------------------------------------------------------------------
  // Token / auth
  // ------------------------------------------------------------------
  function setToken(tok) {
    S.token = tok || null;
    window.__huddle_token = S.token;
    try {
      if (tok) localStorage.setItem(TOKEN_KEY, tok);
      else localStorage.removeItem(TOKEN_KEY);
    } catch (_) { /* ignore */ }
  }

  function hydrateToken() {
    const params = new URLSearchParams(location.search);
    const qt = params.get('token');
    if (qt) {
      setToken(qt);
      params.delete('token');
      const qs = params.toString();
      history.replaceState(null, '', location.pathname + (qs ? '?' + qs : '') + location.hash);
      return qt;
    }
    let tok = null;
    try { tok = localStorage.getItem(TOKEN_KEY) || localStorage.getItem('token') || localStorage.getItem('auth_token'); } catch (_) { /* ignore */ }
    if (tok) setToken(tok);
    return tok;
  }

  let authMode = 'login';
  function setAuthMode(mode) {
    authMode = mode;
    const form = byId('auth-form');
    form.dataset.mode = mode;
    const signup = mode === 'signup';
    byId('auth-heading').textContent = signup ? 'Create your Huddle account' : 'Sign in to Huddle';
    byId('auth-subtitle').textContent = signup
      ? 'Pick a username (letters, digits, underscore) and a password of at least 8 characters.'
      : 'Welcome back! Enter your username and password.';
    byId('auth-submit').textContent = signup ? 'Create account' : 'Sign in';
    byId('auth-toggle-prompt').textContent = signup ? 'Already have an account?' : 'New to Huddle?';
    byId('auth-toggle').textContent = signup ? 'Sign in instead' : 'Create an account';
    byId('auth-display-name-field').hidden = !signup;
    byId('auth-display-name').disabled = !signup;
    byId('auth-password').setAttribute('autocomplete', signup ? 'new-password' : 'current-password');
    setError(byId('auth-error'), '');
  }

  function showAuth() {
    document.body.classList.remove('booting');
    byId('app').hidden = true;
    byId('auth-modal').hidden = false;
    closeAllModals();
    setTimeout(() => { const u = byId('auth-username'); if (u) u.focus(); }, 0);
  }

  async function onAuthSubmit(ev) {
    ev.preventDefault();
    const form = byId('auth-form');
    const errBox = byId('auth-error');
    const username = form.elements.username.value.trim();
    const password = form.elements.password.value;
    const displayName = form.elements.display_name.value.trim();
    setError(errBox, '');
    if (!username) return setError(errBox, 'Please enter a username.');
    if (authMode === 'signup') {
      if (/\s/.test(username)) return setError(errBox, 'Username cannot contain spaces. Use letters, digits or underscores.');
      if (!/^[A-Za-z0-9_]+$/.test(username)) return setError(errBox, 'Username may only contain letters, digits and underscores.');
      if (username.length > 32) return setError(errBox, 'Username must be at most 32 characters.');
      if (password.length < 8) return setError(errBox, 'Password must be at least 8 characters long.');
    } else if (!password) {
      return setError(errBox, 'Please enter your password.');
    }
    const btn = byId('auth-submit');
    btn.disabled = true;
    try {
      let data;
      if (authMode === 'signup') {
        const body = { username, password };
        if (displayName) body.display_name = displayName;
        data = await api('POST', '/api/auth/register', body, { noAuthRedirect: true });
      } else {
        data = await api('POST', '/api/auth/login', { username, password }, { noAuthRedirect: true });
      }
      if (!data.token) throw new ApiError(500, 'Server did not return a token');
      setToken(data.token);
      form.reset();
      await afterLogin(data.user);
    } catch (e) {
      let msg = errText(e);
      if (authMode === 'signup') {
        if (e.status === 409) msg = `That username is already taken (${msg}).`;
        else if (e.status === 400) msg = `Could not create account: ${msg}`;
      } else if (e.status === 401) {
        msg = 'Incorrect username or password.';
      }
      setError(errBox, msg);
    } finally {
      btn.disabled = false;
    }
  }

  function handleUnauthorized() {
    if (!S.token) return;
    teardownSession();
    showAuth();
    setError(byId('auth-error'), 'Your session has expired. Please sign in again.');
  }

  function teardownSession() {
    setToken(null);
    if (S.sock) { const s = S.sock; S.sock = null; try { s.close(); } catch (_) { /* ignore */ } }
    clearTimeout(S.sockTimer);
    clearInterval(S.pingTimer);
    S.me = null; S.ws = null; S.workspaces = []; S.channels = new Map(); S.currentChannelId = null;
    S.msgs = new Map(); S.thread = null; S.editing = null; S.unread = new Map(); S.mentionCount = new Map();
    S.lastSeq = new Map(); S.sockSubs = new Set(); S.wsMembers = []; S.dmNames = new Map(); S.myRole = null;
    S.everConnected = false;
    closeEmojiPicker();
    byId('message-list').innerHTML = '';
    byId('channel-list').innerHTML = '';
    byId('dms-list').innerHTML = '';
    byId('thread-panel').hidden = true;
    byId('search-panel').hidden = true;
  }

  function logout() {
    teardownSession();
    setAuthMode('login');
    showAuth();
  }

  async function afterLogin(user) {
    if (!user) {
      const d = await api('GET', '/api/auth/me');
      user = d.user;
    }
    S.me = user;
    rememberUser(user);
    byId('auth-modal').hidden = true;
    byId('app').hidden = false;
    document.body.classList.remove('booting');
    renderCurrentUser();
    connectSocket();
    await loadWorkspaces();
  }

  function renderCurrentUser() {
    const box = byId('current-user');
    box.innerHTML = '';
    if (!S.me) return;
    box.appendChild(avatarEl(S.me, null, true));
    box.appendChild(el('div', { class: 'cu-text' },
      el('span', { class: 'cu-name', text: userName(S.me) }),
      el('span', { class: 'cu-handle', text: '@' + (S.me.username || '') })));
    box.title = `Signed in as ${userName(S.me)} (@${S.me.username})`;
  }

  // ------------------------------------------------------------------
  // Workspaces
  // ------------------------------------------------------------------
  function lastWsKey() { return `huddle.lastWorkspace.${S.me ? S.me.id : ''}`; }
  function lastChKey(slug) { return `huddle.lastChannel.${S.me ? S.me.id : ''}.${slug}`; }
  function lsGet(k) { try { return localStorage.getItem(k); } catch (_) { return null; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (_) { /* ignore */ } }

  async function loadWorkspaces(preferSlug) {
    let data;
    try { data = await api('GET', '/api/workspaces'); } catch (e) { toast(errText(e), true); return; }
    S.workspaces = data.workspaces || [];
    renderRail();
    if (!S.workspaces.length) {
      S.ws = null;
      renderNoWorkspace();
      showEmptyState(true, false);
      return;
    }
    const want = preferSlug || lsGet(lastWsKey());
    const ws = S.workspaces.find((w) => w.slug === want) || S.workspaces[0];
    await loadWorkspace(ws.slug);
  }

  function renderNoWorkspace() {
    byId('workspace-name').textContent = 'No workspace';
    byId('workspace-slug').textContent = '';
    byId('channel-list').innerHTML = '';
    byId('dms-list').innerHTML = '';
    byId('channel-list').appendChild(el('li', { class: 'sidebar-empty', text: 'Create or join a workspace to see channels.' }));
  }

  function renderRail() {
    const list = byId('workspace-rail-list');
    list.innerHTML = '';
    for (const w of S.workspaces) {
      const active = S.ws && S.ws.slug === w.slug;
      list.appendChild(el('li', null, el('button', {
        type: 'button', class: 'ws-rail-btn' + (active ? ' active' : ''), title: w.name, 'aria-label': `Switch to workspace ${w.name}`,
        'data-testid': 'workspace-switch', 'data-workspace-slug': w.slug, style: `background:${colorFor(w.slug)}`,
        onclick: () => { showEmptyState(false); if (!S.ws || S.ws.slug !== w.slug) loadWorkspace(w.slug); },
      }, initials(w.name))));
    }
  }

  function showEmptyState(on, allowBack) {
    byId('empty-state').hidden = !on;
    byId('empty-state-back').hidden = !(on && allowBack && S.ws);
    if (on) {
      setError(byId('workspace-create-error'), '');
      clearJoinError();
    }
  }

  async function loadWorkspace(slug, preferChannelId) {
    const token = ++S.loadSeq;
    let data;
    try {
      data = await api('GET', `/api/workspaces/${encodeURIComponent(slug)}?include_archived=1`);
    } catch (e) {
      toast(errText(e), true);
      return;
    }
    if (token !== S.loadSeq) return;
    S.ws = data.workspace;
    const idx = S.workspaces.findIndex((w) => w.slug === S.ws.slug);
    if (idx >= 0) S.workspaces[idx] = Object.assign({}, S.workspaces[idx], S.ws); else S.workspaces.push(S.ws);
    lsSet(lastWsKey(), S.ws.slug);
    S.channels = new Map();
    for (const c of data.channels || []) S.channels.set(c.id, c);
    applyReadState(data.read_state);
    showEmptyState(false);
    byId('workspace-name').textContent = S.ws.name || S.ws.slug;
    byId('workspace-slug').textContent = S.ws.slug;
    document.title = `${S.ws.name || S.ws.slug} — Huddle`;
    renderRail();
    renderSidebar();
    resolveDmNames();
    subscribeAll();
    loadWsMembers();
    // pick channel
    let target = preferChannelId && S.channels.get(preferChannelId);
    if (!target) {
      const last = Number(lsGet(lastChKey(S.ws.slug)));
      target = S.channels.get(last);
    }
    if (!target) target = Array.from(S.channels.values()).find((c) => c.name === 'general' && !c.is_dm);
    if (!target) target = Array.from(S.channels.values()).find((c) => !c.is_dm && !c.is_archived);
    if (!target) target = Array.from(S.channels.values())[0];
    if (target) openChannel(target.id);
    else {
      S.currentChannelId = null;
      renderHeader();
      renderMessages();
    }
  }

  async function refreshChannels() {
    if (!S.ws) return;
    try {
      const data = await api('GET', `/api/workspaces/${encodeURIComponent(S.ws.slug)}?include_archived=1`);
      for (const c of data.channels || []) S.channels.set(c.id, Object.assign({}, S.channels.get(c.id) || {}, c));
      if (data.workspace) S.ws = data.workspace;
      renderSidebar();
      resolveDmNames();
      subscribeAll();
    } catch (_) { /* ignore */ }
  }

  async function loadWsMembers() {
    if (!S.ws) return [];
    try {
      const d = await api('GET', `/api/workspaces/${encodeURIComponent(S.ws.slug)}/members`);
      S.wsMembers = d.members || [];
      for (const m of S.wsMembers) {
        if (m.user) rememberUser(m.user);
        else if (m.username) rememberUser(Object.assign({ id: m.user_id }, m, { id: m.user_id }));
      }
      const mine = S.wsMembers.find((m) => m.user_id === (S.me && S.me.id));
      S.myRole = mine ? mine.role : (S.ws && S.me && S.ws.owner_id === S.me.id ? 'owner' : null);
    } catch (_) { S.wsMembers = []; }
    return S.wsMembers;
  }

  function isWsOwner() { return !!(S.ws && S.me && (S.ws.owner_id === S.me.id || S.myRole === 'owner')); }
  function isWsAdmin() { return isWsOwner() || S.myRole === 'admin'; }

  function applyReadState(rs) {
    if (!rs) return;
    let arr;
    if (Array.isArray(rs)) arr = rs;
    else if (typeof rs === 'object' && rs.channel_id !== undefined) arr = [rs];
    else if (typeof rs === 'object') arr = Object.entries(rs).map(([k, v]) => Object.assign({ channel_id: Number(k) }, typeof v === 'object' ? v : { unread_count: v }));
    else return;
    for (const r of arr) {
      const cid = Number(r.channel_id);
      if (!cid) continue;
      S.unread.set(cid, Number(r.unread_count) || 0);
      S.mentionCount.set(cid, Number(r.mention_count) || 0);
    }
  }

  // ------------------------------------------------------------------
  // Sidebar
  // ------------------------------------------------------------------
  function channelLabel(ch) {
    if (!ch) return '';
    if (ch.is_dm) {
      const u = S.dmNames.get(ch.id);
      return u ? userName(u) : (ch.display_name || ch.name || 'Direct message');
    }
    return ch.name;
  }
  function channelTitle(ch) {
    if (!ch) return '';
    return ch.is_dm ? channelLabel(ch) : '#' + ch.name;
  }

  function renderSidebar() {
    const list = byId('channel-list');
    const dms = byId('dms-list');
    list.innerHTML = '';
    dms.innerHTML = '';
    const chans = Array.from(S.channels.values());
    const normal = chans.filter((c) => !c.is_dm).sort((a, b) => (a.is_archived - b.is_archived) || a.name.localeCompare(b.name));
    const directs = chans.filter((c) => c.is_dm).sort((a, b) => channelLabel(a).localeCompare(channelLabel(b)));
    for (const c of normal) list.appendChild(channelItem(c, false));
    for (const c of directs) dms.appendChild(channelItem(c, true));
    if (!normal.length) list.appendChild(el('li', { class: 'sidebar-empty', text: 'No channels yet' }));
    if (!directs.length) dms.appendChild(el('li', { class: 'sidebar-empty', text: 'No direct messages yet' }));
  }

  function channelItem(c, isDm) {
    const unread = S.unread.get(c.id) || 0;
    const mentions = S.mentionCount.get(c.id) || 0;
    const active = c.id === S.currentChannelId;
    const classes = ['channel-entry'];
    if (active) classes.push('active');
    if (unread && !active) classes.push('unread');
    if (c.is_archived) classes.push('archived');
    let prefix;
    if (isDm) {
      const u = S.dmNames.get(c.id);
      prefix = avatarEl(u, channelLabel(c), true);
      prefix.classList.add('ch-avatar');
    } else {
      prefix = el('span', { class: 'ch-hash', 'aria-hidden': 'true', text: c.is_private ? '\u{1F512}' : '#' });
    }
    const label = channelLabel(c);
    const btn = el('button', {
      type: 'button', class: classes.join(' '),
      'data-testid': isDm ? 'dm-entry' : 'channel-entry',
      'data-channel-id': c.id, 'data-channel-name': isDm ? (c.name || label) : c.name,
      'aria-current': active ? 'page' : null,
      title: isDm ? `Direct message with ${label}` : `#${c.name}${c.is_private ? ' (private)' : ''}${c.is_archived ? ' (archived)' : ''}`,
      onclick: () => openChannel(c.id),
    }, prefix, el('span', { class: 'ch-name', text: isDm ? label : (c.is_private ? c.name : c.name) }));
    if (!isDm && !c.is_private) {
      // render as "# name" — the hash is part of the visible text
      prefix.textContent = '#';
    }
    if (unread && !active) btn.appendChild(el('span', { class: 'badge', 'data-testid': 'unread-badge', 'aria-label': `${unread} unread`, text: String(mentions || unread) }));
    return el('li', null, btn);
  }

  async function resolveDmNames() {
    const tasks = [];
    for (const c of S.channels.values()) {
      if (!c.is_dm || S.dmNames.has(c.id)) continue;
      // channel object might carry the other user directly
      const other = c.other_user || c.dm_user || c.user || null;
      if (other && typeof other === 'object') { S.dmNames.set(c.id, other); rememberUser(other); continue; }
      tasks.push(api('GET', `/api/channels/${c.id}/members`).then((d) => {
        const members = d.members || [];
        members.forEach(rememberUser);
        const o = members.find((m) => S.me && (m.id !== S.me.id && m.user_id !== S.me.id)) || members[0];
        if (o) S.dmNames.set(c.id, o.user || o);
      }).catch(() => {}));
    }
    if (tasks.length) {
      await Promise.all(tasks);
      renderSidebar();
      renderHeader();
    }
  }

  // ------------------------------------------------------------------
  // Channel view
  // ------------------------------------------------------------------
  function currentChannel() { return S.channels.get(S.currentChannelId) || null; }

  function renderHeader() {
    const ch = currentChannel();
    const title = byId('channel-title');
    const topic = byId('channel-topic');
    if (!ch) {
      title.textContent = S.ws ? 'No channel selected' : '';
      topic.textContent = '';
      byId('archived-banner').hidden = true;
      setComposerEnabled(false, 'Select a channel');
      return;
    }
    title.textContent = channelTitle(ch) + (ch.is_private && !ch.is_dm ? ' \u{1F512}' : '');
    title.setAttribute('data-channel-id', ch.id);
    if (ch.topic) { topic.textContent = ch.topic; topic.classList.remove('empty'); }
    else { topic.textContent = ch.is_dm ? 'Direct message' : 'No topic set — add one in channel details'; topic.classList.add('empty'); }
    byId('archived-banner').hidden = !ch.is_archived;
    if (ch.is_archived) setComposerEnabled(false, 'This channel is archived');
    else setComposerEnabled(true, `Message ${channelTitle(ch)}`);
  }

  function setComposerEnabled(on, placeholder) {
    const input = byId('message-input');
    input.disabled = !on;
    input.placeholder = placeholder || '';
    byId('send-btn').disabled = !on;
    byId('composer-form').classList.toggle('disabled', !on);
  }

  async function openChannel(id, opts) {
    opts = opts || {};
    const ch = S.channels.get(id);
    if (!ch) return;
    const switching = S.currentChannelId !== id;
    S.currentChannelId = id;
    if (S.ws) lsSet(lastChKey(S.ws.slug), String(id));
    S.unread.set(id, 0);
    S.mentionCount.set(id, 0);
    if (switching) {
      S.editing = null;
      setError(byId('composer-error'), '');
      if (S.thread && S.thread.channelId !== id) closeThread();
      byId('message-input').value = '';
      S.pendingFiles = [];
      renderPendingFiles();
      autoGrow(byId('message-input'));
    }
    renderSidebar();
    renderHeader();
    renderMessages(true);
    subscribeChannel(id);
    await loadMessages(id);
    if (!opts.noFocus) { const inp = byId('message-input'); if (!inp.disabled) inp.focus(); }
  }

  function chanState(id) {
    let st = S.msgs.get(id);
    if (!st) { st = { list: [], hasMore: false, loaded: false }; S.msgs.set(id, st); }
    return st;
  }

  function sortMsgs(list) {
    list.sort((a, b) => {
      const ta = parseTime(a.created_at), tb = parseTime(b.created_at);
      const d = (ta ? ta.getTime() : 0) - (tb ? tb.getTime() : 0);
      if (d) return d;
      return (Number(a.id) || 0) - (Number(b.id) || 0);
    });
  }

  async function loadMessages(id, triedJoin) {
    let data;
    try {
      data = await api('GET', `/api/channels/${id}/messages?limit=50`);
    } catch (e) {
      if (e.status === 403 && !triedJoin) {
        try { await api('POST', `/api/channels/${id}/join`); return loadMessages(id, true); } catch (_) { /* fall through */ }
      }
      if (id === S.currentChannelId) setError(byId('composer-error'), `Could not load messages: ${errText(e)}`);
      return;
    }
    const st = chanState(id);
    const fetched = (data.messages || []).filter((m) => !m.parent_id && !m.deleted && !m.is_deleted);
    const maxFetched = fetched.reduce((mx, m) => Math.max(mx, Number(m.id) || 0), 0);
    const newerLive = st.list.filter((m) => (Number(m.id) || 0) > maxFetched && !fetched.some((f) => f.id === m.id));
    st.list = fetched.concat(newerLive);
    sortMsgs(st.list);
    st.hasMore = (data.messages || []).length >= 50;
    st.loaded = true;
    st.list.forEach((m) => authorOf(m));
    ensureAuthors(st.list);
    if (id === S.currentChannelId) {
      renderMessages(true);
      markRead(id);
    }
  }

  async function loadOlder() {
    const id = S.currentChannelId;
    const st = chanState(id);
    if (!st.list.length) return;
    const oldest = st.list[0];
    const scroller = byId('message-scroll');
    const prevHeight = scroller.scrollHeight;
    try {
      const data = await api('GET', `/api/channels/${id}/messages?limit=50&before=${encodeURIComponent(oldest.id)}`);
      const older = (data.messages || []).filter((m) => !m.parent_id && !st.list.some((x) => x.id === m.id));
      st.list = older.concat(st.list);
      sortMsgs(st.list);
      st.hasMore = (data.messages || []).length >= 50;
      ensureAuthors(older);
      renderMessages(false);
      scroller.scrollTop = scroller.scrollHeight - prevHeight;
    } catch (e) { toast(errText(e), true); }
  }

  function markRead(id) {
    const seq = S.lastSeq.get(id);
    if (seq === undefined) return;
    api('POST', `/api/channels/${id}/read`, { last_read_seq: seq }).catch(() => {});
  }

  function isNearBottom(scroller) {
    return scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 120;
  }

  function renderMessages(forceBottom) {
    const list = byId('message-list');
    const scroller = byId('message-scroll');
    const intro = byId('channel-intro');
    const ch = currentChannel();
    const wasNearBottom = isNearBottom(scroller);
    const prevTop = scroller.scrollTop;
    const focusedEdit = document.activeElement && document.activeElement.closest && document.activeElement.closest('#message-list .edit-form');
    list.innerHTML = '';
    if (!ch) {
      intro.hidden = false;
      intro.innerHTML = '';
      intro.appendChild(el('h2', { text: S.ws ? 'No channel selected' : 'Welcome to Huddle' }));
      intro.appendChild(el('p', { text: S.ws ? 'Pick a channel from the sidebar, or create a new one.' : 'Create or join a workspace to get started.' }));
      byId('load-older').hidden = true;
      return;
    }
    const st = chanState(ch.id);
    if (!st.list.length) {
      intro.hidden = false;
      intro.innerHTML = '';
      if (!st.loaded) {
        intro.appendChild(el('p', { class: 'muted', text: 'Loading messages…' }));
      } else if (ch.is_dm) {
        intro.appendChild(el('h2', { text: channelLabel(ch) }));
        intro.appendChild(el('p', { text: `This is the very beginning of your direct message history with ${channelLabel(ch)}. No messages yet — say hello!` }));
      } else {
        intro.appendChild(el('h2', { text: `#${ch.name}` }));
        intro.appendChild(el('p', { text: `This is the very beginning of #${ch.name}. No messages yet — say hello!` }));
      }
    } else {
      intro.hidden = true;
    }
    byId('load-older').hidden = !st.hasMore;
    let lastDay = '';
    for (const m of st.list) {
      const dk = dayKey(m.created_at);
      if (dk && dk !== lastDay) {
        list.appendChild(el('li', { class: 'day-divider', role: 'separator', text: dayLabel(m.created_at) }));
        lastDay = dk;
      }
      list.appendChild(buildMessage(m, false));
    }
    if (focusedEdit) focusEditBox(list);
    if (forceBottom || wasNearBottom) scroller.scrollTop = scroller.scrollHeight;
    else scroller.scrollTop = prevTop;
  }

  function focusEditBox(root) {
    const ta = $('.edit-form textarea', root);
    if (ta) { ta.focus(); const n = ta.value.length; ta.setSelectionRange(n, n); }
  }

  // ------------------------------------------------------------------
  // Message rendering
  // ------------------------------------------------------------------
  function renderBody(text) {
    let html = escapeHtml(text || '');
    // inline code
    html = html.replace(/`([^`\n]+)`/g, '<code>$1</code>');
    // links
    html = html.replace(/(^|[\s(])(https?:\/\/[^\s<]+)/g, (m, pre, url) => `${pre}<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`);
    // mentions
    const meName = S.me ? S.me.username : null;
    html = html.replace(/(^|[^A-Za-z0-9_@.])@([A-Za-z0-9_][A-Za-z0-9_.-]*)/g, (m, pre, name) => {
      const cls = (meName && name.toLowerCase() === meName.toLowerCase()) || name === 'channel' || name === 'here' ? 'mention me' : 'mention';
      return `${pre}<span class="${cls}">@${name}</span>`;
    });
    return html;
  }

  function buildMessage(m, inThread, isThreadParent) {
    const author = authorOf(m);
    const authorName = userName(author) || (m.author_id !== undefined ? `user ${m.author_id}` : 'unknown');
    const mine = S.me && m.author_id === S.me.id;
    const li = el('li', {
      class: 'message', 'data-testid': 'message', 'data-message-id': m.id, 'data-author-id': m.author_id,
      tabindex: '-1', 'aria-label': `Message from ${authorName}`,
    });
    li.appendChild(avatarEl(author, authorName));
    const main = el('div', { class: 'msg-main' });
    li.appendChild(main);
    const head = el('div', { class: 'msg-head' },
      el('span', { class: 'msg-author', 'data-testid': 'message-author', text: authorName }),
      el('time', { class: 'msg-time', 'data-testid': 'message-time', datetime: m.created_at || '', title: fmtFull(m.created_at), text: fmtTime(m.created_at) }));
    main.appendChild(head);

    const editing = S.editing && S.editing.id === m.id && !isThreadParent;
    if (editing) {
      main.appendChild(buildEditForm(m));
    } else {
      const textWrap = el('div', { class: 'msg-text' });
      const body = String(m.body || '');
      const bodyEl = el('div', { class: 'message-body', 'data-testid': 'message-body' });
      if (body.startsWith('/me ')) {
        bodyEl.classList.add('me-action');
        bodyEl.innerHTML = renderBody(body);
        bodyEl.title = `${authorName} ${body.slice(4)}`;
      } else {
        bodyEl.innerHTML = renderBody(body);
      }
      textWrap.appendChild(bodyEl);
      if (m.edited_at) textWrap.appendChild(el('span', { class: 'edited', 'data-testid': 'edited-indicator', title: `Edited ${fmtFull(m.edited_at)}`, text: '(edited)' }));
      main.appendChild(textWrap);
    }

    if (Array.isArray(m.files) && m.files.length) {
      const files = el('div', { class: 'msg-files' });
      for (const f of m.files) {
        if (!f) continue;
        files.appendChild(el('a', {
          class: 'msg-file', 'data-testid': 'message-file', href: `/api/files/${f.id}/download`,
          onclick: (ev) => { ev.preventDefault(); downloadFile(f); },
        }, `\u{1F4C4} ${f.filename || 'file'}`, f.size ? el('span', { class: 'muted', text: ` (${fmtSize(f.size)})` }) : null));
      }
      main.appendChild(files);
    }

    const reactions = (m.reactions || []).filter((r) => r && r.count > 0);
    if (reactions.length) {
      const box = el('div', { class: 'reactions', 'data-testid': 'reactions' });
      for (const r of reactions) {
        const reacted = S.me && Array.isArray(r.user_ids) && r.user_ids.includes(S.me.id);
        box.appendChild(el('button', {
          type: 'button', class: 'reaction-chip' + (reacted ? ' mine' : ''), 'data-testid': 'reaction-chip', 'data-emoji': r.emoji,
          'aria-pressed': reacted ? 'true' : 'false',
          'aria-label': `${r.emoji} ${r.count} reaction${r.count === 1 ? '' : 's'} — click to ${reacted ? 'remove' : 'add'} yours`,
          title: reactionTitle(r),
          onclick: () => toggleReaction(m, r.emoji),
        }, el('span', { class: 'emoji', text: r.emoji }), el('span', { class: 'count', 'data-testid': 'reaction-count', text: String(r.count) })));
      }
      box.appendChild(el('button', {
        type: 'button', class: 'reaction-chip add-reaction', 'aria-label': 'Add reaction', title: 'Add reaction',
        onclick: (ev) => openEmojiPicker(ev.currentTarget, (emoji) => addReaction(m, emoji)),
      }, '+\u{1F642}'));
      main.appendChild(box);
    }

    const rc = Number(m.reply_count) || 0;
    if (!inThread && rc > 0) {
      main.appendChild(el('button', {
        type: 'button', class: 'reply-link', 'data-testid': 'reply-count', 'aria-label': `${rc} ${rc === 1 ? 'reply' : 'replies'} — open thread`,
        onclick: () => openThread(m.id),
      }, el('span', { 'aria-hidden': 'true', text: '\u{1F4AC}' }), `${rc} ${rc === 1 ? 'reply' : 'replies'}`));
    }

    if (!editing) {
      const actions = el('div', { class: 'msg-actions', role: 'toolbar', 'aria-label': 'Message actions', 'data-testid': 'message-actions' });
      actions.appendChild(el('button', {
        type: 'button', 'data-testid': 'reaction-button', 'aria-label': 'Add reaction', title: 'Add reaction',
        onclick: (ev) => openEmojiPicker(ev.currentTarget, (emoji) => addReaction(m, emoji)),
      }, '\u{1F642}'));
      if (!inThread) {
        actions.appendChild(el('button', {
          type: 'button', 'data-testid': 'open-thread-btn', 'aria-label': 'Reply in thread', title: 'Reply in thread',
          onclick: () => openThread(m.id),
        }, '\u{1F4AC}'));
      }
      if (mine) {
        actions.appendChild(el('button', {
          type: 'button', 'data-testid': 'edit-message-btn', 'aria-label': 'Edit message', title: 'Edit message',
          onclick: () => startEdit(m),
        }, '✏️'));
      }
      if (mine || isWsOwner()) {
        actions.appendChild(el('button', {
          type: 'button', 'data-testid': 'delete-message-btn', 'aria-label': 'Delete message', title: 'Delete message',
          onclick: () => confirmDelete(m),
        }, '\u{1F5D1}️'));
      }
      li.appendChild(actions);
    }
    return li;
  }

  function reactionTitle(r) {
    const names = (r.user_ids || []).map((id) => (S.me && id === S.me.id ? 'You' : userName(S.users.get(id)) || `user ${id}`));
    return names.length ? `${names.join(', ')} reacted with ${r.emoji}` : r.emoji;
  }

  function fmtSize(n) {
    if (n < 1024) return `${n} B`;
    if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
    return `${(n / 1048576).toFixed(1)} MB`;
  }

  async function downloadFile(f) {
    try {
      const resp = await fetch(`/api/files/${f.id}/download`, { headers: { Authorization: 'Bearer ' + S.token } });
      if (!resp.ok) throw new Error(`Download failed (${resp.status})`);
      const blob = await resp.blob();
      const url = URL.createObjectURL(blob);
      const a = el('a', { href: url, download: f.filename || 'file' });
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) { toast(errText(e), true); }
  }

  // ------------------------------------------------------------------
  // Message store helpers
  // ------------------------------------------------------------------
  function findMessage(id) {
    for (const st of S.msgs.values()) {
      const m = st.list.find((x) => x.id === id);
      if (m) return m;
    }
    if (S.thread) {
      if (S.thread.parent && S.thread.parent.id === id) return S.thread.parent;
      const r = S.thread.replies.find((x) => x.id === id);
      if (r) return r;
    }
    return null;
  }

  function updateMessageEverywhere(id, patch) {
    let found = false;
    for (const st of S.msgs.values()) {
      const m = st.list.find((x) => x.id === id);
      if (m) { Object.assign(m, patch); found = true; }
    }
    if (S.thread) {
      if (S.thread.parent && S.thread.parent.id === id) { if (S.thread.parent !== findInLists(id)) Object.assign(S.thread.parent, patch); found = true; }
      const r = S.thread.replies.find((x) => x.id === id);
      if (r) { Object.assign(r, patch); found = true; }
    }
    return found;
  }
  function findInLists(id) {
    for (const st of S.msgs.values()) { const m = st.list.find((x) => x.id === id); if (m) return m; }
    return null;
  }

  function upsertTopLevel(msg) {
    if (!msg || msg.parent_id) return false;
    rememberUser(msg.author);
    const st = chanState(msg.channel_id);
    const existing = st.list.find((x) => x.id === msg.id);
    if (existing) {
      // keep the larger reply_count (reply events may race)
      const rc = Math.max(Number(existing.reply_count) || 0, Number(msg.reply_count) || 0);
      Object.assign(existing, msg, { reply_count: rc });
      return false;
    }
    st.list.push(msg);
    sortMsgs(st.list);
    return true;
  }

  function removeMessageEverywhere(id) {
    for (const st of S.msgs.values()) {
      const i = st.list.findIndex((x) => x.id === id);
      if (i >= 0) st.list.splice(i, 1);
    }
    if (S.editing && S.editing.id === id) S.editing = null;
    if (S.thread) {
      const i = S.thread.replies.findIndex((x) => x.id === id);
      if (i >= 0) {
        S.thread.replies.splice(i, 1);
        const p = findInLists(S.thread.parentId) || S.thread.parent;
        if (p) p.reply_count = Math.max(0, (Number(p.reply_count) || 0) - 1);
      }
      if (S.thread.parentId === id) {
        closeThread();
        toast('The thread\'s parent message was deleted');
      }
    }
  }

  // ------------------------------------------------------------------
  // Composer
  // ------------------------------------------------------------------
  function autoGrow(ta) {
    ta.style.height = 'auto';
    ta.style.height = Math.min(200, ta.scrollHeight) + 'px';
  }

  async function sendMessage(channelId, body, parentId, fileIds, errBox, triedJoin) {
    const payload = { body };
    if (parentId) payload.parent_id = parentId;
    if (fileIds && fileIds.length) payload.file_ids = fileIds;
    try {
      return await api('POST', `/api/channels/${channelId}/messages`, payload);
    } catch (e) {
      if (e.status === 403 && !triedJoin) {
        const ch = S.channels.get(channelId);
        if (ch && !ch.is_private && !ch.is_dm) {
          try {
            await api('POST', `/api/channels/${channelId}/join`);
            return await sendMessage(channelId, body, parentId, fileIds, errBox, true);
          } catch (_) { /* fall through */ }
        }
      }
      throw e;
    }
  }

  async function onComposerSubmit(ev) {
    if (ev) ev.preventDefault();
    const input = byId('message-input');
    const errBox = byId('composer-error');
    const ch = currentChannel();
    if (!ch) return;
    const body = input.value;
    const files = S.pendingFiles.slice();
    if (!body.trim() && !files.length) {
      setError(errBox, 'Message cannot be empty — type something before sending.');
      input.focus();
      return;
    }
    if (ch.is_archived) { setError(errBox, 'This channel is archived — messages cannot be posted.'); return; }
    setError(errBox, '');
    const sendBtn = byId('send-btn');
    sendBtn.disabled = true;
    try {
      const data = await sendMessage(ch.id, body.trim() ? body : (files.map((f) => f.filename).join(', ')), null, files.map((f) => f.id), errBox);
      input.value = '';
      S.pendingFiles = [];
      renderPendingFiles();
      autoGrow(input);
      if (data.message) {
        if (upsertTopLevel(data.message)) renderMessages(true);
        else renderMessages(true);
      }
      if (data.channel) {
        S.channels.set(data.channel.id, Object.assign({}, S.channels.get(data.channel.id) || {}, data.channel));
        renderSidebar();
        renderHeader();
        if (!data.message) toast('Channel updated');
      }
      if (data.invited_user) toast(`Added @${data.invited_user.username || userName(data.invited_user)} to ${channelTitle(ch)}`);
    } catch (e) {
      setError(errBox, e.status === 423 ? 'This channel is archived — messages cannot be posted.' : errText(e));
    } finally {
      sendBtn.disabled = !!(currentChannel() && currentChannel().is_archived);
      input.focus();
    }
  }

  function renderPendingFiles() {
    const box = byId('composer-files');
    box.innerHTML = '';
    for (const f of S.pendingFiles) {
      box.appendChild(el('span', { class: 'pending-file' }, `\u{1F4CE} ${f.filename}`,
        el('button', { type: 'button', class: 'link-btn', 'aria-label': `Remove ${f.filename}`, onclick: () => { S.pendingFiles = S.pendingFiles.filter((x) => x !== f); renderPendingFiles(); } }, ' ×')));
    }
  }

  async function onFileChosen(ev) {
    const input = ev.target;
    const file = input.files && input.files[0];
    input.value = '';
    if (!file) return;
    if (file.size > 10 * 1024 * 1024) { setError(byId('composer-error'), 'File is too large (max 10 MB).'); return; }
    const fd = new FormData();
    fd.append('file', file, file.name);
    try {
      const d = await api('POST', '/api/files', fd);
      if (d.file) { S.pendingFiles.push(d.file); renderPendingFiles(); }
    } catch (e) { setError(byId('composer-error'), `Upload failed: ${errText(e)}`); }
  }

  function bindEnterToSend(ta, submit) {
    ta.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' && !ev.shiftKey && !ev.isComposing && !ev.altKey && !ev.ctrlKey && !ev.metaKey) {
        ev.preventDefault();
        submit();
      }
    });
    ta.addEventListener('input', () => autoGrow(ta));
  }

  // ------------------------------------------------------------------
  // Edit / delete
  // ------------------------------------------------------------------
  function buildEditForm(m) {
    const draft = S.editing && S.editing.id === m.id ? S.editing.draft : m.body;
    const ta = el('textarea', { name: 'body', 'data-testid': 'edit-message-input', 'aria-label': 'Edit message', rows: '2' });
    ta.value = draft;
    const errBox = el('div', { class: 'form-error', role: 'alert', hidden: true });
    if (S.editing && S.editing.error) setError(errBox, S.editing.error);
    const form = el('form', { class: 'edit-form', 'data-testid': 'edit-message-form', name: 'edit-message', novalidate: true },
      ta, errBox,
      el('div', { class: 'edit-actions' },
        el('button', { type: 'button', class: 'btn btn-outline small', 'data-testid': 'edit-message-cancel', onclick: cancelEdit }, 'Cancel'),
        el('button', { type: 'submit', class: 'btn btn-primary small', 'data-testid': 'edit-message-save' }, 'Save'),
        el('span', { class: 'muted small-text', text: 'Enter to save · Escape to cancel' })));
    ta.addEventListener('input', () => { if (S.editing) S.editing.draft = ta.value; });
    ta.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape') { ev.preventDefault(); ev.stopPropagation(); cancelEdit(); }
      else if (ev.key === 'Enter' && !ev.shiftKey && !ev.isComposing) { ev.preventDefault(); saveEdit(m.id); }
    });
    form.addEventListener('submit', (ev) => { ev.preventDefault(); saveEdit(m.id); });
    return form;
  }

  function rerenderAll() { renderMessages(); renderThread(); }

  function startEdit(m) {
    S.editing = { id: m.id, draft: m.body || '' };
    rerenderAll();
    const li = $(`.message[data-message-id="${m.id}"]`);
    if (li) focusEditBox(li);
  }

  function cancelEdit() {
    const id = S.editing && S.editing.id;
    S.editing = null;
    rerenderAll();
    const li = id && $(`.message[data-message-id="${id}"]`);
    if (li) li.focus();
  }

  async function saveEdit(id) {
    if (!S.editing || S.editing.id !== id) return;
    const body = S.editing.draft;
    const m = findMessage(id);
    if (!body.trim()) { S.editing.error = 'Message cannot be empty.'; rerenderAll(); const li = $(`.message[data-message-id="${id}"]`); if (li) focusEditBox(li); return; }
    if (m && body === m.body) { cancelEdit(); return; }
    try {
      const d = await api('PATCH', `/api/messages/${id}`, { body });
      S.editing = null;
      if (d.message) updateMessageEverywhere(id, d.message);
      else updateMessageEverywhere(id, { body, edited_at: new Date().toISOString() });
      rerenderAll();
    } catch (e) {
      if (S.editing) S.editing.error = errText(e);
      rerenderAll();
    }
  }

  let confirmAction = null;
  function confirmDelete(m) {
    byId('confirm-heading').textContent = 'Delete message';
    byId('confirm-text').textContent = 'Are you sure you want to delete this message? This cannot be undone.';
    const prev = byId('confirm-preview');
    prev.textContent = m.body || '';
    prev.hidden = !m.body;
    byId('confirm-ok').textContent = 'Delete';
    confirmAction = async () => {
      try {
        await api('DELETE', `/api/messages/${m.id}`);
        removeMessageEverywhere(m.id);
        rerenderAll();
      } catch (e) { toast(errText(e), true); }
    };
    openModal('confirm-modal');
    byId('confirm-ok').focus();
  }

  // ------------------------------------------------------------------
  // Reactions & emoji picker
  // ------------------------------------------------------------------
  const EMOJIS = [
    ['\u{1F44D}', 'thumbs up'], ['\u{1F44E}', 'thumbs down'], ['\u{1F600}', 'grinning face'], ['\u{1F602}', 'tears of joy'],
    ['\u{1F60D}', 'heart eyes'], ['\u{1F389}', 'party popper'], ['❤️', 'red heart'], ['\u{1F525}', 'fire'],
    ['\u{1F440}', 'eyes'], ['\u{1F64F}', 'folded hands'], ['\u{1F44F}', 'clapping hands'], ['\u{1F4AF}', 'hundred points'],
    ['✅', 'check mark'], ['❌', 'cross mark'], ['\u{1F680}', 'rocket'], ['\u{1F914}', 'thinking face'],
    ['\u{1F622}', 'crying face'], ['\u{1F62E}', 'surprised face'], ['\u{1F60E}', 'cool face'], ['\u{1F64C}', 'raising hands'],
    ['\u{1F4A1}', 'light bulb'], ['⭐', 'star'], ['\u{1F44B}', 'waving hand'], ['☕', 'coffee'],
  ];
  let picker = null;
  function closeEmojiPicker() {
    if (picker) { picker.remove(); picker = null; }
    $$('.msg-actions.force').forEach((n) => n.classList.remove('force'));
  }
  function openEmojiPicker(anchor, onPick) {
    closeEmojiPicker();
    const actions = anchor.closest('.msg-actions');
    if (actions) actions.classList.add('force');
    const grid = el('div', { class: 'emoji-grid', role: 'grid' });
    for (const [e, name] of EMOJIS) {
      grid.appendChild(el('button', {
        type: 'button', class: 'emoji-option', 'data-testid': 'emoji-option', 'data-emoji': e, title: name, 'aria-label': `${name} ${e}`,
        onclick: (ev) => { ev.stopPropagation(); closeEmojiPicker(); onPick(e); },
      }, e));
    }
    picker = el('div', { class: 'emoji-picker', 'data-testid': 'emoji-picker', role: 'dialog', 'aria-label': 'Pick a reaction' },
      el('div', { class: 'ep-title', text: 'Add a reaction' }), grid);
    document.body.appendChild(picker);
    const r = anchor.getBoundingClientRect();
    const pw = 292, ph = picker.offsetHeight || 150;
    let left = Math.min(window.innerWidth - pw - 8, Math.max(8, r.right - pw));
    let top = r.bottom + 6;
    if (top + ph > window.innerHeight - 8) top = Math.max(8, r.top - ph - 6);
    picker.style.left = left + 'px';
    picker.style.top = top + 'px';
    const first = $('.emoji-option', picker);
    if (first) first.focus({ preventScroll: true });
