  function setReactions(id, reactions) {
    updateMessageEverywhere(id, { reactions: reactions || [] });
  }

  async function addReaction(m, emoji) {
    try {
      const d = await api('POST', `/api/messages/${m.id}/reactions`, { emoji });
      if (d.reactions) setReactions(m.id, d.reactions);
      rerenderAll();
    } catch (e) { toast(errText(e), true); }
  }

  async function toggleReaction(m, emoji) {
    const cur = findMessage(m.id) || m;
    const r = (cur.reactions || []).find((x) => x.emoji === emoji);
    const mine = r && S.me && Array.isArray(r.user_ids) && r.user_ids.includes(S.me.id);
    try {
      const d = mine
        ? await api('DELETE', `/api/messages/${m.id}/reactions/${encodeURIComponent(emoji)}`)
        : await api('POST', `/api/messages/${m.id}/reactions`, { emoji });
      if (d.reactions) setReactions(m.id, d.reactions);
      rerenderAll();
    } catch (e) { toast(errText(e), true); }
  }

  // ------------------------------------------------------------------
  // Threads
  // ------------------------------------------------------------------
  async function openThread(parentId) {
    const parent = findMessage(parentId);
    byId('search-panel').hidden = true;
    S.thread = { parentId, channelId: parent ? parent.channel_id : S.currentChannelId, parent: parent || null, replies: [], loaded: false };
    byId('thread-panel').hidden = false;
    setError(byId('thread-error'), '');
    byId('thread-input').value = '';
    renderThread();
    byId('thread-input').focus();
    try {
      const d = await api('GET', `/api/messages/${parentId}/replies`);
      if (!S.thread || S.thread.parentId !== parentId) return;
      const replies = d.replies || d.messages || [];
      // merge any live replies that arrived meanwhile
      for (const r of S.thread.replies) if (!replies.some((x) => x.id === r.id)) replies.push(r);
      sortMsgs(replies);
      S.thread.replies = replies;
      S.thread.loaded = true;
      if (d.parent) S.thread.parent = d.parent;
      ensureAuthors(replies);
      const p = findInLists(parentId);
      if (p && replies.length > (Number(p.reply_count) || 0)) { p.reply_count = replies.length; renderMessages(); }
      renderThread(true);
    } catch (e) {
      setError(byId('thread-error'), `Could not load replies: ${errText(e)}`);
    }
  }

  function closeThread() {
    S.thread = null;
    byId('thread-panel').hidden = true;
    if (S.editing) { S.editing = null; renderMessages(); }
  }

  function renderThread(forceBottom) {
    const panel = byId('thread-panel');
    if (!S.thread) { panel.hidden = true; return; }
    const parentBox = byId('thread-parent');
    const list = byId('thread-replies');
    const scroller = byId('thread-scroll');
    const near = isNearBottom(scroller);
    const ch = S.channels.get(S.thread.channelId);
    byId('thread-subheading').textContent = ch ? channelTitle(ch) : '';
    parentBox.innerHTML = '';
    const parent = findInLists(S.thread.parentId) || S.thread.parent;
    if (parent) {
      const node = buildMessage(parent, true, true);
      node.classList.add('thread-parent-message');
      node.setAttribute('data-testid', 'thread-parent');
      // the edit toolbar on the parent should act on the main copy, keep only reaction
      parentBox.appendChild(node);
    } else {
      parentBox.appendChild(el('p', { class: 'muted', style: 'padding:12px 16px', text: 'Loading…' }));
    }
    const n = S.thread.replies.length;
    byId('thread-divider').textContent = n ? `${n} ${n === 1 ? 'reply' : 'replies'}` : (S.thread.loaded ? 'No replies yet — start the thread below.' : '');
    list.innerHTML = '';
    for (const r of S.thread.replies) list.appendChild(buildMessage(r, true));
    if (forceBottom || near) scroller.scrollTop = scroller.scrollHeight;
  }

  async function onThreadSubmit(ev) {
    if (ev) ev.preventDefault();
    if (!S.thread) return;
    const input = byId('thread-input');
    const errBox = byId('thread-error');
    const body = input.value;
    if (!body.trim()) { setError(errBox, 'Reply cannot be empty.'); input.focus(); return; }
    setError(errBox, '');
    const { parentId, channelId } = S.thread;
    const btn = byId('thread-send');
    btn.disabled = true;
    try {
      const d = await sendMessage(channelId, body, parentId, null, errBox);
      input.value = '';
      autoGrow(input);
      if (d.message) addReply(d.message, null);
    } catch (e) {
      setError(errBox, errText(e));
    } finally {
      btn.disabled = false;
      input.focus();
    }
  }

  // Add a reply to the open thread (if any) and bump the parent's reply count.
  function addReply(msg, authoritativeCount) {
    rememberUser(msg.author);
    const parentId = msg.parent_id;
    let isNew = true;
    if (S.thread && S.thread.parentId === parentId) {
      if (S.thread.replies.some((x) => x.id === msg.id)) {
        isNew = false;
        const r = S.thread.replies.find((x) => x.id === msg.id);
        Object.assign(r, msg);
      } else {
        S.thread.replies.push(msg);
        sortMsgs(S.thread.replies);
      }
    } else {
      isNew = !seenReplies.has(msg.id);
    }
    seenReplies.add(msg.id);
    const p = findInLists(parentId);
    if (p) {
      if (typeof authoritativeCount === 'number') p.reply_count = Math.max(authoritativeCount, isNew ? (Number(p.reply_count) || 0) : 0, authoritativeCount);
      else if (isNew) p.reply_count = (Number(p.reply_count) || 0) + 1;
    }
    if (S.thread && S.thread.parent && S.thread.parent.id === parentId && S.thread.parent !== p) {
      if (typeof authoritativeCount === 'number') S.thread.parent.reply_count = authoritativeCount;
      else if (isNew) S.thread.parent.reply_count = (Number(S.thread.parent.reply_count) || 0) + 1;
    }
    renderMessages();
    renderThread(true);
  }
  const seenReplies = new Set();

  // ------------------------------------------------------------------
  // WebSocket
  // ------------------------------------------------------------------
  function connectSocket() {
    if (!S.token) return;
    if (S.sock && (S.sock.readyState === WebSocket.OPEN || S.sock.readyState === WebSocket.CONNECTING)) return;
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    let sock;
    try {
      sock = new WebSocket(`${proto}://${location.host}/api/ws?token=${encodeURIComponent(S.token)}`);
    } catch (_) { scheduleReconnect(); return; }
    S.sock = sock;
    S.sockSubs = new Set();
    sock.onopen = () => {
      if (S.sock !== sock) return;
      const reconnect = S.everConnected;
      S.everConnected = true;
      S.sockRetry = 0;
      subscribeAll();
      clearInterval(S.pingTimer);
      S.pingTimer = setInterval(() => { if (sock.readyState === WebSocket.OPEN) sock.send(JSON.stringify({ type: 'ping' })); }, 25000);
      if (reconnect && S.currentChannelId) loadMessages(S.currentChannelId);
    };
    sock.onmessage = (ev) => {
      if (S.sock !== sock) return;
      let f;
      try { f = JSON.parse(ev.data); } catch (_) { return; }
      try { handleFrame(f); } catch (e) { console.error('frame handling failed', e, f); }
    };
    sock.onclose = () => {
      if (S.sock !== sock) return;
      S.sock = null;
      clearInterval(S.pingTimer);
      scheduleReconnect();
    };
    sock.onerror = () => { /* close will follow */ };
  }

  function scheduleReconnect() {
    if (!S.token) return;
    clearTimeout(S.sockTimer);
    const delay = Math.min(5000, 300 * Math.pow(2, S.sockRetry++));
    S.sockTimer = setTimeout(connectSocket, delay);
  }

  function sockSend(obj) {
    if (S.sock && S.sock.readyState === WebSocket.OPEN) { S.sock.send(JSON.stringify(obj)); return true; }
    return false;
  }

  function subscribeChannel(id) {
    if (!S.sock || S.sock.readyState !== WebSocket.OPEN || S.sockSubs.has(id)) return;
    const ch = S.channels.get(id);
    if (ch && ch.is_private && ch.is_member === false) return;
    S.sockSubs.add(id);
    if (S.lastSeq.has(id)) sockSend({ type: 'resume', channel_id: id, since_seq: S.lastSeq.get(id) });
    else sockSend({ type: 'subscribe', channel_id: id });
  }

  function subscribeAll() {
    if (S.currentChannelId) subscribeChannel(S.currentChannelId);
    for (const id of S.channels.keys()) subscribeChannel(id);
  }

  function handleFrame(f) {
    const type = f.type;
    if (!type) return;
    const cid = f.channel_id !== undefined ? Number(f.channel_id) : null;
    switch (type) {
      case 'pong':
      case 'hello':
      case 'resumed':
        if (type === 'resumed' && cid && typeof f.head_seq === 'number') bumpSeq(cid, f.head_seq);
        return;
      case 'subscribed':
        if (cid && typeof f.head_seq === 'number' && !S.lastSeq.has(cid)) S.lastSeq.set(cid, f.head_seq);
        if (cid === S.currentChannelId) markRead(cid);
        return;
      case 'resume.gap':
        if (cid === S.currentChannelId) loadMessages(cid);
        return;
      case 'error':
        if (cid) S.sockSubs.delete(cid);
        return;
      case 'user.updated':
        if (f.user) {
          rememberUser(f.user);
          if (S.me && f.user.id === S.me.id) { S.me = Object.assign({}, S.me, f.user); renderCurrentUser(); }
          rerenderAll();
        }
        return;
      default:
        break;
    }
    if (!cid) return;
    let fresh = true;
    if (typeof f.seq === 'number') {
      const prev = S.lastSeq.get(cid);
      fresh = prev === undefined || f.seq > prev;
      bumpSeq(cid, f.seq);
    }
    const isCurrent = cid === S.currentChannelId;
    switch (type) {
      case 'message.new': {
        const m = f.message;
        if (!m) return;
        if (m.parent_id) { addReply(m, typeof f.reply_count === 'number' ? f.reply_count : null); return; }
        const added = upsertTopLevel(m);
        ensureAuthors([m]);
        if (isCurrent) {
          renderMessages(S.me && m.author_id === S.me.id);
          if (document.visibilityState === 'visible') markRead(cid);
        } else if (added && fresh && S.channels.has(cid) && !(S.me && m.author_id === S.me.id)) {
          S.unread.set(cid, (S.unread.get(cid) || 0) + 1);
          if (S.me && Array.isArray(m.mentions) && m.mentions.includes(S.me.id)) S.mentionCount.set(cid, (S.mentionCount.get(cid) || 0) + 1);
          renderSidebar();
        }
        return;
      }
      case 'message.reply': {
        const m = f.message;
        if (!m) return;
        if (!m.parent_id && f.parent_id) m.parent_id = f.parent_id;
        ensureAuthors([m]);
        addReply(m, typeof f.reply_count === 'number' ? f.reply_count : null);
        return;
      }
      case 'message.updated': {
        const m = f.message;
        if (!m) return;
        rememberUser(m.author);
        const existing = findMessage(m.id);
        if (existing) {
          const patch = Object.assign({}, m);
          if (existing.reply_count && !m.reply_count) delete patch.reply_count;
          updateMessageEverywhere(m.id, patch);
          if (S.editing && S.editing.id === m.id && S.me && m.author_id === S.me.id) { /* keep editing */ }
          rerenderAll();
        }
        return;
      }
      case 'message.deleted': {
        const id = f.message_id !== undefined ? f.message_id : (f.message && f.message.id);
        if (id === undefined) return;
        if (findMessage(id)) { removeMessageEverywhere(id); rerenderAll(); }
        return;
      }
      case 'reaction.added':
      case 'reaction.removed': {
        if (f.message_id === undefined) return;
        if (Array.isArray(f.reactions)) {
          setReactions(f.message_id, f.reactions);
          rerenderAll();
        }
        return;
      }
      case 'channel.updated':
      case 'channel.archived':
      case 'channel.unarchived': {
        const prev = S.channels.get(cid);
        if (!prev && !f.channel) return;
        const next = Object.assign({}, prev || {}, f.channel || {});
        if (type === 'channel.archived') next.is_archived = true;
        if (type === 'channel.unarchived') next.is_archived = false;
        if (prev || (S.ws && next.workspace_id === S.ws.id)) S.channels.set(cid, next);
        renderSidebar();
        if (isCurrent) renderHeader();
        if (settingsChannelId === cid) renderChannelSettingsStatic();
        return;
      }
      case 'member.joined':
      case 'member.left': {
        if (f.user) rememberUser(f.user);
        if (settingsChannelId === cid) loadChannelMembers();
        if (S.me && f.user_id === S.me.id) {
          const ch = S.channels.get(cid);
          if (ch) ch.is_member = type === 'member.joined';
          if (type === 'member.joined' && !ch) refreshChannels();
        }
        return;
      }
      default:
        return;
    }
  }

  function bumpSeq(cid, seq) {
    const prev = S.lastSeq.get(cid);
    if (prev === undefined || seq > prev) S.lastSeq.set(cid, seq);
  }

  // ------------------------------------------------------------------
  // Modals
  // ------------------------------------------------------------------
  let modalReturnFocus = null;
  function openModal(id) {
    modalReturnFocus = document.activeElement;
    byId(id).hidden = false;
  }
  function closeModal(id) {
    const m = byId(id);
    if (!m || m.hidden) return;
    m.hidden = true;
    if (id === 'channel-settings-modal') settingsChannelId = null;
    if (modalReturnFocus && document.contains(modalReturnFocus)) { try { modalReturnFocus.focus(); } catch (_) { /* ignore */ } }
  }
  function closeAllModals() {
    ['create-channel-modal', 'channel-settings-modal', 'workspace-settings-modal', 'new-dm-modal', 'confirm-modal'].forEach(closeModal);
  }
  function topModal() {
    const ids = ['confirm-modal', 'new-dm-modal', 'create-channel-modal', 'channel-settings-modal', 'workspace-settings-modal'];
    return ids.find((id) => !byId(id).hidden) || null;
  }

  // ---- create channel ----
  function openCreateChannel() {
    if (!S.ws) { showEmptyState(true, false); return; }
    const form = byId('create-channel-form');
    form.reset();
    setError(byId('create-channel-error'), '');
    openModal('create-channel-modal');
    byId('create-channel-name').focus();
  }

  async function onCreateChannel(ev) {
    ev.preventDefault();
    const form = byId('create-channel-form');
    const errBox = byId('create-channel-error');
    const name = form.elements.name.value.trim();
    const topic = form.elements.topic.value.trim();
    const isPrivate = form.elements.is_private.checked;
    setError(errBox, '');
    if (!name) return setError(errBox, 'Please enter a channel name.');
    if (name.length > 32) return setError(errBox, 'Channel names must be 32 characters or fewer.');
    if (/\s/.test(name)) return setError(errBox, 'Channel names can\'t contain spaces. Use lowercase letters, digits and dashes (e.g. "plan-budget").');
    if (!/^[a-z0-9][a-z0-9_-]*$/.test(name)) return setError(errBox, 'Channel names may only contain lowercase letters, digits and dashes (e.g. "plan-budget").');
    const existing = Array.from(S.channels.values()).find((c) => !c.is_dm && c.name === name);
    const btn = byId('create-channel-submit');
    btn.disabled = true;
    try {
      const body = { name, is_private: isPrivate };
      if (topic) body.topic = topic;
      const d = await api('POST', `/api/workspaces/${encodeURIComponent(S.ws.slug)}/channels`, body);
      const ch = d.channel;
      S.channels.set(ch.id, ch);
      closeModal('create-channel-modal');
      renderSidebar();
      subscribeChannel(ch.id);
      openChannel(ch.id);
    } catch (e) {
      if (e.status === 409) setError(errBox, `A channel named #${name} already exists in this workspace. Please choose a different name.`);
      else if (e.status === 403) setError(errBox, isPrivate ? `You don't have permission to create private channels (${errText(e)}).` : `You don't have permission to create channels (${errText(e)}).`);
      else if (e.status === 400) setError(errBox, `Invalid channel name: ${errText(e)}`);
      else setError(errBox, errText(e));
      void existing;
    } finally {
      btn.disabled = false;
    }
  }

  // ---- channel settings ----
  let settingsChannelId = null;
  function openChannelSettings() {
    const ch = currentChannel();
    if (!ch) return;
    settingsChannelId = ch.id;
    setError(byId('channel-topic-error'), '');
    setError(byId('channel-add-member-error'), '');
    setError(byId('channel-archive-error'), '');
    byId('channel-add-member-ok').hidden = true;
    byId('channel-add-member-input').value = '';
    byId('channel-topic-input').value = ch.topic || '';
    renderChannelSettingsStatic();
    byId('channel-members-list').innerHTML = '';
    openModal('channel-settings-modal');
    loadChannelMembers();
  }

  function renderChannelSettingsStatic() {
    const ch = S.channels.get(settingsChannelId);
    if (!ch) return;
    byId('channel-settings-title').textContent = `${channelTitle(ch)} — details`;
    byId('archive-channel-btn').hidden = !!ch.is_archived;
    byId('unarchive-channel-btn').hidden = !ch.is_archived;
    byId('leave-channel-btn').hidden = !!ch.is_dm;
    byId('channel-add-member-form').hidden = !!ch.is_dm;
  }

  async function loadChannelMembers() {
    const cid = settingsChannelId;
    if (!cid) return;
    const list = byId('channel-members-list');
    try {
      const d = await api('GET', `/api/channels/${cid}/members`);
      if (settingsChannelId !== cid) return;
      list.innerHTML = '';
      const members = d.members || [];
      if (!members.length) list.appendChild(el('li', { class: 'muted', text: 'No members yet.' }));
      for (const raw of members) {
        const u = raw.user || raw;
        const uid = u.id !== undefined ? u.id : raw.user_id;
        rememberUser(Object.assign({}, u, { id: uid }));
        const isMe = S.me && uid === S.me.id;
        list.appendChild(el('li', { 'data-testid': 'channel-member-row', 'data-user-id': uid },
          avatarEl(u, userName(u)),
          el('div', { class: 'm-name' }, el('strong', { text: userName(u) + (isMe ? ' (you)' : '') }), el('span', { text: '@' + (u.username || '') })),
          isMe ? null : el('button', { type: 'button', class: 'btn btn-outline small', 'data-testid': 'message-user-btn', onclick: () => startDm(uid, u) }, 'Message')));
      }
    } catch (e) {
      list.innerHTML = '';
      list.appendChild(el('li', { class: 'muted', text: `Could not load members: ${errText(e)}` }));
    }
  }

  async function onChannelTopic(ev) {
    ev.preventDefault();
    const cid = settingsChannelId;
    const errBox = byId('channel-topic-error');
    const topic = byId('channel-topic-input').value;
    setError(errBox, '');
    if (topic.length > 250) return setError(errBox, 'Topic must be 250 characters or fewer.');
    try {
      const d = await api('PATCH', `/api/channels/${cid}`, { topic });
      const ch = Object.assign({}, S.channels.get(cid) || {}, d.channel || { topic });
      S.channels.set(cid, ch);
      renderHeader();
      renderSidebar();
      toast('Topic updated');
    } catch (e) { setError(errBox, errText(e)); }
  }

  async function onAddChannelMember(ev) {
    ev.preventDefault();
    const cid = settingsChannelId;
    const errBox = byId('channel-add-member-error');
    const ok = byId('channel-add-member-ok');
    ok.hidden = true;
    const username = byId('channel-add-member-input').value.trim().replace(/^@/, '');
    setError(errBox, '');
    if (!username) return setError(errBox, 'Enter a username to add.');
    try {
      const d = await api('POST', `/api/channels/${cid}/messages`, { body: `/invite @${username}` });
      byId('channel-add-member-input').value = '';
      ok.textContent = `Added @${(d.invited_user && d.invited_user.username) || username} to the channel.`;
      ok.hidden = false;
      loadChannelMembers();
    } catch (e) {
      setError(errBox, e.status === 404 ? `No user named @${username} was found.` : errText(e));
    }
  }

  async function onArchive(archive) {
    const cid = settingsChannelId;
    const errBox = byId('channel-archive-error');
    setError(errBox, '');
    try {
      const d = await api('POST', `/api/channels/${cid}/${archive ? 'archive' : 'unarchive'}`);
      const ch = Object.assign({}, S.channels.get(cid) || {}, d.channel || {}, { is_archived: archive });
      if (d.channel && d.channel.is_archived !== undefined) ch.is_archived = !!d.channel.is_archived;
      S.channels.set(cid, ch);
      renderChannelSettingsStatic();
      renderSidebar();
      renderHeader();
      toast(archive ? 'Channel archived' : 'Channel unarchived');
    } catch (e) {
      setError(errBox, e.status === 403 ? `Only the workspace owner can ${archive ? 'archive' : 'unarchive'} channels.` : errText(e));
    }
  }

  async function onLeaveChannel() {
    const cid = settingsChannelId;
    try {
      await api('POST', `/api/channels/${cid}/leave`);
      closeModal('channel-settings-modal');
      const ch = S.channels.get(cid);
      if (ch && ch.is_private) S.channels.delete(cid);
      else if (ch) ch.is_member = false;
      toast('You left the channel');
      await refreshChannels();
      if (!S.channels.has(cid)) {
        const g = Array.from(S.channels.values()).find((c) => c.name === 'general') || Array.from(S.channels.values())[0];
        if (g) openChannel(g.id);
      }
    } catch (e) { setError(byId('channel-archive-error'), errText(e)); }
  }

  // ---- DMs ----
  async function startDm(userId, user) {
    try {
      const d = await api('POST', '/api/dms', { user_id: userId });
      const cid = d.channel_id !== undefined ? d.channel_id : (d.channel && d.channel.id);
      closeAllModals();
      if (user) S.dmNames.set(cid, user);
      await refreshChannels();
      if (!S.channels.has(cid)) {
        S.channels.set(cid, Object.assign({ id: cid, is_dm: true, is_private: true, name: d.channel && d.channel.name || `dm-${cid}`, topic: '', is_archived: false }, d.channel || {}));
        renderSidebar();
      }
      subscribeChannel(cid);
      openChannel(cid);
    } catch (e) { toast(`Could not start a DM: ${errText(e)}`, true); }
  }

  async function openNewDm() {
    if (!S.ws) return;
    const list = byId('new-dm-list');
    list.innerHTML = '';
    setError(byId('new-dm-error'), '');
    openModal('new-dm-modal');
    const members = await loadWsMembers();
    const others = members.filter((m) => !S.me || m.user_id !== S.me.id);
    await Promise.all(others.map((m) => fetchUser(m.user_id)));
    list.innerHTML = '';
    if (!others.length) list.appendChild(el('li', { class: 'muted', text: 'Nobody else is in this workspace yet. Invite people from Workspace settings → Invitations.' }));
    for (const m of others) {
      const u = S.users.get(m.user_id) || { id: m.user_id, username: m.username, display_name: m.display_name };
      list.appendChild(el('li', null, avatarEl(u, userName(u)),
        el('div', { class: 'm-name' }, el('strong', { text: userName(u) }), el('span', { text: '@' + (u.username || '') })),
        el('button', { type: 'button', class: 'btn btn-primary small', 'data-testid': 'start-dm-btn', onclick: () => startDm(m.user_id, u) }, 'Message')));
    }
  }

  // ---- workspace settings ----
  function openWorkspaceSettings() {
    if (!S.ws) { showEmptyState(true, false); return; }
    openModal('workspace-settings-modal');
    selectSettingsTab('members');
  }

  function selectSettingsTab(name) {
    for (const t of $$('#workspace-settings-modal .tab')) {
      const on = t.dataset.tab === name;
      t.classList.toggle('active', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
    }
    for (const p of $$('#workspace-settings-modal .tab-pane')) p.hidden = p.dataset.pane !== name;
    if (name === 'members') renderMembersPane();
    if (name === 'invitations') { byId('create-invitation-form').hidden = true; byId('invitation-created').hidden = true; loadInvitations(); }
    if (name === 'general') {
      byId('workspace-name-input').value = S.ws.name || '';
      byId('workspace-join-mode').value = S.ws.join_mode || 'open';
      setError(byId('workspace-general-error'), '');
      byId('workspace-general-ok').hidden = true;
    }
  }

  async function renderMembersPane() {
    const list = byId('workspace-members-list');
    setError(byId('members-error'), '');
    const members = await loadWsMembers();
    await Promise.all(members.map((m) => (m.user || m.username) ? null : fetchUser(m.user_id)));
    list.innerHTML = '';
    const canManage = isWsAdmin();
    const roleOrder = { owner: 0, admin: 1, member: 2, guest: 3 };
    members.sort((a, b) => (roleOrder[a.role] - roleOrder[b.role]) || userName(S.users.get(a.user_id)).localeCompare(userName(S.users.get(b.user_id))));
    for (const m of members) {
      const u = S.users.get(m.user_id) || m.user || { id: m.user_id, username: m.username, display_name: m.display_name };
      const isMe = S.me && m.user_id === S.me.id;
      const badge = el('span', { class: `role-badge ${m.role}`, 'data-testid': 'role-badge', text: m.role });
      const row = el('li', { 'data-testid': 'member-row', 'data-user-id': m.user_id, 'data-role': m.role },
        avatarEl(u, userName(u)),
        el('div', { class: 'm-name' }, el('strong', { text: userName(u) + (isMe ? ' (you)' : '') }), el('span', { text: '@' + (u.username || '') })),
        badge);
      const select = el('select', { class: 'role-select', 'data-testid': 'role-select', name: 'role', 'aria-label': `Role for ${userName(u)}` });
      for (const r of ['admin', 'member', 'guest']) select.appendChild(el('option', { value: r, text: r[0].toUpperCase() + r.slice(1) }));
      if (m.role === 'owner') {
        select.appendChild(el('option', { value: 'owner', text: 'Owner' }));
        select.disabled = true;
      }
      select.value = m.role;
      if (!canManage || isMe) select.disabled = true;
      select.addEventListener('change', async () => {
        const role = select.value;
        try {
          const d = await api('PATCH', `/api/workspaces/${encodeURIComponent(S.ws.slug)}/members/${m.user_id}`, { role });
          m.role = (d.member && d.member.role) || role;
          badge.textContent = m.role;
          badge.className = `role-badge ${m.role}`;
          row.dataset.role = m.role;
          toast(`${userName(u)} is now ${m.role === 'admin' ? 'an' : 'a'} ${m.role}`);
        } catch (e) {
          select.value = m.role;
          setError(byId('members-error'), errText(e));
        }
      });
      row.appendChild(select);
      if (!isMe) row.appendChild(el('button', { type: 'button', class: 'btn btn-outline small', 'data-testid': 'message-user-btn', onclick: () => startDm(m.user_id, u) }, 'Message'));
      list.appendChild(row);
    }
    if (!members.length) list.appendChild(el('li', { class: 'muted', text: 'Could not load members.' }));
  }

  async function loadInvitations() {
    const list = byId('invitations-list');
    list.innerHTML = '';
    try {
      const d = await api('GET', `/api/workspaces/${encodeURIComponent(S.ws.slug)}/invitations`);
      const invs = d.invitations || [];
      if (!invs.length) list.appendChild(el('li', { class: 'muted', text: 'No active invitations. Create one to invite people.' }));
      for (const inv of invs) list.appendChild(invitationRow(inv));
    } catch (e) {
      list.appendChild(el('li', { class: 'muted', text: e.status === 403 ? 'Only workspace admins and owners can manage invitations.' : `Could not load invitations: ${errText(e)}` }));
    }
  }

  function invitationRow(inv) {
    const details = [];
    if (inv.max_uses !== undefined && inv.max_uses !== null) details.push(`${inv.uses || inv.use_count || 0}/${inv.max_uses} uses`);
    if (inv.expires_at) details.push(`expires ${fmtFull(inv.expires_at)}`);
    if (inv.invited_username) details.push(`for @${inv.invited_username}`);
    else if (inv.invited_user_id) details.push(`for user ${inv.invited_user_id}`);
    return el('li', { 'data-testid': 'invitation-row', 'data-code': inv.code },
      el('div', { class: 'm-name' }, el('code', { class: 'invitation-code', 'data-testid': 'invitation-code', text: inv.code }), el('span', { text: ' ' + details.join(' · ') })),
      el('button', { type: 'button', class: 'btn btn-outline small', onclick: () => copyText(inv.code) }, 'Copy'),
      el('button', { type: 'button', class: 'btn btn-outline small', 'data-testid': 'revoke-invitation-btn', onclick: () => revokeInvitation(inv.code) }, 'Revoke'));
  }

  function copyText(t) {
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(() => toast('Copied to clipboard'), () => toast(t));
    else toast(t);
  }

  async function revokeInvitation(code) {
    try {
      await api('DELETE', `/api/workspaces/${encodeURIComponent(S.ws.slug)}/invitations/${encodeURIComponent(code)}`);
      loadInvitations();
    } catch (e) { toast(errText(e), true); }
  }

  async function onCreateInvitation(ev) {
    ev.preventDefault();
    const form = byId('create-invitation-form');
    const errBox = byId('create-invitation-error');
    setError(errBox, '');
    const body = {};
    const mu = parseInt(form.elements.max_uses.value, 10);
    if (mu > 0) body.max_uses = mu;
    const exp = parseInt(form.elements.expires_in_seconds.value, 10);
    if (exp > 0) body.expires_in_seconds = exp;
    const target = form.elements.invited_username.value.trim().replace(/^@/, '');
    if (target) body.invited_username = target;
    try {
      const d = await api('POST', `/api/workspaces/${encodeURIComponent(S.ws.slug)}/invitations`, body);
      const inv = d.invitation || {};
      const box = byId('invitation-created');
      box.innerHTML = '';
      box.appendChild(document.createTextNode('Invitation created — share this code: '));
      box.appendChild(el('code', { class: 'invitation-code', 'data-testid': 'new-invitation-code', text: inv.code || '' }));
      box.hidden = false;
      form.hidden = true;
      form.reset();
      loadInvitations();
    } catch (e) {
      setError(errBox, e.status === 403 ? 'Only workspace admins and owners can create invitations.' : errText(e));
    }
  }

  async function onWorkspaceGeneral(ev) {
    ev.preventDefault();
    const errBox = byId('workspace-general-error');
    const ok = byId('workspace-general-ok');
    ok.hidden = true;
    setError(errBox, '');
    const name = byId('workspace-name-input').value.trim();
    const join_mode = byId('workspace-join-mode').value;
    if (!name) return setError(errBox, 'Workspace name cannot be empty.');
    try {
      const d = await api('PATCH', `/api/workspaces/${encodeURIComponent(S.ws.slug)}`, { name, join_mode });
      S.ws = Object.assign({}, S.ws, d.workspace || { name, join_mode });
      const idx = S.workspaces.findIndex((w) => w.slug === S.ws.slug);
      if (idx >= 0) S.workspaces[idx] = S.ws;
      byId('workspace-name').textContent = S.ws.name;
      document.title = `${S.ws.name} — Huddle`;
      renderRail();
      ok.textContent = 'Workspace settings saved.';
      ok.hidden = false;
    } catch (e) {
      setError(errBox, e.status === 403 ? 'Only workspace admins and owners can change these settings.' : errText(e));
    }
  }

  // ---- create / join workspace ----
  function slugify(s) {
    return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 32);
  }

  async function onCreateWorkspace(ev) {
    ev.preventDefault();
    const form = byId('workspace-create-form');
    const errBox = byId('workspace-create-error');
    setError(errBox, '');
    const name = form.elements.name.value.trim();
    let slug = form.elements.slug.value.trim();
    if (!slug && name) { slug = slugify(name); form.elements.slug.value = slug; }
    if (!name) return setError(errBox, 'Please enter a workspace name.');
