def on_redis_message(self, channel, data):
    try:
        obj = json.loads(data)
    except ValueError:
        return
    # Ignore traffic from another cluster (different db) sharing the same Redis.
    if not isinstance(obj, dict) or obj.get("c") != CLUSTER_TAG:
        return
    if channel == REDIS_EVENTS:
        self.stats["redis_frames"] += 1
        if isinstance(obj.get("f"), dict):
            self.on_frame(obj["f"], None)
    elif channel == REDIS_GLOBAL:
        self.on_global(obj.get("gid"), obj.get("f") or {})

